update public.article_cache set translation = '{"texts": ["Sightings of the Persian leopard in the Caucasus are extremely rare — only three times in Georgia and ten times in Armenia over the past 20 years, with fewer than 1,100 individuals left worldwide.", "One leopard in particular has drawn attention: a leopard named Aren, who is presumed to have traveled about 240 kilometers from Armenia to Georgia on three legs, across cold and rugged mountain terrain, likely injured by landmines.", "The Caucasus region still holds minefields from past conflicts, and thousands of kilometers of Soviet-era barbed wire also pose dangers to leopards, bears, deer, and people alike along its borders.", "The NGO NACRES, based in Georgia, operates with a staff of just three people led by zoologist Bejan Lortkipanidze, and due to severe funding shortages, their work is largely limited to monitoring.", "Lortkipanidze said that if he had unlimited resources, he would set up a monitoring center and prioritize education outreach — visiting remote villages to teach locals what to do when they encounter a leopard and reducing human-wildlife conflict.", "WWF is also monitoring leopards in the same area, but both organizations face growing difficulties as conservation funding tightens globally; still, the survival of leopards like Aren and the work of those protecting them continues."], "sentences": [{"text": "코카서스 지역에서 페르시아표범을 보는 일은 매우 드뭅니다.", "translation": "Seeing a Persian leopard in the Caucasus region is very rare.", "vocab": [{"ko": "코카서스", "en": "Caucasus"}, {"ko": "페르시아표범", "en": "Persian leopard"}, {"ko": "드물다", "en": "to be rare"}], "analysis": [{"type": "grammar", "label": "~는 일", "exp": "Nominalizes an action (보다 ''to see'') into a noun phrase meaning ''the act/matter of seeing''; conveys the event itself as a countable noun.", "example_in_sentence": "페르시아표범을 보는 일"}]}, {"text": "지난 20년 동안 조지아에서는 세 번, 아르메니아에서는 열 번만 목격되었습니다.", "translation": "Over the past 20 years, it has been sighted only three times in Georgia and ten times in Armenia.", "vocab": [{"ko": "지난", "en": "past"}, {"ko": "동안", "en": "during; over"}, {"ko": "목격되다", "en": "to be sighted"}], "analysis": [{"type": "grammar", "label": "~만", "exp": "Particle limiting the quantity to an exclusive number; emphasizes ''only'' and ''no more than'' the stated amount.", "example_in_sentence": "세 번, 아르메니아에서는 열 번만"}, {"type": "grammar", "label": "~되다 (passive)", "exp": "목격하다 ''to sight'' → 목격되다 ''to be sighted'' → 목격되었습니다 ''was sighted''.", "example_in_sentence": "목격되었습니다"}]}, {"text": "현재 페르시아표범은 전 세계에 1,100마리도 남지 않은 멸종 위기 동물입니다.", "translation": "Currently, the Persian leopard is an endangered animal with fewer than 1,100 individuals remaining in the entire world.", "vocab": [{"ko": "현재", "en": "currently; at present"}, {"ko": "남다", "en": "to remain; to be left"}, {"ko": "멸종 위기", "en": "endangerment; threat of extinction"}], "analysis": [{"type": "grammar", "label": "~도 + negation", "exp": "Particle emphasizing surprise or extremity in negative contexts; 1,100마리도 남지 않다 = ''not even 1,100 individuals remain'' (even fewer than expected).", "example_in_sentence": "1,100마리도 남지 않은"}, {"type": "grammar", "label": "~은/ㄴ (attributive adjective form)", "exp": "Modifies following noun; 남지 않은 ''not remaining'' becomes an adjective phrase describing 동물 ''animal''.", "example_in_sentence": "남지 않은 멸종 위기 동물"}]}, {"text": "그중에서 특히 주목받는 표범이 있습니다.", "translation": "Among them, there is a leopard that particularly draws attention.", "vocab": [{"ko": "그중에서", "en": "among them; from among those"}, {"ko": "특히", "en": "particularly; especially"}, {"ko": "주목받다", "en": "to draw/receive attention"}], "analysis": [{"type": "grammar", "label": "~는/은 (attributive present tense)", "exp": "Modifies noun; 주목받다 + ~는 describes an ongoing or habitual state; 주목받는 표범 = ''a leopard that draws attention''.", "example_in_sentence": "주목받는 표범"}]}, {"text": "연구자들이 ''아렌''이라고 이름을 붙인 이 표범은 세 개의 다리로 약 240킬로미터를 이동한 것으로 추정됩니다.", "translation": "This leopard, which researchers named ''Aren,'' is estimated to have traveled approximately 240 kilometers on three legs.", "vocab": [{"ko": "연구자", "en": "researcher"}, {"ko": "붙이다", "en": "to attach; to give (a name)"}, {"ko": "이동하다", "en": "to move; to travel"}], "analysis": [{"type": "grammar", "label": "~(이)라고 이름을 붙이다", "exp": "''To name (something) X'': ''아렌''이라고 이름을 붙이다 ''to name it Aren''.", "example_in_sentence": "''아렌''이라고 이름을 붙인"}, {"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 붙이다 → 이름을 붙인 이 표범 ''this leopard (that researchers) named''.", "example_in_sentence": "붙인 이 표범"}, {"type": "grammar", "label": "~으로/로", "exp": "Instrumental particle indicating means or tool; 다리로 ''by/with legs'' specifies how the leopard moved.", "example_in_sentence": "세 개의 다리로"}, {"type": "expression", "label": "~은/ㄴ 것으로 추정되다", "exp": "Expression meaning ''is estimated/presumed to have''; combines nominalizer ~은/ㄴ 것 with 추정되다 ''to be estimated''.", "example_in_sentence": "이동한 것으로 추정됩니다"}]}, {"text": "아르메니아에서 조지아까지 춥고 험한 산악 지형을 건넌 것입니다.", "translation": "That means it crossed cold, rugged mountain terrain from Armenia to Georgia.", "vocab": [{"ko": "험하다", "en": "to be rugged; to be harsh"}, {"ko": "산악", "en": "mountainous"}, {"ko": "건너다", "en": "to cross; to traverse"}], "analysis": [{"type": "grammar", "label": "~고 (coordinating adjectives)", "exp": "Connects two adjectives 춥다 ''cold'' + 험하다 ''rugged'' to modify the same noun; emphasizes multiple qualities.", "example_in_sentence": "춥고 험한 산악 지형"}, {"type": "grammar", "label": "~(으)ㄴ 것이다", "exp": "Explains what happened: 건너다 → 건넌 것입니다 ''(that is,) it crossed''.", "example_in_sentence": "건넌 것입니다"}]}, {"text": "아렌이 다리를 잃게 된 것은 코카서스 지역 곳곳에 남아 있는 지뢰 때문인 것으로 보입니다.", "translation": "It appears that Aren lost its leg due to landmines remaining throughout the Caucasus region.", "vocab": [{"ko": "잃다", "en": "to lose"}, {"ko": "곳곳", "en": "here and there; throughout"}, {"ko": "남다", "en": "to remain; to be left"}, {"ko": "지뢰", "en": "landmine"}], "analysis": [{"type": "grammar", "label": "~게 되다", "exp": "Auxiliary verb phrase indicating a change of state or coming to be in a condition; 잃게 되다 ''to come to lose'' emphasizes the unintended or accidental nature.", "example_in_sentence": "다리를 잃게 된"}, {"type": "expression", "label": "N 때문인 것으로 보이다", "exp": "''It seems to be because of N'': 지뢰 때문인 것으로 보입니다 ''it appears to be due to landmines''.", "example_in_sentence": "지뢰 때문인 것으로 보입니다"}, {"type": "grammar", "label": "~아/어 있는", "exp": "남다 → 남아 있다 ''to remain (a state)'' → 남아 있는 지뢰 ''landmines that remain''.", "example_in_sentence": "남아 있는 지뢰"}]}, {"text": "코카서스 지역에는 과거 분쟁으로 인한 지뢰밭이 여전히 남아 있습니다.", "translation": "In the Caucasus region, minefields caused by past conflicts still remain.", "vocab": [{"ko": "과거", "en": "past"}, {"ko": "분쟁", "en": "conflict; dispute"}, {"ko": "지뢰밭", "en": "minefield"}], "analysis": [{"type": "expression", "label": "~으로 인한", "exp": "Preposition-like expression meaning ''caused by; due to''; 분쟁으로 인한 지뢰밭 = ''minefields caused by conflict''.", "example_in_sentence": "과거 분쟁으로 인한 지뢰밭"}, {"type": "grammar", "label": "~아/어 있다", "exp": "Shows a state that continues: 남다 → 남아 있습니다 ''(minefields) still remain''.", "example_in_sentence": "남아 있습니다"}]}, {"text": "또한 소련 시대부터 수천 킬로미터에 걸쳐 설치된 철조망도 표범, 곰, 사슴 등 야생동물에게 위험합니다.", "translation": "Additionally, barbed wire installed over thousands of kilometers since the Soviet era is also dangerous to wildlife such as leopards, bears, and deer.", "vocab": [{"ko": "소련", "en": "Soviet Union"}, {"ko": "시대", "en": "era; period"}, {"ko": "수천", "en": "thousands"}], "analysis": [{"type": "grammar", "label": "~부터", "exp": "Starting point particle marking temporal origin; 시대부터 ''from/since the era'' indicates a starting time extending to present.", "example_in_sentence": "소련 시대부터"}, {"type": "grammar", "label": "~에 걸쳐", "exp": "Expression meaning ''spanning; over''; indicates extent or distribution over a distance; 수천 킬로미터에 걸쳐 ''spanning thousands of kilometers''.", "example_in_sentence": "수천 킬로미터에 걸쳐"}, {"type": "grammar", "label": "~도", "exp": "Particle meaning ''also''; marks addition of another subject or element; 철조망도 ''(not only landmines but) barbed wire also''.", "example_in_sentence": "철조망도"}, {"type": "grammar", "label": "~은/ㄴ (attributive past tense)", "exp": "Modifies noun; 설치된 철조망 ''barbed wire (that was) installed'' describes a completed action.", "example_in_sentence": "설치된 철조망"}]}, {"text": "국경선을 따라 놓인 이러한 시설들은 사람과 동물 모두에게 위협이 되고 있습니다.", "translation": "These facilities placed along the border are becoming a threat to both people and animals.", "vocab": [{"ko": "국경선", "en": "border line"}, {"ko": "놓이다", "en": "to be placed; to be laid"}, {"ko": "위협", "en": "threat"}], "analysis": [{"type": "expression", "label": "~을/를 따라", "exp": "Expression meaning ''along; following''; 국경선을 따라 ''along the border line'' indicates spatial arrangement.", "example_in_sentence": "국경선을 따라"}, {"type": "grammar", "label": "~은/ㄴ (attributive past tense)", "exp": "Modifies noun; 놓인 시설들 ''facilities (that were) placed'' describes completed placement action.", "example_in_sentence": "놓인 이러한 시설들"}, {"type": "expression", "label": "A와 B 모두에게", "exp": "Expression meaning ''to both A and B''; distributes the target to two recipients: 사람과 동물 모두에게 ''to both people and animals''.", "example_in_sentence": "사람과 동물 모두에게"}, {"type": "grammar", "label": "~이 되다 + ~고 있다", "exp": "Auxiliary combination: 되다 ''to become'' + progressive ~고 있다 ''is becoming''; describes an ongoing change of state.", "example_in_sentence": "위협이 되고 있습니다"}]}, {"text": "이 지역에서 야생동물을 보호하기 위해 노력하는 단체가 있습니다.", "translation": "There is an organization working in this region to protect wildlife.", "vocab": [{"ko": "보호하다", "en": "to protect"}, {"ko": "노력하다", "en": "to make effort; to strive"}], "analysis": [{"type": "grammar", "label": "~기 위해", "exp": "Purpose/intention construction; 보호하기 위해 ''in order to protect'' indicates purposive motivation for 노력하다 ''to make effort''.", "example_in_sentence": "보호하기 위해"}, {"type": "grammar", "label": "~는 (attributive present tense)", "exp": "Modifies noun; 노력하는 단체 ''organization (that) makes effort'' describes an ongoing or habitual action.", "example_in_sentence": "노력하는 단체"}]}, {"text": "조지아에 설립된 비정부기구 나크레스는 동물학자 베잔 로르트키파니제를 중심으로 단 세 명이 일하고 있습니다.", "translation": "Nacres, an NGO founded in Georgia, has just three people working there, led by zoologist Bejan Lortkipanidze.", "vocab": [{"ko": "설립되다", "en": "to be established; to be founded"}, {"ko": "비정부기구", "en": "NGO; non-governmental organization"}, {"ko": "동물학자", "en": "zoologist"}], "analysis": [{"type": "grammar", "label": "~은/ㄴ (attributive past tense)", "exp": "Modifies noun; 설립된 비정부기구 ''NGO (that was) established'' describes a completed action.", "example_in_sentence": "설립된 비정부기구"}, {"type": "expression", "label": "~을/를 중심으로", "exp": "Expression meaning ''centered on; with ~ as the center''; X를 중심으로 ''with X as the center/focus''.", "example_in_sentence": "동물학자 베잔 로르트키파니제를 중심으로"}, {"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates ongoing or habitual action; 일하고 있습니다 ''are working'' emphasizes current continuous state.", "example_in_sentence": "일하고 있습니다"}]}, {"text": "예산이 매우 부족하기 때문에 표범을 직접 보호하기보다는 주로 모니터링을 하고 있습니다.", "translation": "Because the budget is very limited, rather than directly protecting the leopard, they mainly conduct monitoring.", "vocab": [{"ko": "예산", "en": "budget"}, {"ko": "부족하다", "en": "to be insufficient; to be lacking"}, {"ko": "직접", "en": "directly"}, {"ko": "모니터링", "en": "monitoring"}], "analysis": [{"type": "grammar", "label": "~기 때문에", "exp": "Reason/cause construction; 부족하기 때문에 ''because of being insufficient'' provides causal explanation for the action change.", "example_in_sentence": "부족하기 때문에"}, {"type": "expression", "label": "~기보다는", "exp": "Contrastive construction meaning ''rather than ~''; 보호하기보다는 ''(rather than protecting directly) instead''.", "example_in_sentence": "보호하기보다는"}]}, {"text": "로르트키파니제는 충분한 자원이 생긴다면 모니터링 센터를 세우고 싶다고 했습니다.", "translation": "Lortkipanidze said that if sufficient resources were available, he would want to establish a monitoring center.", "vocab": [{"ko": "충분하다", "en": "to be sufficient; to be enough"}, {"ko": "자원", "en": "resources"}, {"ko": "생기다", "en": "to occur; to arise; to become available"}], "analysis": [{"type": "grammar", "label": "~ㄴ다면 (conditional)", "exp": "Conditional connective; 생긴다면 ''if (resources) were to occur/be available'' expresses hypothetical condition.", "example_in_sentence": "생긴다면"}, {"type": "grammar", "label": "~고 싶다 (desiderative)", "exp": "Auxiliary expressing wish or desire; 세우고 싶다 ''want to establish'' conveys personal aspiration.", "example_in_sentence": "세우고 싶다고"}, {"type": "grammar", "label": "~다고 하다 (reported speech)", "exp": "Marks indirect quotation or reported statement; conveyed what was said in past tense context.", "example_in_sentence": "싶다고 했습니다"}]}, {"text": "또한 투셰티 같은 외딴 지역의 마을을 찾아가 주민들에게 표범을 발견했을 때 어떻게 행동해야 하는지 알리고 싶어 합니다.", "translation": "He also wants to visit villages in remote areas like Tusheti and inform residents how they should behave when a leopard is discovered.", "vocab": [{"ko": "투셰티", "en": "Tusheti (region)"}, {"ko": "같다", "en": "to be like; such as"}, {"ko": "외딴", "en": "remote; isolated"}, {"ko": "찾아가다", "en": "to visit; to go find"}], "analysis": [{"type": "grammar", "label": "~았/었을 때", "exp": "''When (something has happened)'': 발견하다 → 발견했을 때 ''when (they) spot (a leopard)''.", "example_in_sentence": "발견했을 때"}, {"type": "expression", "label": "~아/어야 하다", "exp": "''Should'': 행동하다 → 행동해야 하다. With ~는지: 어떻게 행동해야 하는지 ''how (they) should act''.", "example_in_sentence": "행동해야 하는지"}, {"type": "grammar", "label": "~고 싶어 하다", "exp": "''Want to'' for a third person: 알리다 → 알리고 싶어 합니다 ''wants to let (them) know''.", "example_in_sentence": "알리고 싶어 합니다"}]}, {"text": "사람과 야생동물 사이의 갈등을 줄이기 위한 교육이 필요하다고 보는 것입니다.", "translation": "He believes that education is necessary to reduce conflict between people and wildlife.", "vocab": [{"ko": "사이", "en": "between"}, {"ko": "갈등", "en": "conflict"}, {"ko": "줄이다", "en": "to reduce; to lessen"}], "analysis": [{"type": "expression", "label": "A와/과 B 사이의", "exp": "''Between A and B'': 사람과 야생동물 사이의 갈등 ''conflict between people and wildlife''.", "example_in_sentence": "사람과 야생동물 사이의"}, {"type": "grammar", "label": "~기 위한", "exp": "Purpose/intention marker; 줄이기 위한 ''(designed/made) for reducing'' indicates purposive modification.", "example_in_sentence": "줄이기 위한 교육"}, {"type": "expression", "label": "~다고 보다", "exp": "Expression meaning ''to believe; to think/regard''; 필요하다고 보다 ''regards as necessary; believes is necessary''.", "example_in_sentence": "필요하다고 보는 것입니다"}]}, {"text": "나크레스와 함께 세계자연기금도 같은 지역에 카메라를 설치하며 표범을 모니터링하고 있습니다.", "translation": "Together with Nacres, the World Wildlife Fund is also installing cameras in the same region and monitoring leopards.", "vocab": [{"ko": "함께", "en": "together; with"}, {"ko": "세계자연기금", "en": "World Wildlife Fund"}, {"ko": "설치하다", "en": "to install"}], "analysis": [{"type": "grammar", "label": "~(으)며", "exp": "Written connector ''and / while'': 설치하다 → 설치하며 ''installing (cameras) and…''.", "example_in_sentence": "설치하며"}, {"type": "grammar", "label": "~고 있다 (progressive aspect)", "exp": "Indicates ongoing action; 모니터링하고 있습니다 ''are monitoring'' emphasizes continuous/habitual state.", "example_in_sentence": "모니터링하고 있습니다"}]}, {"text": "하지만 전 세계적으로 환경 보호 분야의 자금이 줄어들면서 두 단체 모두 어려운 상황에서 활동을 이어 가고 있습니다.", "translation": "However, as environmental protection funding decreases globally, both organizations continue their activities in difficult circumstances.", "vocab": [{"ko": "전 세계적으로", "en": "globally; worldwide"}, {"ko": "환경 보호", "en": "environmental protection"}, {"ko": "분야", "en": "field; domain"}, {"ko": "자금", "en": "funding; capital"}], "analysis": [{"type": "grammar", "label": "~(으)면서", "exp": "''As (one thing changes, another happens)'': 줄어들다 → 줄어들면서 ''as (funding) shrinks''.", "example_in_sentence": "줄어들면서"}, {"type": "expression", "label": "~ㄴ/은 상황에서", "exp": "Expression meaning ''in a ~ situation''; 어려운 상황에서 ''in difficult circumstances''.", "example_in_sentence": "어려운 상황에서"}, {"type": "expression", "label": "~을/를 이어 가다", "exp": "Expression meaning ''to continue; to carry on''; 활동을 이어 가다 ''to continue activities/work''.", "example_in_sentence": "활동을 이어 가고"}]}, {"text": "그럼에도 아렌처럼 극한의 환경에서 살아남은 표범과 이를 지키려는 사람들의 노력은 계속되고 있습니다.", "translation": "Even so, leopards like Aren that have survived extreme conditions, and the efforts of the people trying to protect them, carry on.", "vocab": [{"ko": "그럼에도", "en": "nevertheless; despite that"}, {"ko": "극한", "en": "extreme; extremity"}, {"ko": "살아남다", "en": "to survive"}], "analysis": [{"type": "expression", "label": "그럼에도", "exp": "''Even so; nevertheless'' (short for 그러함에도 ''despite that'').", "example_in_sentence": "그럼에도"}, {"type": "grammar", "label": "~(으)ㄴ (past modifier)", "exp": "Past modifier: 살아남다 → 살아남은 표범 ''leopards that survived''.", "example_in_sentence": "살아남은 표범"}]}], "version": "s6"}', vocab = '[{"ko": "코카서스", "en": "Caucasus", "note": ""}, {"ko": "페르시아표범", "en": "Persian leopard", "note": ""}, {"ko": "드물다", "en": "to be rare", "note": ""}, {"ko": "지난", "en": "past", "note": ""}, {"ko": "동안", "en": "during; over", "note": ""}, {"ko": "목격되다", "en": "to be sighted", "note": ""}, {"ko": "현재", "en": "currently; at present", "note": ""}, {"ko": "남다", "en": "to remain; to be left", "note": ""}, {"ko": "멸종 위기", "en": "endangerment; threat of extinction", "note": ""}, {"ko": "그중에서", "en": "among them; from among those", "note": ""}, {"ko": "특히", "en": "particularly; especially", "note": ""}, {"ko": "주목받다", "en": "to draw/receive attention", "note": ""}, {"ko": "연구자", "en": "researcher", "note": ""}, {"ko": "붙이다", "en": "to attach; to give (a name)", "note": ""}, {"ko": "이동하다", "en": "to move; to travel", "note": ""}, {"ko": "험하다", "en": "to be rugged; to be harsh", "note": ""}, {"ko": "산악", "en": "mountainous", "note": ""}, {"ko": "건너다", "en": "to cross; to traverse", "note": ""}, {"ko": "잃다", "en": "to lose", "note": ""}, {"ko": "곳곳", "en": "here and there; throughout", "note": ""}, {"ko": "지뢰", "en": "landmine", "note": ""}, {"ko": "과거", "en": "past", "note": ""}, {"ko": "분쟁", "en": "conflict; dispute", "note": ""}, {"ko": "지뢰밭", "en": "minefield", "note": ""}, {"ko": "소련", "en": "Soviet Union", "note": ""}, {"ko": "시대", "en": "era; period", "note": ""}, {"ko": "수천", "en": "thousands", "note": ""}, {"ko": "국경선", "en": "border line", "note": ""}, {"ko": "놓이다", "en": "to be placed; to be laid", "note": ""}, {"ko": "위협", "en": "threat", "note": ""}, {"ko": "보호하다", "en": "to protect", "note": ""}, {"ko": "노력하다", "en": "to make effort; to strive", "note": ""}, {"ko": "설립되다", "en": "to be established; to be founded", "note": ""}, {"ko": "비정부기구", "en": "NGO; non-governmental organization", "note": ""}, {"ko": "동물학자", "en": "zoologist", "note": ""}, {"ko": "예산", "en": "budget", "note": ""}, {"ko": "부족하다", "en": "to be insufficient; to be lacking", "note": ""}, {"ko": "직접", "en": "directly", "note": ""}, {"ko": "모니터링", "en": "monitoring", "note": ""}, {"ko": "충분하다", "en": "to be sufficient; to be enough", "note": ""}, {"ko": "자원", "en": "resources", "note": ""}, {"ko": "생기다", "en": "to occur; to arise; to become available", "note": ""}, {"ko": "투셰티", "en": "Tusheti (region)", "note": ""}, {"ko": "같다", "en": "to be like; such as", "note": ""}, {"ko": "외딴", "en": "remote; isolated", "note": ""}, {"ko": "찾아가다", "en": "to visit; to go find", "note": ""}, {"ko": "사이", "en": "between", "note": ""}, {"ko": "갈등", "en": "conflict", "note": ""}, {"ko": "줄이다", "en": "to reduce; to lessen", "note": ""}, {"ko": "함께", "en": "together; with", "note": ""}, {"ko": "세계자연기금", "en": "World Wildlife Fund", "note": ""}, {"ko": "설치하다", "en": "to install", "note": ""}, {"ko": "전 세계적으로", "en": "globally; worldwide", "note": ""}, {"ko": "환경 보호", "en": "environmental protection", "note": ""}, {"ko": "분야", "en": "field; domain", "note": ""}, {"ko": "자금", "en": "funding; capital", "note": ""}, {"ko": "그럼에도", "en": "nevertheless; despite that", "note": ""}, {"ko": "극한", "en": "extreme; extremity", "note": ""}, {"ko": "살아남다", "en": "to survive", "note": ""}]', grammar = '{"patterns": [{"name": "~는 일", "level": "Intermediate", "exp": "Nominalizes an action (보다 ''to see'') into a noun phrase meaning ''the act/matter of seeing''; conveys the event itself as a countable noun.", "ex_ko": "코카서스 지역에서 페르시아표범을 보는 일은 매우 드뭅니다.", "ex_en": "Seeing a Persian leopard in the Caucasus region is very rare."}, {"name": "~만", "level": "Intermediate", "exp": "Particle limiting the quantity to an exclusive number; emphasizes ''only'' and ''no more than'' the stated amount.", "ex_ko": "지난 20년 동안 조지아에서는 세 번, 아르메니아에서는 열 번만 목격되었습니다.", "ex_en": "Over the past 20 years, it has been sighted only three times in Georgia and ten times in Armenia."}, {"name": "~되다 (passive)", "level": "Intermediate", "exp": "목격하다 ''to sight'' → 목격되다 ''to be sighted'' → 목격되었습니다 ''was sighted''.", "ex_ko": "지난 20년 동안 조지아에서는 세 번, 아르메니아에서는 열 번만 목격되었습니다.", "ex_en": "Over the past 20 years, it has been sighted only three times in Georgia and ten times in Armenia."}, {"name": "~도 + negation", "level": "Intermediate", "exp": "Particle emphasizing surprise or extremity in negative contexts; 1,100마리도 남지 않다 = ''not even 1,100 individuals remain'' (even fewer than expected).", "ex_ko": "현재 페르시아표범은 전 세계에 1,100마리도 남지 않은 멸종 위기 동물입니다.", "ex_en": "Currently, the Persian leopard is an endangered animal with fewer than 1,100 individuals remaining in the entire world."}, {"name": "~은/ㄴ (attributive adjective form)", "level": "Intermediate", "exp": "Modifies following noun; 남지 않은 ''not remaining'' becomes an adjective phrase describing 동물 ''animal''.", "ex_ko": "현재 페르시아표범은 전 세계에 1,100마리도 남지 않은 멸종 위기 동물입니다.", "ex_en": "Currently, the Persian leopard is an endangered animal with fewer than 1,100 individuals remaining in the entire world."}, {"name": "~는/은 (attributive present tense)", "level": "Intermediate", "exp": "Modifies noun; 주목받다 + ~는 describes an ongoing or habitual state; 주목받는 표범 = ''a leopard that draws attention''.", "ex_ko": "그중에서 특히 주목받는 표범이 있습니다.", "ex_en": "Among them, there is a leopard that particularly draws attention."}, {"name": "~(이)라고 이름을 붙이다", "level": "Intermediate", "exp": "''To name (something) X'': ''아렌''이라고 이름을 붙이다 ''to name it Aren''.", "ex_ko": "연구자들이 ''아렌''이라고 이름을 붙인 이 표범은 세 개의 다리로 약 240킬로미터를 이동한 것으로 추정됩니다.", "ex_en": "This leopard, which researchers named ''Aren,'' is estimated to have traveled approximately 240 kilometers on three legs."}, {"name": "~(으)ㄴ (past modifier)", "level": "Intermediate", "exp": "Past modifier: 붙이다 → 이름을 붙인 이 표범 ''this leopard (that researchers) named''.", "ex_ko": "연구자들이 ''아렌''이라고 이름을 붙인 이 표범은 세 개의 다리로 약 240킬로미터를 이동한 것으로 추정됩니다.", "ex_en": "This leopard, which researchers named ''Aren,'' is estimated to have traveled approximately 240 kilometers on three legs."}, {"name": "~으로/로", "level": "Intermediate", "exp": "Instrumental particle indicating means or tool; 다리로 ''by/with legs'' specifies how the leopard moved.", "ex_ko": "연구자들이 ''아렌''이라고 이름을 붙인 이 표범은 세 개의 다리로 약 240킬로미터를 이동한 것으로 추정됩니다.", "ex_en": "This leopard, which researchers named ''Aren,'' is estimated to have traveled approximately 240 kilometers on three legs."}, {"name": "~고 (coordinating adjectives)", "level": "Intermediate", "exp": "Connects two adjectives 춥다 ''cold'' + 험하다 ''rugged'' to modify the same noun; emphasizes multiple qualities.", "ex_ko": "아르메니아에서 조지아까지 춥고 험한 산악 지형을 건넌 것입니다.", "ex_en": "That means it crossed cold, rugged mountain terrain from Armenia to Georgia."}, {"name": "~(으)ㄴ 것이다", "level": "Intermediate", "exp": "Explains what happened: 건너다 → 건넌 것입니다 ''(that is,) it crossed''.", "ex_ko": "아르메니아에서 조지아까지 춥고 험한 산악 지형을 건넌 것입니다.", "ex_en": "That means it crossed cold, rugged mountain terrain from Armenia to Georgia."}, {"name": "~게 되다", "level": "Intermediate", "exp": "Auxiliary verb phrase indicating a change of state or coming to be in a condition; 잃게 되다 ''to come to lose'' emphasizes the unintended or accidental nature.", "ex_ko": "아렌이 다리를 잃게 된 것은 코카서스 지역 곳곳에 남아 있는 지뢰 때문인 것으로 보입니다.", "ex_en": "It appears that Aren lost its leg due to landmines remaining throughout the Caucasus region."}, {"name": "~아/어 있는", "level": "Intermediate", "exp": "남다 → 남아 있다 ''to remain (a state)'' → 남아 있는 지뢰 ''landmines that remain''.", "ex_ko": "아렌이 다리를 잃게 된 것은 코카서스 지역 곳곳에 남아 있는 지뢰 때문인 것으로 보입니다.", "ex_en": "It appears that Aren lost its leg due to landmines remaining throughout the Caucasus region."}, {"name": "~아/어 있다", "level": "Intermediate", "exp": "Shows a state that continues: 남다 → 남아 있습니다 ''(minefields) still remain''.", "ex_ko": "코카서스 지역에는 과거 분쟁으로 인한 지뢰밭이 여전히 남아 있습니다.", "ex_en": "In the Caucasus region, minefields caused by past conflicts still remain."}, {"name": "~부터", "level": "Intermediate", "exp": "Starting point particle marking temporal origin; 시대부터 ''from/since the era'' indicates a starting time extending to present.", "ex_ko": "또한 소련 시대부터 수천 킬로미터에 걸쳐 설치된 철조망도 표범, 곰, 사슴 등 야생동물에게 위험합니다.", "ex_en": "Additionally, barbed wire installed over thousands of kilometers since the Soviet era is also dangerous to wildlife such as leopards, bears, and deer."}]}', updated_at = now() where article_id = 'mvr6wwtuf8t9' and md5(translation) = '5fdb836eaeaefd686a1e12aadaa23484';
update public.article_cache set translation = '{"texts": ["Model Joo Woo-jae drew attention after sharing that his quality of life improved after quitting Americano. He reported that positive changes occurred in both his body and daily life after giving up coffee.", "In Korea, Americano is one of the most common beverages for both office workers and students. This is because coffee culture has become deeply rooted, with cafes found throughout the streets.", "Joo Woo-jae was someone who regularly enjoyed Americano, but at some point he decided to quit coffee. Since then, various aspects of his life have changed, including improvements in sleep quality.", "Many people seem to relate to the difficulty of breaking free from a caffeine-dependent lifestyle. In particular, it is noteworthy that the habit of solving fatigue with coffee may actually interfere with sleep.", "Experts say that reducing caffeine intake can improve sleep quality and enhance overall condition. It prompts us to reconsider that while a cup of coffee helps us endure our daily routines, it may simultaneously be lowering our quality of life."], "sentences": [{"text": "모델 주우재가 아메리카노를 끊은 뒤 삶의 질이 높아졌다는 내용이 올라와 주목을 받았습니다.", "translation": "A post saying that model Joo Woo-jae''s quality of life improved after he quit Americanos went up and drew attention.", "vocab": [{"ko": "끊다", "en": "to quit; to stop"}, {"ko": "올라오다", "en": "to be posted; to go up"}, {"ko": "주목을 받다", "en": "to draw attention"}], "analysis": [{"type": "grammar", "label": "~은/ㄴ 뒤", "exp": "Temporal conjunction indicating ''after'' a completed action. Past tense modifier (끊은) + 뒤 marks sequence of events.", "example_in_sentence": "끊은 뒤"}, {"type": "grammar", "label": "~다는 내용", "exp": "Nominalizes a clause (높아졌다) and adds 내용 (content/claim) to report indirect speech or proposition.", "example_in_sentence": "높아졌다는 내용"}, {"type": "expression", "label": "주목을 받다", "exp": "Collocation meaning ''to attract/receive attention.'' Object-marking construction with 을 + 받다.", "example_in_sentence": "주목을 받았습니다"}]}, {"text": "그는 커피를 끊으면서 몸과 일상에 긍정적인 변화가 생겼다고 합니다.", "translation": "He reportedly said that quitting coffee brought positive changes to his body and daily life.", "vocab": [{"ko": "끊다", "en": "to quit; to stop"}, {"ko": "변화", "en": "change"}, {"ko": "생기다", "en": "to occur; to arise"}], "analysis": [{"type": "grammar", "label": "~으면서", "exp": "Connective suffix indicating simultaneous or accompanying action. Base 끊다 + 으면서 marks concurrent event with main clause.", "example_in_sentence": "끊으면서"}, {"type": "grammar", "label": "~다고 합니다", "exp": "Hearsay/report marker. Nominalized clause (생겼다) + 고 + 합니다 conveys indirect information or claim.", "example_in_sentence": "생겼다고 합니다"}]}, {"text": "한국에서 아메리카노는 직장인과 학생 모두에게 가장 흔한 음료 중 하나입니다.", "translation": "In Korea, Americano is one of the most common beverages for both office workers and students.", "vocab": [{"ko": "흔하다", "en": "to be common; to be frequent"}, {"ko": "음료", "en": "beverage; drink"}], "analysis": [{"type": "grammar", "label": "가장 … N 중 하나", "exp": "''One of the most …'': 가장 흔한 음료 중 하나 ''one of the most common drinks''.", "example_in_sentence": "가장 흔한 음료 중 하나"}]}, {"text": "길거리 곳곳에 카페가 있을 만큼 커피 문화가 깊이 자리 잡고 있기 때문입니다.", "translation": "That''s because coffee culture is so deeply rooted that there are cafés on every street.", "vocab": [{"ko": "곳곳", "en": "everywhere; here and there"}, {"ko": "자리 잡다", "en": "to be established; to take root"}], "analysis": [{"type": "expression", "label": "~(으)ㄹ 만큼", "exp": "''So much that…'': 있다 → 있을 만큼 ''so much that there are (cafés everywhere)''.", "example_in_sentence": "있을 만큼"}, {"type": "grammar", "label": "~기 때문이다", "exp": "Causal ending. ~기 nominalizes action + 때문이다 marks definitive reason/cause in formal speech.", "example_in_sentence": "있기 때문입니다"}]}, {"text": "주우재는 아메리카노를 즐겨 마시던 사람이었는데, 어느 순간 커피를 끊게 되었습니다.", "translation": "Joo Woo-jae was someone who habitually enjoyed drinking Americano, but at some point he came to quit coffee.", "vocab": [{"ko": "즐겨", "en": "habitually; with pleasure"}, {"ko": "끊다", "en": "to quit; to stop"}], "analysis": [{"type": "grammar", "label": "~던", "exp": "Past habitual/retrospective modifier. Combines with action verb (마시) to express repeated past action viewed from present.", "example_in_sentence": "마시던"}, {"type": "grammar", "label": "~게 되다", "exp": "Passive/inchoative auxiliary. 끊다 + 게 되다 marks involuntary transition or gradual change into state.", "example_in_sentence": "끊게 되었습니다"}, {"type": "expression", "label": "어느 순간", "exp": "Temporal expression meaning ''at some point; suddenly.'' Often marks threshold moment of change.", "example_in_sentence": "어느 순간"}]}, {"text": "그 이후로 수면의 질이 나아지는 등 여러 면에서 생활이 달라졌다고 합니다.", "translation": "Since then, he says, his life has changed in many ways, such as sleeping better.", "vocab": [{"ko": "나아지다", "en": "to improve; to get better"}, {"ko": "달라지다", "en": "to change; to become different"}], "analysis": [{"type": "grammar", "label": "~다고 합니다", "exp": "Hearsay/report marker. Reports indirect information with hedging tone.", "example_in_sentence": "달라졌다고 합니다"}]}, {"text": "카페인에 의존하는 생활에서 벗어나는 것이 쉽지 않다는 점에서 많은 사람들이 공감하는 것 같습니다.", "translation": "Many people seem to relate, since breaking away from a caffeine-dependent life isn''t easy.", "vocab": [{"ko": "의존하다", "en": "to depend on; to rely on"}, {"ko": "벗어나다", "en": "to escape from; to break away from"}, {"ko": "공감하다", "en": "to empathize; to relate to"}], "analysis": [{"type": "grammar", "label": "~는 (noun modifier)", "exp": "Present modifier: 의존하다 → 카페인에 의존하는 생활 ''a life dependent on caffeine''.", "example_in_sentence": "의존하는 생활"}, {"type": "grammar", "label": "~다는 점에서", "exp": "Causal/thematic marker. Nominalized clause (쉽지 않다) + 점 (point/aspect) + 에서 marks reason/perspective.", "example_in_sentence": "쉽지 않다는 점에서"}, {"type": "grammar", "label": "~는 것 같다", "exp": "Conjecture/appearance marker. ~는 것 nominalizes; 같다 adds epistemic hedge ''seems/appears to.''", "example_in_sentence": "공감하는 것 같습니다"}]}, {"text": "특히 피로를 커피로 해결하는 습관이 오히려 수면을 방해할 수 있다는 점은 눈여겨볼 만합니다.", "translation": "In particular, it''s worth noting that the habit of fighting fatigue with coffee can actually disturb sleep.", "vocab": [{"ko": "피로", "en": "fatigue; tiredness"}, {"ko": "방해하다", "en": "to hinder; to interfere with"}, {"ko": "눈여겨보다", "en": "to pay attention to; to note"}], "analysis": [{"type": "grammar", "label": "~(으)ㄹ 수 있다", "exp": "''Can; may'': 방해하다 → 방해할 수 있다 ''can disturb''.", "example_in_sentence": "방해할 수 있다"}, {"type": "grammar", "label": "~다는 점", "exp": "Nominalizes proposition to treat it as ''the point/fact that.'' Shifts emphasis to content itself.", "example_in_sentence": "수면을 방해할 수 있다는 점"}, {"type": "expression", "label": "~ㄹ 만하다", "exp": "Evaluative suffix meaning ''worth; deserving.'' Adjoins to verb to mark worthy of action.", "example_in_sentence": "눈여겨볼 만합니다"}]}, {"text": "전문가들은 카페인 섭취를 줄이면 수면의 질이 개선되면서 전반적인 컨디션이 좋아질 수 있다고 말합니다.", "translation": "Experts say that cutting down on caffeine can improve sleep quality and, with it, your overall condition.", "vocab": [{"ko": "섭취", "en": "intake; consumption"}, {"ko": "줄이다", "en": "to reduce; to decrease"}, {"ko": "개선되다", "en": "to improve; to be improved"}, {"ko": "전반적", "en": "overall; general"}], "analysis": [{"type": "grammar", "label": "~(으)면", "exp": "Ending meaning ''if'': 줄이다 → 줄이면 ''if (you) reduce''.", "example_in_sentence": "줄이면"}, {"type": "grammar", "label": "~(으)면서", "exp": "''As / along with'': 개선되다 → 개선되면서 ''as (sleep) improves, (your condition) also…''.", "example_in_sentence": "개선되면서"}, {"type": "grammar", "label": "~ㄹ 수 있다", "exp": "Possibility marker. 좋아지다 + ㄹ 수 있다 signals potential or capacity.", "example_in_sentence": "좋아질 수 있다"}]}, {"text": "커피 한 잔이 일상을 버티게 해 주는 동시에 삶의 질을 낮추고 있을 수도 있다는 점을 다시 생각해 보게 됩니다.", "translation": "It makes you think again about how a cup of coffee may be helping you get through the day while also lowering your quality of life.", "vocab": [{"ko": "버티다", "en": "to endure; to hold out; to withstand"}, {"ko": "동시에", "en": "at the same time; simultaneously"}, {"ko": "낮추다", "en": "to lower; to reduce"}], "analysis": [{"type": "grammar", "label": "~게 하다", "exp": "Causative auxiliary. 버티다 + 게 하다 marks ''to make/enable [someone] to endure.''", "example_in_sentence": "버티게 해"}, {"type": "expression", "label": "~는 동시에", "exp": "''While at the same time'': 해 주다 → 해 주는 동시에 ''while helping (you get through)''.", "example_in_sentence": "해 주는 동시에"}, {"type": "grammar", "label": "~고 있다", "exp": "Progressive aspect. 낮추다 + 고 있다 marks ongoing or habitual action in present time.", "example_in_sentence": "낮추고 있을"}, {"type": "grammar", "label": "~게 되다", "exp": "Inchoative/spontaneous marker. 생각해 보다 + 게 되다 marks natural or unintentional transition into thinking.", "example_in_sentence": "생각해 보게 됩니다"}]}], "version": "s6"}', vocab = '[{"ko": "끊다", "en": "to quit; to stop", "note": ""}, {"ko": "올라오다", "en": "to be posted; to go up", "note": ""}, {"ko": "주목을 받다", "en": "to draw attention", "note": ""}, {"ko": "변화", "en": "change", "note": ""}, {"ko": "생기다", "en": "to occur; to arise", "note": ""}, {"ko": "흔하다", "en": "to be common; to be frequent", "note": ""}, {"ko": "음료", "en": "beverage; drink", "note": ""}, {"ko": "곳곳", "en": "everywhere; here and there", "note": ""}, {"ko": "자리 잡다", "en": "to be established; to take root", "note": ""}, {"ko": "즐겨", "en": "habitually; with pleasure", "note": ""}, {"ko": "나아지다", "en": "to improve; to get better", "note": ""}, {"ko": "달라지다", "en": "to change; to become different", "note": ""}, {"ko": "의존하다", "en": "to depend on; to rely on", "note": ""}, {"ko": "벗어나다", "en": "to escape from; to break away from", "note": ""}, {"ko": "공감하다", "en": "to empathize; to relate to", "note": ""}, {"ko": "피로", "en": "fatigue; tiredness", "note": ""}, {"ko": "방해하다", "en": "to hinder; to interfere with", "note": ""}, {"ko": "눈여겨보다", "en": "to pay attention to; to note", "note": ""}, {"ko": "섭취", "