update public.article_cache set translation = '{"texts": ["American singer Sabrina Carpenter has become a hot topic on the internet. People were surprised because her appearance without makeup and with makeup looked so different.", "Internet users compared the two photos side by side. Some people called Carpenter a \"catfish.\" Catfish refers to a person who hides their true appearance.", "However, many fans are supporting Carpenter. They say that wearing makeup is a normal thing that all women do. They believe that musical talent is more important than appearance.", "This kind of controversy happens frequently to celebrities. In the age of social media, a single photo can become a big topic of discussion."], "sentences": [{"text": "미국 가수 사브리나 카펜터가 인터넷에서 화제가 되고 있어요.", "translation": "American singer Sabrina Carpenter has become a hot topic on the internet.", "vocab": [{"ko": "가수", "en": "singer", "note": "Common noun for profession"}, {"ko": "화제", "en": "hot topic; topic of discussion", "note": "Used with 되다 to mean ''become a topic''"}], "grammar": [{"pattern": "~고 있어요", "exp": "Indicates an ongoing action or state in present time.", "example_in_sentence": "화제가 되고 있어요"}], "analysis": []}, {"text": "메이크업을 하지 않은 모습과 메이크업을 한 모습이 너무 달라서 사람들이 놀랐어요.", "translation": "People were surprised because her appearance without makeup and with makeup looked so different.", "vocab": [{"ko": "메이크업", "en": "makeup", "note": "Loanword; 하다 verb for ''to apply makeup''"}, {"ko": "모습", "en": "appearance; look", "note": "Refers to visual appearance or how someone looks"}, {"ko": "놀라다", "en": "to be surprised", "note": "Passive emotion; conjugates to 놀랐어요 in past"}], "grammar": [{"pattern": "~어서", "exp": "Expresses cause or reason; ''because'' or ''so''.", "example_in_sentence": "달라서 사람들이 놀랐어요"}], "analysis": []}, {"text": "인터넷 사용자들이 두 사진을 나란히 놓고 비교했어요.", "translation": "Internet users compared the two photos side by side.", "vocab": [{"ko": "사용자", "en": "user", "note": "Formal term; 인터넷 사용자 = internet user"}, {"ko": "나란히", "en": "side by side; in a line", "note": "Adverb describing arrangement of objects"}, {"ko": "비교하다", "en": "to compare", "note": "Common academic verb; pairs with 놓고 for ''place side by side and compare''"}], "grammar": [{"pattern": "~고", "exp": "Connects two actions; ''place and then compare''.", "example_in_sentence": "나란히 놓고 비교했어요"}], "analysis": []}, {"text": "어떤 사람들은 카펜터가 ''캣피시''라고 말했어요.", "translation": "Some people called Carpenter a \"catfish.\"", "vocab": [{"ko": "어떤", "en": "some; certain", "note": "Modifier meaning ''certain people'' or ''some people''"}], "grammar": [], "analysis": []}, {"text": "캣피시는 자신의 진짜 모습을 숨기는 사람을 뜻해요.", "translation": "Catfish refers to a person who hides their true appearance.", "vocab": [{"ko": "뜻하다", "en": "to mean; to refer to", "note": "Used with noun subjects: ''X means/refers to Y''"}, {"ko": "숨기다", "en": "to hide; to conceal", "note": "Transitive verb; 진짜 모습을 숨기다 = hide one''s true appearance"}], "grammar": [{"pattern": "~는 사람", "exp": "Relative clause modifying 사람; the present tense form ~는 describes the noun.", "example_in_sentence": "모습을 숨기는 사람"}], "analysis": []}, {"text": "하지만 많은 팬들은 카펜터를 응원하고 있어요.", "translation": "However, many fans are supporting Carpenter.", "vocab": [{"ko": "하지만", "en": "however; but", "note": "Formal conjunction introducing contrast"}, {"ko": "응원하다", "en": "to support; to cheer for", "note": "Common verb for backing a person or team"}], "grammar": [{"pattern": "~고 있어요", "exp": "Indicates ongoing action in present.", "example_in_sentence": "응원하고 있어요"}], "analysis": []}, {"text": "메이크업은 모든 여성이 하는 일반적인 일이라고 말해요.", "translation": "They say that wearing makeup is a normal thing that all women do.", "vocab": [{"ko": "일반적", "en": "general; common; ordinary", "note": "Adjective; 일반적인 일 = a common/normal thing"}], "grammar": [{"pattern": "~다고 말하다", "exp": "Reports direct speech; ''say that...''", "example_in_sentence": "일반적인 일이라고 말해요"}], "analysis": []}, {"text": "외모보다는 음악 실력이 더 중요하다고 생각해요.", "translation": "They believe that musical talent is more important than appearance.", "vocab": [{"ko": "음악 실력", "en": "musical talent; musical skill", "note": "Compound: 음악 (music) + 실력 (skill/ability)"}, {"ko": "중요하다", "en": "to be important", "note": "Adjective; used with 더 for comparison"}], "grammar": [{"pattern": "~보다는", "exp": "Comparison particle; ''more than'' or ''rather than''.", "example_in_sentence": "외모보다는 음악 실력이 더 중요하다"}], "analysis": []}, {"text": "이런 논란은 연예인들에게 자주 일어나요.", "translation": "This kind of controversy happens frequently to celebrities.", "vocab": [{"ko": "논란", "en": "controversy; dispute", "note": "Noun for a heated public debate"}, {"ko": "연예인", "en": "celebrity; entertainer", "note": "Formal term for public figures in entertainment"}, {"ko": "자주", "en": "often; frequently", "note": "Adverb modifying frequency"}], "grammar": [{"pattern": "~에게", "exp": "Marks the recipient or target of an action; ''to/for''.", "example_in_sentence": "연예인들에게 자주 일어나요"}], "analysis": []}, {"text": "소셜 미디어 시대에는 사진 한 장으로 큰 화제가 될 수 있어요.", "translation": "In the age of social media, a single photo can become a big topic of discussion.", "vocab": [{"ko": "소셜 미디어", "en": "social media", "note": "Loanword; modern technology term"}, {"ko": "시대", "en": "age; era; period", "note": "Noun for a historical or cultural period"}, {"ko": "한 장", "en": "one; a single (counter for flat objects)", "note": "Counter word: 장 for sheets, pages, photos"}], "grammar": [{"pattern": "~ㄹ 수 있어요", "exp": "Expresses possibility; ''can'' or ''is able to''.", "example_in_sentence": "큰 화제가 될 수 있어요"}], "analysis": []}]}', vocab = '[{"ko": "가수", "en": "singer", "note": "Common noun for profession"}, {"ko": "화제", "en": "hot topic; topic of discussion", "note": "Used with 되다 to mean ''become a topic''"}, {"ko": "메이크업", "en": "makeup", "note": "Loanword; 하다 verb for ''to apply makeup''"}, {"ko": "모습", "en": "appearance; look", "note": "Refers to visual appearance or how someone looks"}, {"ko": "놀라다", "en": "to be surprised", "note": "Passive emotion; conjugates to 놀랐어요 in past"}, {"ko": "사용자", "en": "user", "note": "Formal term; 인터넷 사용자 = internet user"}, {"ko": "나란히", "en": "side by side; in a line", "note": "Adverb describing arrangement of objects"}, {"ko": "비교하다", "en": "to compare", "note": "Common academic verb; pairs with 놓고 for ''place side by side and compare''"}, {"ko": "어떤", "en": "some; certain", "note": "Modifier meaning ''certain people'' or ''some people''"}, {"ko": "뜻하다", "en": "to mean; to refer to", "note": "Used with noun subjects: ''X means/refers to Y''"}, {"ko": "숨기다", "en": "to hide; to conceal", "note": "Transitive verb; 진짜 모습을 숨기다 = hide one''s true appearance"}, {"ko": "하지만", "en": "however; but", "note": "Formal conjunction introducing contrast"}, {"ko": "응원하다", "en": "to support; to cheer for", "note": "Common verb for backing a person or team"}, {"ko": "일반적", "en": "general; common; ordinary", "note": "Adjective; 일반적인 일 = a common/normal thing"}, {"ko": "음악 실력", "en": "musical talent; musical skill", "note": "Compound: 음악 (music) + 실력 (skill/ability)"}, {"ko": "중요하다", "en": "to be important", "note": "Adjective; used with 더 for comparison"}, {"ko": "논란", "en": "controversy; dispute", "note": "Noun for a heated public debate"}, {"ko": "연예인", "en": "celebrity; entertainer", "note": "Formal term for public figures in entertainment"}, {"ko": "자주", "en": "often; frequently", "note": "Adverb modifying frequency"}, {"ko": "소셜 미디어", "en": "social media", "note": "Loanword; modern technology term"}, {"ko": "시대", "en": "age; era; period", "note": "Noun for a historical or cultural period"}, {"ko": "한 장", "en": "one; a single (counter for flat objects)", "note": "Counter word: 장 for sheets, pages, photos"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'mot9s42wj4zd' and md5(translation) = '4292b83edd6b1a651de204e7aabd7ec2';
update public.article_cache set translation = '{"texts": ["The Wikimedia Foundation announced that it will shut down Wikinews. Wikinews was an online news site that operated for 21 years.", "The foundation said it will close Wikinews in all languages on March 30th. It cited the difficulty of continuing the site for a long time as the reason.", "Wikinews was a site where anyone could write news. However, recently the number of users has decreased significantly.", "Since this is a decision by the Wikimedia Foundation, which is famous for Wikipedia, many people are showing interest in it."], "sentences": [{"text": "위키미디어 재단이 위키뉴스(Wikinews)를 닫는다고 발표했어요.", "translation": "The Wikimedia Foundation announced that it will shut down Wikinews.", "vocab": [{"ko": "위키미디어 재단", "en": "Wikimedia Foundation", "note": "Proper noun; the organization behind Wikipedia and Wikinews"}, {"ko": "닫다", "en": "to close, shut down", "note": "Used for closing websites, buildings, or businesses"}, {"ko": "발표하다", "en": "to announce", "note": "Official announcement of news or information"}], "grammar": [{"pattern": "~(으)ㄴ다고 발표하다", "exp": "Expresses announcing a future action or plan using reported speech with ~(으)ㄴ다 form inside a quotation", "example_in_sentence": "닫는다고 발표했어요"}], "analysis": []}, {"text": "위키뉴스는 21년 동안 운영된 온라인 뉴스 사이트예요.", "translation": "Wikinews was an online news site that operated for 21 years.", "vocab": [{"ko": "운영되다", "en": "to be operated, run", "note": "Passive form; describes how a business or service functions over time"}, {"ko": "온라인", "en": "online", "note": "Internet-based; borrowed word from English"}], "grammar": [], "analysis": []}, {"text": "재단은 3월 30일에 모든 언어의 위키뉴스를 닫겠다고 말했어요.", "translation": "The foundation said it will close Wikinews in all languages on March 30th.", "vocab": [{"ko": "닫다", "en": "to close, shut down", "note": "Same as sentence 1; repeated for consistency"}, {"ko": "말하다", "en": "to say, tell", "note": "Used here in reported speech context"}], "grammar": [{"pattern": "~(으)ㄹ 것이다 / ~겠다", "exp": "Expresses future intention or plan, here in reported speech form (~겠다고 말했어요)", "example_in_sentence": "닫겠다고 말했어요"}], "analysis": []}, {"text": "오랫동안 계속하기 어렵다는 이유를 들었어요.", "translation": "It cited the difficulty of continuing the site for a long time as the reason.", "vocab": [{"ko": "들다", "en": "to cite, raise (a reason)", "note": "~을/를 들다 = to bring up or mention something as evidence or reason"}, {"ko": "계속하다", "en": "to continue", "note": "To keep doing or maintain something"}], "grammar": [{"pattern": "~기 어렵다", "exp": "Expresses that an action (in ~기 form) is difficult to do", "example_in_sentence": "계속하기 어렵다"}], "analysis": []}, {"text": "위키뉴스는 누구나 뉴스를 쓸 수 있는 사이트였어요.", "translation": "Wikinews was a site where anyone could write news.", "vocab": [{"ko": "누구나", "en": "anyone, everyone", "note": "Universal pronoun; anyone at all can do the action"}, {"ko": "쓰다", "en": "to write", "note": "Write text, articles, or documents"}], "grammar": [], "analysis": []}, {"text": "하지만 최근에는 사용하는 사람이 많이 줄었어요.", "translation": "However, recently the number of users has decreased significantly.", "vocab": [{"ko": "사용하다", "en": "to use", "note": "Use a tool, service, or website"}, {"ko": "줄다", "en": "to decrease, diminish", "note": "Quantity or number becomes smaller"}], "grammar": [{"pattern": "~고 있다", "exp": "Describes a state or ongoing situation (past state continuing to present)", "example_in_sentence": "줄었어요 (past state); with context, shows a change over time"}], "analysis": []}, {"text": "위키백과(Wikipedia)로 유명한 위키미디어 재단의 결정이어서 많은 사람들이 관심을 보이고 있어요.", "translation": "Since this is a decision by the Wikimedia Foundation, which is famous for Wikipedia, many people are showing interest in it.", "vocab": [{"ko": "유명하다", "en": "to be famous, well-known", "note": "Descriptive verb; something or someone is known widely"}, {"ko": "결정", "en": "decision", "note": "A choice or determination made"}, {"ko": "관심을 보이다", "en": "to show interest, demonstrate concern", "note": "Expression of attention or care toward something"}], "grammar": [{"pattern": "~(으)니까 / ~어서 (causal connector)", "exp": "Connects the reason (famous foundation''s decision) to the result (many showing interest)", "example_in_sentence": "결정이어서 많은 사람들이 관심을 보이고 있어요"}], "analysis": []}]}', vocab = '[{"ko": "위키미디어 재단", "en": "Wikimedia Foundation", "note": "Proper noun; the organization behind Wikipedia and Wikinews"}, {"ko": "닫다", "en": "to close, shut down", "note": "Used for closing websites, buildings, or businesses"}, {"ko": "발표하다", "en": "to announce", "note": "Official announcement of news or information"}, {"ko": "운영되다", "en": "to be operated, run", "note": "Passive form; describes how a business or service functions over time"}, {"ko": "온라인", "en": "online", "note": "Internet-based; borrowed word from English"}, {"ko": "말하다", "en": "to say, tell", "note": "Used here in reported speech context"}, {"ko": "들다", "en": "to cite, raise (a reason)", "note": "~을/를 들다 = to bring up or mention something as evidence or reason"}, {"ko": "계속하다", "en": "to continue", "note": "To keep doing or maintain something"}, {"ko": "누구나", "en": "anyone, everyone", "note": "Universal pronoun; anyone at all can do the action"}, {"ko": "쓰다", "en": "to write", "note": "Write text, articles, or documents"}, {"ko": "사용하다", "en": "to use", "note": "Use a tool, service, or website"}, {"ko": "줄다", "en": "to decrease, diminish", "note": "Quantity or number becomes smaller"}, {"ko": "유명하다", "en": "to be famous, well-known", "note": "Descriptive verb; something or someone is known widely"}, {"ko": "결정", "en": "decision", "note": "A choice or determination made"}, {"ko": "관심을 보이다", "en": "to show interest, demonstrate concern", "note": "Expression of attention or care toward something"}]', grammar = '{"patterns": []}', updated_at = now() where article_id = 'moyxwezm487m' and md5(translation) = '73e61055d3e87d04d63655c5d6a6bfd5';
update public.article_cache set grammar = '{"patterns": [{"name": "-는 것 같다", "level": "Intermediate", "exp": "Says ''it seems that ...'' about something happening now, based on what the speaker observes. Attach -는 것 같다 to a verb: 늦추고 있다 → 늦추고 있는 것 같아요.", "ex_ko": "청년들이 집값 때문에 결혼을 늦추고 있는 것 같아요.", "ex_en": "It seems that young people are delaying marriage because of housing prices."}, {"name": "-아/어서 (reason)", "level": "Intermediate", "exp": "Connects a reason to its result: ''because ..., so ...''. 어렵다 → 어려워서 ''because it is difficult''.", "ex_ko": "집을 사기 어려워서 결혼을 미루고 있다.", "ex_en": "Because it is hard to buy a house, they are putting off marriage."}, {"name": "-ㄹ 예정이다", "level": "Intermediate", "exp": "Expression meaning ''plan to'' or ''intend to'', used to indicate a planned future action", "ex_ko": "정부는 청년 전용 임대주택을 더 많이 지을 예정입니다.", "ex_en": "The government plans to build more youth-exclusive rental housing."}]}', updated_at = now() where article_id = 'mmdzqsd00zvm' and md5(grammar) = '317ff7d8dee807176bbafd51d19fb962';
update public.article_cache set grammar = '{"patterns": [{"name": "-어지고 있어요", "level": "Intermediate", "exp": "Progressive change or state: ''is becoming/getting''. Shows that a situation is in the process of changing.", "ex_ko": "대학생들의 취업이 매우 어려워지고 있어요.", "ex_en": "University students'' employment is becoming very difficult."}, {"name": "-기 때문이다", "level": "Intermediate", "exp": "Ends a sentence by giving the reason: ''it is because ...''. Attach -기 to the verb stem: 부족하다 → 부족하기 때문입니다.", "ex_ko": "이 문제의 가장 큰 이유는 좋은 일자리가 부족하기 때문입니다.", "ex_en": "The biggest reason for this problem is that there are not enough good jobs."}, {"name": "-을 예정이에요", "level": "Intermediate", "exp": "Future plan or schedule: ''is planned to/is scheduled to''. Indicates an intention or plan for the future.", "ex_ko": "창업을 원하는 대학생들에게 무료 교육과 자금을 제공할 예정이에요.", "ex_en": "They are planning to provide free education and funding to university students who want to start a business."}]}', updated_at = now() where article_id = 'mmdzrmjzjr0w' and md5(grammar) = '58ef2f0ad681a13973732bf0e10e81a1';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄹ 수 있어요", "level": "Intermediate", "exp": "Expression indicating possibility or potential outcome", "ex_ko": "이런 갈등은 세계 경제에 나쁜 영향을 줄 수 있어요.", "ex_en": "This conflict can have a negative impact on the world economy."}, {"name": "-기로 했어요", "level": "Intermediate", "exp": "Expression meaning ''decided to'' or ''agreed to'' do something", "ex_ko": "양국은 다음 주에 화상회의를 열기로 했어요.", "ex_en": "The two countries decided to hold a video conference next week."}]}', updated_at = now() where article_id = 'mmdzrst4946p' and md5(grammar) = 'd90f4a65a50dc495e2c3ce784b662f3b';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 수 있다 (ability/possibility)", "level": "Intermediate", "exp": "Expresses ability or possibility: ''can, be able to''. Attach it to the verb stem: 설명하다 → 설명할 수 있어요.", "ex_ko": "새 버전은 동영상을 보고 내용을 설명<strong>할 수 있어요</strong>.", "ex_en": "The new version can watch videos and explain their content."}, {"name": "~다고 말했어요 (reported speech - past)", "level": "Intermediate", "exp": "This pattern is used to report what someone said in the past. The ~다고 ending converts the statement into indirect speech, followed by the past tense verb 말했어요.", "ex_ko": "이전 버전보다 훨씬 똑똑해졌<strong>다고 말했어요</strong>.", "ex_en": "(They) said that it became much smarter than the previous version."}, {"name": "~을 것 같아요 (conjecture/prediction)", "level": "Intermediate", "exp": "This pattern expresses a guess, prediction, or supposition about something. It indicates the speaker''s assumption or expectation based on current information.", "ex_ko": "학생들이 공부할 때 더 많은 도움을 받을 수 있<strong>을 것 같아요</strong>.", "ex_en": "It seems like students will be able to receive more help when studying."}, {"name": "-(으)ㄹ 것으로 예상되다", "level": "Intermediate", "exp": "A formal, news-style way to say something is expected to happen: ''it is expected that ...''. 바뀌다 → 바뀔 것으로 예상됩니다.", "ex_ko": "앞으로 교육, 의료, 회사 업무 등 많은 분야가 바뀔 <strong>것으로 예상됩니다</strong>.", "ex_en": "Many fields such as education, healthcare and office work are expected to change going forward."}]}', updated_at = now() where article_id = 'mmdzsen0c2vv' and md5(grammar) = 'abae1d560714b11baa9b8d7302bc7e93';
update public.article_cache set grammar = '{"patterns": [{"name": "-기 시작하다", "level": "Intermediate", "exp": "Marks the start of an action: ''start to, begin -ing''. 올리다 → 올리기 시작했어요 ''began raising''.", "ex_ko": "2025년부터 등록금을 올리기 시작했어요.", "ex_en": "Starting in 2025, (universities) began raising tuition."}, {"name": "-어야 합니다", "level": "Intermediate", "exp": "Expresses necessity or obligation; ''must/have to'' or ''need to''", "ex_ko": "한 학기에 50만 원에서 100만 원 정도 더 내야 합니다.", "ex_en": "You have to pay an additional 500,000 to 1,000,000 won per semester."}, {"name": "-도록 (so that)", "level": "Intermediate", "exp": "Links a goal to an action: ''so that ...''. 받을 수 있도록 means ''so that (students) can receive''.", "ex_ko": "학자금 대출을 더 쉽게 받을 수 있도록 도와주겠다고 했습니다.", "ex_en": "The government said it would help so that students can get student loans more easily."}]}', updated_at = now() where article_id = 'mme1ggu42n5y' and md5(grammar) = 'ee138aeefb5c9fbd9a301cbfe25f5c28';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있는 + noun", "level": "Intermediate", "exp": "A progressive verb can describe a noun: -고 있다 → -고 있는 + noun, ''a ... that is (still) -ing''. 떨어지고 있는 수치 = ''a figure that keeps falling''.", "ex_ko": "이는 계속 떨어지고 있는 수치입니다.", "ex_en": "This is a figure that continues to fall."}, {"name": "-아/어서", "level": "Intermediate", "exp": "Causal connector indicating reason or cause. Connects two clauses where the first clause explains why the second clause happens", "ex_ko": "집값이 너무 비싸서 결혼을 늦게 하는 사람들이 많아졌어요.", "ex_en": "Because housing prices are too expensive, many people are getting married late."}, {"name": "-(으)ㄹ 수 있도록", "level": "Intermediate", "exp": "''So that (someone) can ...'': -(으)ㄹ 수 있다 (can) + -도록 (so that). 쓰다 → 쓸 수 있도록.", "ex_ko": "아빠들도 육아휴직을 쓸 수 있도록 제도를 개선했어요.", "ex_en": "They improved the system so that fathers can also take parental leave."}]}', updated_at = now() where article_id = 'mme1i6cthxsj' and md5(grammar) = '991d99738e85b55f5d6a7a87347bd7b2';
update public.article_cache set grammar = '{"patterns": [{"name": "~(으)ㄹ 예정이다", "level": "Intermediate", "exp": "Expresses a plan or intention to do something in the future", "ex_ko": "새로운 AI 칩은 주로 스마트폰과 자동차에 사용될 예정이에요.", "ex_en": "The new AI chip is planned to be mainly used in smartphones and automobiles."}, {"name": "-(으)ㄹ 것으로 기대되다", "level": "Intermediate", "exp": "News-style expression for a hoped-for result: ''it is expected to ...''. 향상시키다 → 향상시킬 것으로 기대됩니다.", "ex_ko": "자율주행 자동차의 성능을 크게 향상시킬 것으로 기대됩니다.", "ex_en": "It is expected to greatly improve the performance of self-driving cars."}, {"name": "-(으)ㄹ 것이라고 (reported prediction)", "level": "Intermediate", "exp": "Reports a prediction someone made: -(으)ㄹ 것이다 (''will'') + the quoting ending -라고. 될 것이라고 평가했어요 = ''assessed that it will be''.", "ex_ko": "이 기술이 한국의 IT 산업 발전에 도움이 될 것이라고 평가했어요.", "ex_en": "(Experts) assessed that this technology will help the development of Korea''s IT industry."}]}', updated_at = now() where article_id = 'mme1it9jthdk' and md5(grammar) = 'aefdc8f3340d979ebcd99dd16580dc6d';
update public.article_cache set grammar = '{"patterns": [{"name": "-았/었어요 (past polite)", "level": "Beginner", "exp": "Polite past-tense ending for something that already happened. 시작하다 → 시작했어요 ''started''.", "ex_ko": "미국과 중국이 무역 문제를 해결하기 위해 대화를 시작했어요.", "ex_en": "The US and China started talks to resolve trade issues."}, {"name": "-ㄹ지", "level": "Beginner", "exp": "Expression indicating uncertainty or wondering about a future possibility", "ex_ko": "이번 대화로 관계가 좋아질지 관심이 높아요.", "ex_en": "People are very interested in whether this dialogue will improve relations."}, {"name": "-면", "level": "Beginner", "exp": "Conditional ending meaning ''if'' or ''when'', indicating a condition and its result", "ex_ko": "좋은 결과가 나오면 세계 경제에도 도움이 될 거예요.", "ex_en": "If good results come out, it will also help the global economy."}]}', updated_at = now() where article_id = 'mme43qhwfvx1' and md5(grammar) = '0ac8210801bec3c2ec74b1ddb14ffc4c';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄴ/은 지", "level": "Intermediate", "exp": "Expresses ''it has been [time] since'' or ''within [time] of''. Used to indicate a period of time that has passed since an action occurred.", "ex_ko": "공개된 지 일주일 만에 80개국에서 1위를 기록했어요.", "ex_en": "Within just one week of being released, it ranked 1st in 80 countries."}, {"name": "-고 있다", "level": "Beginner", "exp": "Indicates an ongoing or continuous action in the present. Expresses ''is/are [verb]ing'' or shows a state that continues.", "ex_ko": "많은 사람들이 시청하고 있습니다.", "ex_en": "Many people are watching it."}, {"name": "-다고 말하다 (indirect speech)", "level": "Intermediate", "exp": "Reports what someone said. Add -다고 to the quoted statement, then 말하다: 늘어나고 있다 → 늘어나고 있다고 말했어요.", "ex_ko": "전문가들은 한국 드라마의 인기가 계속 늘어나고 있다고 말했어요.", "ex_en": "Experts said that the popularity of Korean dramas continues to grow."}]}', updated_at = now() where article_id = 'mmfavhx3y71c' and md5(grammar) = '36509ad3346bbcb262a327664feccb6d';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 것으로 보이다", "level": "Advanced", "exp": "Expresses a guess based on visible signs or evidence: ''it appears that ... will''. 사용되다 → 사용될 것으로 보입니다.", "ex_ko": "스마트폰과 자율주행차에 주로 사용될 것으로 보입니다.", "ex_en": "It appears that it will be used mainly in smartphones and self-driving cars."}, {"name": "-(으)려고 하다", "level": "Advanced", "exp": "Expresses intention or purpose: ''intend to, plan to''. 높이다 → 높이려고 해요.", "ex_ko": "삼성은 이 기술로 글로벌 AI 반도체 시장에서 경쟁력을 높이려고 해요.", "ex_en": "Samsung intends to raise its competitiveness in the global AI semiconductor market with this technology."}, {"name": "-ㄹ 것으로 예상됩니다", "level": "Advanced", "exp": "Expresses prediction or expectation about a future event; ''it is expected/anticipated that''", "ex_ko": "다른 경쟁사들도 비슷한 제품 개발에 속도를 낼 것으로 예상됩니다.", "ex_en": "It is expected that competitors will also accelerate similar product development."}]}', updated_at = now() where article_id = 'mmfavwhbx3gl' and md5(grammar) = '92b4b239ace0571214e0bfd7aaacdbfe';
update public.article_cache set grammar = '{"patterns": [{"name": "N보다 더 (comparison)", "level": "Intermediate", "exp": "Compares two things: ''more ... than N''. 보다 follows the thing compared against and 더 comes before the adjective: 기존 칩보다 더 빠르다 ''faster than existing chips''.", "ex_ko": "이 칩은 기존 칩보다 40% <strong>더 빨라진다</strong>고 합니다.", "ex_en": "This chip is said to be 40% faster than existing chips."}, {"name": "''-ㄹ 수 있다'' (capability/possibility)", "level": "Intermediate", "exp": "This pattern expresses ability or possibility. It literally means ''can do'' or ''is able to do,'' showing that something is possible or capable of being done.", "ex_ko": "이 칩은 사진 편집이나 번역 같은 AI 기능을 <strong>더 빠르게 처리할 수 있어요</strong>.", "ex_en": "This chip is able to process AI functions like photo editing and translation faster."}, {"name": "-(으)ㄹ 것으로 예상되다", "level": "Intermediate", "exp": "A formal, news-style way to say something is expected to happen: ''it is expected to ...''. 비싸지다 → 비싸질 것으로 예상됩니다.", "ex_ko": "새 아이폰의 가격은 아직 발표되지 않았어요. 하지만 AI 칩 때문에 기존 모델보다 10만 원 정도 <strong>비싸질 것으로 예상됩니다</strong>.", "ex_en": "The price of the new iPhone has not been announced yet. But because of the AI chip, it is expected to be about 100,000 won more expensive than existing models."}, {"name": "''-고 있다'' (ongoing action/progressive)", "level": "Intermediate", "exp": "This pattern describes an action that is currently happening or in progress. It shows a continuous or habitual action in the present.", "ex_ko": "삼성전자와 구글도 비슷한 AI 칩을 <strong>개발하고 있어요</strong>.", "ex_en": "Samsung and Google are also developing similar AI chips."}]}', updated_at = now() where article_id = 'mmfsudbx015o' and md5(grammar) = '1f6c8758cf9f8816cfce22484e019b35';
update public.article_cache set grammar = '{"patterns": [{"name": "N이/가 되다", "level": "Intermediate", "exp": "''To become N'': the noun takes 이/가 and is followed by 되다. 14억 2천만 명이 되었어요 = ''has reached 1.42 billion people''.", "ex_ko": "인도의 인구가 14억 2천만 명이 되었어요.", "ex_en": "India''s population has reached 1.42 billion."}, {"name": "-고 있어요", "level": "Intermediate", "exp": "Indicates an ongoing or continuous action/state in the present", "ex_ko": "중국은 출산율이 계속 낮아지고 있어요.", "ex_en": "China''s birth rate is continuously decreasing."}, {"name": "-ㄹ 것 같아요", "level": "Intermediate", "exp": "Expresses conjecture or supposition; ''seems like it will'' or ''appears that''", "ex_ko": "이런 변화는 세계 경제에 큰 영향을 줄 것 같아요.", "ex_en": "This change seems like it will have a big impact on the world economy."}]}', updated_at = now() where article_id = 'mmivefmnhjrj' and md5(grammar) = '87fb33b77934a8b44e00cbb56a265d69';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 것이다", "level": "Intermediate", "exp": "Expresses future prediction or conjecture; ''will'' or ''is going to''", "ex_ko": "이 문제가 빨리 해결되지 않으면 학생들의 학습에 큰 영향을 줄 것이라고 걱정하고 있습니다.", "ex_en": "Experts are worried that if this problem is not solved quickly, it will have a big impact on students'' learning."}, {"name": "N 때문에", "level": "Intermediate", "exp": "''Because of N'': put 때문에 directly after a noun. 민원 때문에 = ''because of complaints''. (After a verb, use -기 때문에.)", "ex_ko": "학생들의 문제 행동이나 학부모들의 민원 때문에 교사들이 스트레스를 많이 받고 있습니다.", "ex_en": "Because of students'' behavior problems and parents'' complaints, teachers are under a lot of stress."}, {"name": "-기도 했어요", "level": "Intermediate", "exp": "Indicates that an action also occurred or happened; ''also did'' or ''even changed to''", "ex_ko": "일부 학교는 수업 시간을 줄이거나 온라인 수업으로 바꾸기도 했어요.", "ex_en": "Some schools also reduced class hours or changed to online classes."}]}', updated_at = now() where article_id = 'mmk2g2np3o8r' and md5(grammar) = 'b0772fff230c64b18c9099ef5362d54e';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 것으로 보이다", "level": "Intermediate", "exp": "Expresses a prediction based on current signs or evidence: ''it appears that ... will''. 활발해지다 → 활발해질 것으로 보입니다.", "ex_ko": "이들의 성공으로 K-팝의 일본 진출이 더욱 활발해질 것으로 보입니다.", "ex_en": "It appears that K-pop''s push into Japan will become even more active thanks to their success."}, {"name": "-다고 말하다 (indirect speech)", "level": "Intermediate", "exp": "Reports what someone said. Add -다고 to the quoted statement: 감동했다 → 감동했다고 말했습니다 ''said that they were moved''.", "ex_ko": "일본 팬들의 뜨거운 반응에 멤버들도 감동했다고 말했습니다.", "ex_en": "The members said they were moved by the enthusiastic response from Japanese fans."}, {"name": "-고 있다", "level": "Intermediate", "exp": "Describes an action in progress, including ongoing plans: ''be -ing''. 계획하다 → 계획하고 있어요 ''are planning''.", "ex_ko": "올해 하반기에는 아시아 다른 나라에서도 대규모 공연을 계획하고 있어요.", "ex_en": "For the second half of this year, they are planning large-scale concerts in other Asian countries as well."}]}', updated_at = now() where article_id = 'mmk2gjw6asvi' and md5(grammar) = 'bdd4ad5cb37eb283013021bbb5f05938';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어지다 (change of state)", "level": "Beginner", "exp": "Shows a change of state: ''become ...''. 비싸다 → 비싸지다 ''become expensive''; past: 비싸졌어요.", "ex_ko": "작년보다 15% 더 비싸졌어요.", "ex_en": "It became 15% more expensive than last year."}, {"name": "아/어야 해요 (Must/Have to)", "level": "Beginner", "exp": "Expresses necessity or obligation that something must be done.", "ex_ko": "20대와 30대가 아파트를 사려면 평균 15년 동안 돈을 모아야 해요.", "ex_en": "People in their 20s and 30s must save money for an average of 15 years to buy an apartment."}, {"name": "ㄹ 예정이에요 (Plan to/Intend to)", "level": "Beginner", "exp": "Expresses a future plan or intention to do something.", "ex_ko": "청년들을 위한 특별 대출을 늘릴 예정이에요.", "ex_en": "They plan to increase special loans for young people."}]}', updated_at = now() where article_id = 'mmkx710642gg' and md5(grammar) = '1483613f7d5f782b7c5cafa426bfcb28';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄴ/는다고 발표하다", "level": "Beginner", "exp": "Reports an announcement (indirect speech): statement + -ㄴ/는다고 + 발표하다. 중단하다 → 중단한다고 발표했어요 ''announced that it will stop''.", "ex_ko": "유럽연합(EU)이 러시아 에너지 사용을 완전히 중단한다고 발표했어요.", "ex_en": "The European Union (EU) announced that it will completely stop using Russian energy."}, {"name": "-기로 하다", "level": "Beginner", "exp": "Expresses a decision or agreement to do something: ''decide to''. 사다 → 사기로 했어요 ''decided to buy''.", "ex_ko": "앞으로는 다른 나라에서 에너지를 사기로 했어요.", "ex_en": "From now on, they decided to buy energy from other countries."}, {"name": "-(으)ㄹ 것 같다", "level": "Beginner", "exp": "Expresses a guess about what will happen: ''it seems (it) will ...''. 주다 → 줄 것 같아요.", "ex_ko": "이 결정은 세계 경제에도 큰 영향을 줄 것 같아요.", "ex_en": "This decision seems likely to have a big impact on the global economy too."}]}', updated_at = now() where article_id = 'mmkx7jrghjob' and md5(grammar) = '6a814979b201a691401e4e4d6d2b9568';
update public.article_cache set grammar = '{"patterns": [{"name": "~는 것은 (Nominalization with ''thing'')", "level": "Beginner", "exp": "Turns a verb into a noun phrase to make a general statement about an action or state.", "ex_ko": "한국 가수의 솔로 앨범이 빌보드 1위를 하는 것은 매우 어려운 일이에요.", "ex_en": "For a Korean singer''s solo album to rank #1 on Billboard is a very difficult thing."}]}', updated_at = now() where article_id = 'mmkx81rnt4wn' and md5(grammar) = '178267c8cdd962c551febb06c3845096';
update public.article_cache set grammar = '{"patterns": [{"name": "N 직후", "level": "Intermediate", "exp": "''Right after N'': 직후 follows a noun. 지진 직후 = ''right after the earthquake''. (After a verb, use -(으)ㄴ 직후.)", "ex_ko": "지진 직후 구조대와 의료진을 보냈어요", "ex_en": "Right after the earthquake, they sent rescue teams and medical staff."}, {"name": "-기 위해(서) / In order to", "level": "Intermediate", "exp": "Expresses the purpose or reason for an action", "ex_ko": "집을 다시 짓고 병원과 학교를 복구하기 위해서입니다", "ex_en": "It is to rebuild houses and restore hospitals and schools"}, {"name": "-는 데 + time / It takes (time) to", "level": "Intermediate", "exp": "Indicates the amount of time required to complete an action", "ex_ko": "피해 지역을 완전히 복구하는 데 10년이 걸릴 것이라고 말했어요", "ex_en": "He said it will take 10 years to completely restore the affected areas"}]}', updated_at = now() where article_id = 'mmtk5ol5fu3t' and md5(grammar) = '3e09489e4cc817669591625ae53c6b1a';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 예정입니다 (future plan/schedule)", "level": "Intermediate", "exp": "This pattern expresses a planned or scheduled future action. It indicates something that is definitely going to happen according to a plan or schedule.", "ex_ko": "이 드라마는 올해 하반기에 <strong>방송될 예정입니다</strong>.", "ex_en": "This drama is scheduled to air in the second half of this year."}, {"name": "-면서도 (while/and yet)", "level": "Intermediate", "exp": "This pattern connects two contrasting or simultaneous ideas, meaning ''while also'' or ''and yet.'' It shows that two different qualities exist together.", "ex_ko": "드라마 제작진은 \"<strong>현실적이면서도</strong> 감동적인 이야기\"라고 소개했습니다.", "ex_en": "The production team introduced it as a story that is ''realistic and yet touching.''"}, {"name": "-고 있어요 (progressive/continuous action)", "level": "Intermediate", "exp": "This pattern describes an ongoing action or state that is currently in progress. It emphasizes the continuous nature of the action happening now.", "ex_ko": "현지 팬들은 소셜미디어(SNS)에서 기대감을 <strong>표현하고 있어요</strong>.", "ex_en": "Local fans are expressing their anticipation on social media (SNS)."}]}', updated_at = now() where article_id = 'mmtk69xjbaos' and md5(grammar) = '269301dc5e0a2d78d597b0a91a967f93';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)며", "level": "Intermediate", "exp": "A written connector that links two actions or facts: ''and, while''. 요구하다 → 요구하며 ''while demanding''.", "ex_ko": "전국 교원들이 더 나은 근무 환경을 요구하<strong>며</strong> 파업을 예고했어요.", "ex_en": "Teachers across the country announced a strike, demanding a better working environment."}, {"name": "-(으)ㄹ 수 있다", "level": "Intermediate", "exp": "Expresses ability or possibility: ''can''. Here it describes a noun: 교육할 수 있는 권리 ''the right to be able to educate''.", "ex_ko": "학생들을 올바르게 교육<strong>할 수 있는</strong> 권리", "ex_en": "the right to educate students properly"}, {"name": "-지 않도록", "level": "Intermediate", "exp": "Means ''so that ... does not'' and states something you want to prevent. 주다 → 주지 않도록 ''so that it does not affect''.", "ex_ko": "파업이 학생들 수업에 영향을 주<strong>지 않도록</strong> 대책을 준비하고 있어요.", "ex_en": "They are preparing measures so that the strike does not affect students'' classes."}, {"name": "-다고 말하다 (indirect speech)", "level": "Intermediate", "exp": "Reports what someone says. Add -다고 to the quoted statement, then 말하다: 해결해야 한다 → 해결해야 한다고 말해요.", "ex_ko": "전문가들은 교육 현장의 문제를 근본적으로 해결해야 한다<strong>고 말해요.</strong>", "ex_en": "Experts say that the problems in schools must be solved at the root."}]}', updated_at = now() where article_id = 'mmtsc2iiox5n' and md5(grammar) = 'd8d88b36a2bce70a256223336ff04151';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 것 같다", "level": "Starter", "exp": "Expresses a guess about what will happen: ''it seems (it) will ...''. 태어나다 → 태어날 것 같아요.", "ex_ko": "올해도 작년보다 더 적은 아기가 태어날 것 같아요.", "ex_en": "It seems that even fewer babies will be born this year than last year."}, {"name": "-아/어서예요 (giving a reason)", "level": "Starter", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. 어렵다 → 어려워서예요.", "ex_ko": "집값이 너무 비싸고 일자리를 구하기 어려워서예요.", "ex_en": "It''s because housing is too expensive and jobs are hard to find."}, {"name": "-(으)ㄹ 수 있게", "level": "Starter", "exp": "''So that (someone) can ...'': -(으)ㄹ 수 있다 + -게. 쓰다 → 쓸 수 있게 도와주다 ''help (someone) be able to use''.", "ex_ko": "아빠도 육아휴직을 쓸 수 있게 도와줄 거예요.", "ex_en": "They will help fathers be able to take parental leave too."}]}', updated_at = now() where article_id = 'mmv5j7ibzxqw' and md5(grammar) = 'f08a057e10fc8f6d5f2ca1d6510cb2d3';
update public.article_cache set grammar = '{"patterns": [{"name": "-기 시작하다", "level": "Starter", "exp": "Marks the start of an action: ''start to ...''. 피다 → 피기 시작했어요 ''started to bloom''.", "ex_ko": "3월이 되면서 전국에 봄꽃이 피기 시작했어요.", "ex_en": "Now that it is March, spring flowers have started to bloom all over the country."}, {"name": "~ㄹ 거예요 (Future prediction)", "level": "Starter", "exp": "Used to express predictions or expectations about the future based on current conditions or observations.", "ex_ko": "올해는 날씨가 따뜻해서 꽃이 일찍 필 거예요.", "ex_en": "Since the weather is warm this year, the flowers will bloom early."}, {"name": "~지 말아요 (Negative imperative)", "level": "Starter", "exp": "Used to give polite commands or instructions telling someone not to do something.", "ex_ko": "꽃구경을 갈 때는 쓰레기를 버리지 말아요.", "ex_en": "When going to see the flowers, don''t throw away trash."}]}', updated_at = now() where article_id = 'mmv5jq5ams1m' and md5(grammar) = 'b02ae93a3b1913165912862a625c6f98';
update public.article_cache set grammar = '{"patterns": [{"name": "-다고 발표하다", "level": "Intermediate", "exp": "Reports an announcement (indirect speech): statement + -다고 + 발표하다. 들어갔다 → 들어갔다고 발표했어요 ''announced that (Korea) had entered''.", "ex_ko": "통계청은 한국이 본격적인 초고령 사회에 <strong>들어갔다고 발표했어요</strong>.", "ex_en": "Statistics Korea announced that Korea has fully entered a super-aged society."}, {"name": "-고 있다", "level": "Intermediate", "exp": "Describes an action or change that is in progress: ''be -ing''. 떨어지다 → 떨어지고 있어요 ''is falling''.", "ex_ko": "반면 출산율은 계속 <strong>떨어지고 있어요</strong>.", "ex_en": "Meanwhile, the birth rate keeps falling."}, {"name": "V-(으)ㄹ 것으로 예상되다 (It is expected that...)", "level": "Intermediate", "exp": "This pattern expresses predictions or expectations about future outcomes based on current analysis. The passive form emphasizes that this is a general expectation rather than a personal opinion.", "ex_ko": "젊은 세대의 세금 부담<strong>도 더 무거워질 것으로 예상돼요</strong>.", "ex_en": "The tax burden on the younger generation is expected to become heavier."}]}', updated_at = now() where article_id = 'mmyfvo7c5065' and md5(grammar) = 'e39508b989f7c73d4ff9e2faa588d580';
update public.article_cache set grammar = '{"patterns": [{"name": "~(으)ㄹ 수 있다 (can, be able to)", "level": "Intermediate", "exp": "Expresses possibility or ability to do something.", "ex_ko": "새로운 최저임금으로 하루 8시간 일하면 9만 6천원을 받을 수 있어요.", "ex_en": "With the new minimum wage, if you work 8 hours a day, you can receive 96,000 won."}, {"name": "~다고 말했어요 / ~다고 했어요 (said that)", "level": "Intermediate", "exp": "Reports what someone said using indirect speech with the connector ~다고.", "ex_ko": "노동자들은 \"생활비가 많이 올랐는데 임금 인상이 부족하다\"고 말했어요.", "ex_en": "Workers said that ''living expenses have risen a lot, but the wage increase is insufficient.''"}]}', updated_at = now() where article_id = 'mn3yplu491xg' and md5(grammar) = '02bc937fc858c01478da11b357babdb5';
update public.article_cache set grammar = '{"patterns": [{"name": "~ㄴ/은 지 (시간) 지났어요", "level": "Intermediate", "exp": "Expresses that a certain amount of time has passed since an action or event occurred", "ex_ko": "일본 후쿠시마 원자력 발전소 처리수 방류가 시작된 지 1년이 지났어요.", "ex_en": "One year has passed since the release of treated water from the Fukushima nuclear power plant began."}, {"name": "-(으)ㄹ까 봐", "level": "Intermediate", "exp": "Expresses worry that something might happen: ''afraid that ...''. Often followed by 걱정하다: 줄어들까 봐 걱정하다 ''worry that (sales) may drop''.", "ex_ko": "수산업계는 생선 판매가 줄어들까 봐 걱정하고 있어요.", "ex_en": "The fishing industry is worried that fish sales might drop."}]}', updated_at = now() where article_id = 'mn3yq8fvg9er' and md5(grammar) = 'c7ac6ee8fe1a7cbdfdf8c9686bc99ac4';
update public.article_cache set grammar = '{"patterns": [{"name": "Present Progressive (-고 있어요)", "level": "Intermediate", "exp": "Expresses an action that is currently ongoing or in progress.", "ex_ko": "손흥민이 아시안컵에서 한국 대표팀을 이끌고 있어요.", "ex_en": "Son Heung-min is leading the Korean national team at the Asian Cup."}, {"name": "Quoted Speech (-라고 말해요)", "level": "Intermediate", "exp": "Used to report what someone said or their opinion indirectly.", "ex_ko": "축구 전문가들은 한국이 좋은 결과를 낼 것이라고 말해요.", "ex_en": "Soccer experts say that Korea will produce good results."}]}', updated_at = now() where article_id = 'mn3yqqd4y4wh' and md5(grammar) = '8d7b395182eae3ac90514564d4d536cf';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 수 있게 되다", "level": "Beginner", "exp": "Shows a new situation that has come about: ''have become able to ...''. 팔다 → 팔 수 있게 됐어요 ''became able to sell''.", "ex_ko": "브라질은 중국에 콩과 쇠고기를 더 많이 팔 수 있게 됐어요.", "ex_en": "Brazil is now able to sell more soybeans and beef to China."}, {"name": "-(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses ability or possibility: ''can''. 키우다 → 키울 수 있다 ''can grow''.", "ex_ko": "중국이 남미에서 영향력을 더 키울 수 있기 때문이에요.", "ex_en": "It is because China can grow its influence in South America."}, {"name": "N 때문에", "level": "Beginner", "exp": "''Because of N'': put 때문에 directly after a noun. 이 협정 때문에 = ''because of this agreement''.", "ex_ko": "이 협정 때문에 미국이 걱정하고 있어요.", "ex_en": "Because of this agreement, the United States is worried."}]}', updated_at = now() where article_id = 'mn4t78efpb3c' and md5(grammar) = 'b7061da0bd25f30b606adf6cd6453b07';
update public.article_cache set grammar = '{"patterns": [{"name": "N + -이/가 되다", "level": "Beginner", "exp": "Pattern meaning ''to become'' showing a change of state", "ex_ko": "한국 드라마 역사상 가장 성공한 작품이 됐어요.", "ex_en": "It became the most successful work in Korean drama history."}]}', updated_at = now() where article_id = 'mn4t7rmym8dl' and md5(grammar) = '268027fa9be6b776f3fe7e54731fe311';
update public.article_cache set grammar = '{"patterns": [{"name": "-았/었어요 (past polite)", "level": "Starter", "exp": "Polite past-tense ending for something that already happened. 줄다 → 줄었어요 ''decreased''.", "ex_ko": "한국 초등학교에 다니는 아이들이 많이 줄었어요.", "ex_en": "The number of children attending elementary schools in Korea has dropped a lot."}, {"name": "N 같은 (like N)", "level": "Starter", "exp": "Gives examples before a noun: ''N like ...''. 서울과 부산 같은 큰 도시 = ''big cities like Seoul and Busan''.", "ex_ko": "서울과 부산 같은 큰 도시에서 아이가 더 많이 줄었어요.", "ex_en": "In big cities like Seoul and Busan, the number of children fell even more."}, {"name": "동사 + 기 어려워요 (It is difficult to...)", "level": "Starter", "exp": "Used to express that doing an action is difficult or challenging.", "ex_ko": "하지만 아이들이 친구를 사귀기 어려워요.", "ex_en": "However, it is difficult for children to make friends."}]}', updated_at = now() where article_id = 'mn4t9sj8yv87' and md5(grammar) = '359496e247b7aeb91bee9c590cc1bcdc';
update public.article_cache set grammar = '{"patterns": [{"name": "동사 + 기로 하다", "level": "Starter", "exp": "Expresses a decision or plan to do something", "ex_ko": "나토가 동유럽에 군대를 더 보내기로 했어요.", "ex_en": "NATO decided to send more troops to Eastern Europe."}, {"name": "명사 + 때문이다", "level": "Beginner", "exp": "Indicates the reason or cause of something, meaning ''because of''", "ex_ko": "러시아와 우크라이나 전쟁 때문입니다.", "ex_en": "It is because of the Russia-Ukraine war."}]}', updated_at = now() where article_id = 'mn4tab0lcotu' and md5(grammar) = '10fe0292153eee5b4fed1d199d5f74b1';
update public.article_cache set grammar = '{"patterns": [{"name": "Past Tense -았어요/었어요", "level": "Starter", "exp": "Indicates a completed action in the past tense with polite/casual speech ending.", "ex_ko": "이 노래는 한국에서 1위를 했어요.", "ex_en": "This song ranked 1st in Korea."}, {"name": "그래서 (so, that''s why)", "level": "Starter", "exp": "Starts a sentence that gives the result of the previous one: ''so, that''s why''.", "ex_ko": "아이유는 일본어로도 노래를 불러요. 그래서 더 인기가 많아요.", "ex_en": "IU also sings in Japanese. That''s why she is even more popular."}]}', updated_at = now() where article_id = 'mn4tb76p6ibj' and md5(grammar) = '069bae26acbb664ea69b506d90892831';
update public.article_cache set grammar = '{"patterns": [{"name": "~고 있어요 (Present Progressive)", "level": "Beginner", "exp": "This pattern describes an action that is currently happening or in progress. It shows something that started in the past and continues now.", "ex_ko": "미국에서 한 돼지가 SNS에서 큰 인기를 <strong>얻고 있어요</strong>.", "ex_en": "A pig in America is currently gaining great popularity on SNS."}, {"name": "~라고 불려요 (Passive Voice / Being Called)", "level": "Beginner", "exp": "This pattern describes what something is called or named. The ~라고 불려요 structure means ''is called'' or ''is referred to as'' in a passive form.", "ex_ko": "그래서 <strong>\"말하는 돼지\"라고 불려요</strong>.", "ex_en": "That''s why it is called a ''talking pig''."}, {"name": "~아/어요 (Present Tense)", "level": "Beginner", "exp": "This is the basic present tense ending used for simple statements about facts or habitual actions. It is the most common way to express present tense in Korean.", "ex_ko": "이 돼지는 버튼을 눌러 의사 표현을 <strong>해요</strong>.", "ex_en": "This pig expresses its intention by pressing a button."}, {"name": "-고 있다고 말하다", "level": "Intermediate", "exp": "Reports what someone said about something ongoing: -고 있다 + -다고 + 말하다. 커지고 있다 → 커지고 있다고 말했어요 ''said that (it) is growing''.", "ex_ko": "전문가들은 동물의 지능에 대한 관심이 커지고 있다고 <strong>말했어요</strong>.", "ex_en": "Experts said that interest in animal intelligence is growing."}]}', updated_at = now() where article_id = 'mn4tt3oucwgc' and md5(grammar) = '3fd0631f24a1cc6ff05161c87e169e27';
update public.article_cache set grammar = '{"patterns": [{"name": "-기로 하다", "level": "Beginner", "exp": "Expresses a decision or agreement to do something: ''decide to''. 해결하다 → 해결하기로 했어요 ''decided to solve''.", "ex_ko": "독일과 프랑스가 에너지 문제를 함께 해결하기로 했어요.", "ex_en": "Germany and France decided to solve their energy problems together."}, {"name": "-아/어서 (reason)", "level": "Beginner", "exp": "Connects a reason to its result: ''because ..., so ...''. 막히다 → 막혀서 ''because (it) was blocked''.", "ex_ko": "러시아에서 가스를 사오던 길이 막혀서 어려워졌어요.", "ex_en": "Because the route for buying gas from Russia was blocked, things became difficult."}, {"name": "-(으)ㄹ 거예요", "level": "Beginner", "exp": "Expresses a future plan or prediction: ''will''. 보내주다 → 보내줄 거예요 ''will send''.", "ex_ko": "프랑스가 독일에 전기를 더 많이 보내줄 거예요.", "ex_en": "France will send more electricity to Germany."}]}', updated_at = now() where article_id = 'mn5n1khb6tua' and md5(grammar) = 'ce906d772243348fb9b46d659af19e90';
update public.article_cache set grammar = '{"patterns": [{"name": "-는 것으로 나타나다", "level": "Advanced", "exp": "Reports what a survey or study found: ''it turned out that ...''. 그만두다 → 그만두는 것으로 나타났어요.", "ex_ko": "한국 청년들이 첫 직장을 평균 2년 10개월 만에 그만두는 것으로 나타났어요.", "ex_en": "It turned out that young Koreans quit their first job after 2 years and 10 months on average."}, {"name": "-아/어야 한다고 (reported advice)", "level": "Advanced", "exp": "Reports advice or a claim that something must be done: -아/어야 하다 + -다고. 늘리다 → 늘려야 한다고 조언했습니다 ''advised that (they) should increase''.", "ex_ko": "회사들이 청년 직원들을 위한 복지 혜택과 성장 기회를 늘려야 한다고 조언했습니다.", "ex_en": "They advised that companies should increase welfare benefits and growth opportunities for young employees."}, {"name": "-(으)ㄹ 수 있다고 경고하다", "level": "Intermediate", "exp": "Reports a warning about what could happen: -(으)ㄹ 수 있다 + -다고 + 경고하다. 되다 → 될 수 있다고 경고했어요 ''warned that it could become''.", "ex_ko": "이런 현상이 한국 기업들의 인력 관리에 큰 문제가 될 수 있다고 경고했어요.", "ex_en": "They warned that this trend could become a major problem for how Korean companies manage their workforce."}]}', updated_at = now() where article_id = 'mn5p7gvu9rbt' and md5(grammar) = '0ccfd7336e1f286eb35749dd1c1f7441';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Starter", "exp": "Describes something that is happening now or keeps happening: ''be -ing''. 태어나다 → 태어나고 있어요.", "ex_ko": "한국에서 아기가 너무 적게 태어나고 있어요.", "ex_en": "Too few babies are being born in Korea."}, {"name": "-기 때문이다", "level": "Starter", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. 가야 하다 → 가야 하기 때문이에요.", "ex_ko": "아이들이 멀리 있는 학교에 가야 하기 때문이에요.", "ex_en": "It''s because children have to go to schools that are far away."}, {"name": "-(으)ㄹ 것이다 (prediction)", "level": "Starter", "exp": "Predicts a future event: ''will''. In notes and headlines the sentence can stop at 것: 닫다 → 닫을 것.", "ex_ko": "앞으로 10년 후에는 더 많은 학교가 문을 닫을 것", "ex_en": "Ten years from now, more schools will close."}]}', updated_at = now() where article_id = 'mn5qvixch28j' and md5(grammar) = '8bdec17d54060cba30bf2bcd3a41f32f';
update public.article_cache set grammar = '{"patterns": [{"name": "N + 이/가 V", "level": "Starter", "exp": "Subject particle marking the subject of a sentence", "ex_ko": "인도가 새로운 댐을 만들고 있어요.", "ex_en": "India is building a new dam."}, {"name": "-아/어야 해요", "level": "Starter", "exp": "Expresses obligation: ''have to, must''. 쓰다 → 써야 해요 ''have to use''.", "ex_ko": "두 나라는 인더스강의 물을 함께 써야 해요.", "ex_en": "The two countries have to share the water of the Indus River."}, {"name": "N + 으로/로", "level": "Starter", "exp": "Particle indicating cause, reason, or means", "ex_ko": "인도와 파키스탄이 물 문제로 갈등하고 있어요.", "ex_en": "India and Pakistan are in conflict over a water problem."}]}', updated_at = now() where article_id = 'mn5qvzjfma72' and md5(grammar) = '244d9bf47c8e6aa262c081569bec31aa';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄹ 것으로 예상되다", "level": "Advanced", "exp": "Passive future expectation pattern meaning ''it is expected/anticipated that...''. Used to express predictions or forecasts about future situations based on present analysis.", "ex_ko": "학생들과 저소득층에게 부담이 클 것으로 예상됩니다.", "ex_en": "It is expected that the burden will be large for students and low-income groups."}, {"name": "N을/를 이유로", "level": "Advanced", "exp": "''Citing N as the reason'': N을/를 이유로 + verb. 물가 상승을 이유로 설명했어요 = ''explained it by citing rising prices''.", "ex_ko": "서울시는 물가 상승과 운영비 증가를 이유로 설명했어요.", "ex_en": "Seoul City cited rising prices and higher operating costs as the reasons."}, {"name": "-(으)ㄹ 계획이다", "level": "Advanced", "exp": "Expresses a plan: ''plan to ...''. Attach it to the verb stem: 확대하다 → 확대할 계획입니다.", "ex_ko": "저소득층을 위한 할인 혜택도 확대할 계획입니다.", "ex_en": "(The city) also plans to expand discounts for low-income groups."}]}', updated_at = now() where article_id = 'mn5qyotfdvan' and md5(grammar) = 'c5a9b8e3ce274ed50ecdc7e33d0cfaae';
update public.article_cache set grammar = '{"patterns": [{"name": "-기로 하다", "level": "Intermediate", "exp": "Expresses a decision or agreement to do something: ''decide to''. 개발하다 → 개발하기로 했어요 ''decided to develop''.", "ex_ko": "베트남과 필리핀이 남중국해 해역에서 함께 석유를 개발하기로 했어요.", "ex_en": "Vietnam and the Philippines decided to develop oil together in the South China Sea."}, {"name": "-(으)면서", "level": "Intermediate", "exp": "Shows two things happening at the same time, or one change going along with another: ''while, as''. 일하다 → 일하면서.", "ex_ko": "두 나라가 함께 일하면서 남중국해 긴장이 줄어들 수 있다고 봅니다.", "ex_en": "(Experts) think tension in the South China Sea could ease as the two countries work together."}, {"name": "아직 -지 않았다", "level": "Intermediate", "exp": "Says something has not happened yet: ''has not ... yet''. 발표하다 → 아직 발표하지 않았어요.", "ex_ko": "중국 정부는 아직 이번 협정에 대해 공식 입장을 발표하지 않았어요.", "ex_en": "The Chinese government has not yet announced an official position on this agreement."}]}', updated_at = now() where article_id = 'mn5qz7c9kfdw' and md5(grammar) = '9591e35e2272bba5b149be44d1f305a6';
update public.article_cache set grammar = '{"patterns": [{"name": "~고 있어요", "level": "Beginner", "exp": "Progressive aspect pattern indicating an ongoing action or current state.", "ex_ko": "한국 가요계에서도 큰 화제가 되고 있어요.", "ex_en": "It is also becoming a hot topic in the Korean music industry."}]}', updated_at = now() where article_id = 'mn5r126m87bv' and md5(grammar) = '8ca3ff3074eccab9a5b683bafcd2c16a';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 수 있게 되다", "level": "Beginner", "exp": "Shows that a new ability or situation has come about: ''have become able to ...''. 먹다 → 먹을 수 있게 되었다.", "ex_ko": "우주비행사들이 우주에서 김치를 먹을 수 있게 되었다고 했어요.", "ex_en": "(It) said that astronauts are now able to eat kimchi in space."}, {"name": "N과/와 다르다", "level": "Beginner", "exp": "''Is different from N''. 와 follows a vowel and 과 a consonant: 일반 김치와 달라요 ''is different from regular kimchi''.", "ex_ko": "우주에서 먹는 김치는 일반 김치와 달라요.", "ex_en": "Kimchi eaten in space is different from regular kimchi."}, {"name": "-(으)ㄹ 예정이다", "level": "Beginner", "exp": "Expresses a planned or scheduled future action: ''be scheduled to''. 가다 → 갈 예정이에요.", "ex_ko": "한국 우주비행사가 4월에 우주정거장에 갈 예정이에요.", "ex_en": "A Korean astronaut is scheduled to go to the space station in April."}]}', updated_at = now() where article_id = 'mn5r1jq0sjbu' and md5(grammar) = '8b9fb38ffd60bca7d291e990fdd5408c';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Starter", "exp": "Describes something that is happening now or keeps happening: ''be -ing''. 줄어들다 → 줄어들고 있어요 ''is decreasing''.", "ex_ko": "한국에서 태어나는 아기 수가 너무 줄어들고 있어요.", "ex_en": "The number of babies born in Korea is falling sharply."}, {"name": "-아/어서 (reason)", "level": "Starter", "exp": "Connects a reason to its result: ''because ..., so ...''. 적다 → 적어서 ''because there are few''.", "ex_ko": "환자가 적어서 병원 운영이 어려워졌어요.", "ex_en": "Because there are few patients, running hospitals has become difficult."}, {"name": "-기로 하다", "level": "Starter", "exp": "Expresses a decision to do something: ''decide to''. 주다 → 주기로 했어요 ''decided to give''.", "ex_ko": "아기를 낳는 가족에게 더 많은 돈을 주기로 했어요.", "ex_en": "They decided to give more money to families who have babies."}]}', updated_at = now() where article_id = 'mn5r3l6oacvk' and md5(grammar) = 'c616aad71f9f0d88331be6b04c3d3b15';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어 있다 (resulting state)", "level": "Starter", "exp": "Describes a state that continues after an action is done. 들다 → 들어 있다 ''be in, be included''.", "ex_ko": "이 앨범에는 ''Seven''과 ''Standing Next to You'' 같은 인기 노래가 들어 있어요.", "ex_en": "This album includes popular songs like ''Seven'' and ''Standing Next to You''."}, {"name": "-ㄴ/는다고 말하다 (indirect speech)", "level": "Intermediate", "exp": "Reports what someone says. Add -ㄴ/는다고 to an action verb, then 말하다: 보여주다 → 보여준다고 말해요 ''say that it shows''.", "ex_ko": "정국의 성공이 K-pop의 힘을 보여준다고 말해요.", "ex_en": "(Experts) say that Jungkook''s success shows the power of K-pop."}]}', updated_at = now() where article_id = 'mn5r43ndoz4s' and md5(grammar) = 'fd6ead2995678086ed55f118ef86a367';
update public.article_cache set grammar = '{"patterns": [{"name": "N을/를 상대로", "level": "Beginner", "exp": "''Against N'', used for the other side in a lawsuit, match or negotiation. 유튜브와 메타를 상대로 낸 소송 = ''a lawsuit filed against YouTube and Meta''.", "ex_ko": "유튜브와 메타를 상대로 낸 소송", "ex_en": "a lawsuit filed against YouTube and Meta"}]}', updated_at = now() where article_id = 'mn6lk8x1gbv8' and md5(grammar) = '799fc9678d877d25905cadd98b0983ce';
update public.article_cache set grammar = '{"patterns": [{"name": "-지만", "level": "Beginner", "exp": "Connects two contrasting clauses: ''but, although''. 얻었다 → 얻었지만 ''won, but''.", "ex_ko": "현재 집권당이 가장 많은 표를 얻었지만, 과반은 얻지 못했어요.", "ex_en": "The current ruling party won the most votes, but it did not win a majority."}, {"name": "V-아/어야 해요", "level": "Beginner", "exp": "Expression indicating necessity or obligation, meaning ''have to'' or ''must''.", "ex_ko": "총리는 새 정부를 만들기 위해 다른 정당들과 어려운 협상을 해야 해요.", "ex_en": "The prime minister has to conduct difficult negotiations with other parties to form a new government."}]}', updated_at = now() where article_id = 'mn6lkuyibmwn' and md5(grammar) = '807052bd4efda46a0d21539b341523ba';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄴ 것 같다", "level": "Beginner", "exp": "Makes a guess about something that already happened: ''it seems (it) did ...''. 오다 → 온 것 같다 ''seems to have come''.", "ex_ko": "경찰은 이 시신들이 근처 병원과 시체 안치소에서 온 것 같다고 말했어요.", "ex_en": "Police said these bodies seem to have come from a nearby hospital and morgue."}]}', updated_at = now() where article_id = 'mn6llvu4epw9' and md5(grammar) = '25f3623d5dbf3798bfeeb37af4932400';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄴ/는다고 발표하다", "level": "Beginner", "exp": "Reports an announcement (indirect speech): statement + -ㄴ/는다고 + 발표하다. 쓰다 → 쓴다고 발표했어요 ''announced that he will write''.", "ex_ko": "스티븐 콜버트가 새로운 반지의 제왕 영화 각본을 쓴다고 발표했어요.", "ex_en": "Stephen Colbert announced that he will write the script for a new Lord of the Rings movie."}, {"name": "N(으)로 유명하다", "level": "Beginner", "exp": "''Be famous as / for N''. 열렬한 팬으로 유명해요 = ''is famous as a passionate fan''.", "ex_ko": "콜버트는 반지의 제왕 작가 톨킨의 열렬한 팬으로 유명해요.", "ex_en": "Colbert is famous as a passionate fan of Tolkien, the author of The Lord of the Rings."}, {"name": "-(으)ㄹ 예정이라고 하다", "level": "Beginner", "exp": "Passes on a plan you heard about: -(으)ㄹ 예정이다 ''be planned'' + -라고 하다 ''they say''. 만들다 → 만들 예정이라고 해요.", "ex_ko": "원작 소설의 앞부분을 영화로 만들 예정이라고 해요.", "ex_en": "They say they plan to turn the first part of the original novel into a movie."}]}', updated_at = now() where article_id = 'mn6ln8b36w1j' and md5(grammar) = 'cd69a68d3b58d1154f3eb5353d07a808';
update public.article_cache set grammar = '{"patterns": [{"name": "~ㄹ 수 있어요 (Possibility/ability)", "level": "Beginner", "exp": "Indicates possibility or potential occurrence of an action.", "ex_ko": "평소 사용하던 화장품이 갑자기 맞지 않을 수 있어요.", "ex_en": "Cosmetics you usually used might suddenly not suit you."}, {"name": "-는 것이 중요하다", "level": "Beginner", "exp": "Says that doing something is important: verb + -는 것 (makes it a noun) + 이 중요하다. 선택하다 → 선택하는 것이 중요해요.", "ex_ko": "임신 중에는 안전한 제품을 선택하는 것이 중요해요.", "ex_en": "During pregnancy, it is important to choose safe products."}]}', updated_at = now() where article_id = 'mnd8rxhnvuzi' and md5(grammar) = 'a2984a2025ae812f008be48be669deb9';
update public.article_cache set grammar = '{"patterns": [{"name": "~에 대한", "level": "Beginner", "exp": "Means ''about/concerning/regarding''. Used to indicate the topic or object of discussion.", "ex_ko": "화장품에 대한 거짓 정보", "ex_en": "False information about cosmetics"}, {"name": "-기 위해(서)", "level": "Beginner", "exp": "Expresses purpose: ''in order to''. Attach -기 위해 to the verb stem: 얻다 → 얻기 위해 ''in order to gain''.", "ex_ko": "고객의 믿음을 얻기 위해 노력해요", "ex_en": "They work hard to earn customers'' trust."}, {"name": "~아/어야 해요", "level": "Beginner", "exp": "Expresses obligation or necessity. Means ''must/have to/should''. The speaker recommends or requires an action.", "ex_ko": "소비자들은 화장품을 살 때 조심해야 해요", "ex_en": "Consumers must be careful when buying cosmetics"}]}', updated_at = now() where article_id = 'mnd8wkd43m7l' and md5(grammar) = 'bd823febd3ac83d946601715c45440e1';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있어요", "level": "Beginner", "exp": "Progressive aspect indicating an ongoing action or state in present tense", "ex_ko": "관광객이 많이 늘고 있어요.", "ex_en": "Tourists are increasing a lot."}, {"name": "-(으)려고 노력하다", "level": "Beginner", "exp": "''Try (hard) to ...'': -(으)려고 gives the goal and 노력하다 the effort. 관리하다 → 관리하려고 노력하고 있어요.", "ex_ko": "바하마 정부는 늘어나는 관광객을 잘 관리하려고 노력하고 있어요.", "ex_en": "The Bahamas government is trying to manage the growing number of tourists well."}, {"name": "-(으)면", "level": "Beginner", "exp": "Connecting ending meaning ''if'' or ''when''. 늘다 → 늘면 ''if (tourists) increase''.", "ex_ko": "관광객이 늘면 경제에도 도움이 돼요.", "ex_en": "If there are more tourists, it also helps the economy."}]}', updated_at = now() where article_id = 'mnd93z4zo6to' and md5(grammar) = '91f40442abe9b2a537ba447d6c739c9d';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Beginner", "exp": "Describes an action or situation in progress: ''be -ing''. 얻다 → 얻고 있어요 ''is gaining''.", "ex_ko": "한국 화장품이 전 세계에서 큰 인기를 얻고 있어요.", "ex_en": "Korean cosmetics are gaining great popularity around the world."}, {"name": "N 같은 (such as)", "level": "Beginner", "exp": "Gives examples before a noun: ''N such as ...''. A, B, C 같은 회사들 = ''companies such as A, B and C''.", "ex_ko": "토니모리(Tony Moly), 아모레퍼시픽(AmorePacific), 설화수(Sulwhasoo) 같은 한국 화장품 회사들이 세계적으로 유명해졌어요.", "ex_en": "Korean cosmetics companies such as Tony Moly, AmorePacific and Sulwhasoo have become famous worldwide."}, {"name": "N(으)로 유명하다", "level": "Beginner", "exp": "''Be famous for / as N''. 피부 관리 제품으로 유명해요 = ''is famous for skincare products''.", "ex_ko": "한국 화장품은 특히 피부 관리 제품으로 유명해요.", "ex_en": "Korean cosmetics are especially famous for their skincare products."}]}', updated_at = now() where article_id = 'mnd94ffgf964' and md5(grammar) = '54586d850f4f64728b8e647286af558d';
update public.article_cache set grammar = '{"patterns": [{"name": "-(이)라는 + noun", "level": "Beginner", "exp": "Quotes a name or phrase to describe a noun: ''the N called / saying ...''. ''90년대 어떻게 살았나요?''라는 질문 = ''the question How did you live in the 90s?''.", "ex_ko": "요즘 인터넷에서 ''90년대 어떻게 살았나요?''라는 질문이 인기예요.", "ex_en": "These days the question ''How did you live in the 90s?'' is popular online."}, {"name": "~고 있어요", "level": "Beginner", "exp": "Present progressive form indicating an ongoing action or continuous state", "ex_ko": "많은 사람들이 자신의 90년대 이야기를 나누고 있어요.", "ex_en": "Many people are sharing their stories from the 90s."}, {"name": "~는 거예요", "level": "Beginner", "exp": "Explanatory ending that provides reasoning or clarification about a situation", "ex_ko": "그 시절 음악, 패션, 생활 모습을 그리워하는 거예요.", "ex_en": "It''s that they miss the music, fashion, and lifestyle of that time."}]}', updated_at = now() where article_id = 'mnd95czf3sb3' and md5(grammar) = '9c08c7d439eaac54670d33ba28591e65';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ까요?", "level": "Beginner", "exp": "Asks a question to suggest something or get the listener thinking: ''shall we ...?, what should we ...?''. 넣다 → 넣을까요?", "ex_ko": "불안 가방에는 어떤 것들을 <strong>넣을까요?</strong>", "ex_en": "What kinds of things should we put in an anxiety bag?"}, {"name": "N(이)나 (or)", "level": "Beginner", "exp": "Joins nouns as choices: ''or''. Use 나 after a vowel and 이나 after a consonant: 향수나 캔디 ''perfume or candy''.", "ex_ko": "좋아하는 향수나 캔디, 작은 인형 <strong>같은 것들</strong>을 넣어요.", "ex_en": "We put in things like a favorite perfume or candy, or a small doll."}, {"name": "''-아/어지다'' (becoming/getting - expressing change of state)", "level": "Beginner", "exp": "Shows that something changes or becomes a certain state. When you do an action, the result is that something becomes different.", "ex_ko": "마음이 힘들 때 이런 물건들을 만지거나 냄새를 맡으면 기분이 <strong>좋아져요.</strong>", "ex_en": "When you touch or smell these things when your mind is troubled, your mood becomes better."}, {"name": "''-으면 되다'' (if you do this, it will be fine/work)", "level": "Beginner", "exp": "Means ''if you do this, it will work'' or ''it''s okay if you do this.'' It shows that something simple is sufficient to achieve a goal.", "ex_ko": "작은 가방을 준비하고 자신이 좋아하는 물건들을 <strong>넣으면 돼요.</strong>", "ex_en": "If you prepare a small bag and put things you like in it, that will work."}]}', updated_at = now() where article_id = 'mnd95sw1bs0h' and md5(grammar) = 'd5fb86e078290d4eb9819305b7b1174a';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Beginner", "exp": "Describes an action or situation in progress: ''be -ing''. 끌다 → 인기를 끌고 있어요 ''is gaining popularity''.", "ex_ko": "중국에서 특별한 놀이가 인기를 끌고 있어요.", "ex_en": "A special kind of play is gaining popularity in China."}, {"name": "-는 것이 중요하다", "level": "Beginner", "exp": "Says that doing something is important: verb + -는 것 (makes it a noun) + 이 중요하다. 하다 → 하는 것이 중요해요.", "ex_ko": "안전한 놀이를 하는 것이 중요해요.", "ex_en": "It is important to play safely."}, {"name": "-아/어야 하다", "level": "Beginner", "exp": "Expresses obligation: ''must, have to''. 놀다 → 놀아야 해요 ''have to play''.", "ex_ko": "위험하지 않게 조심해서 놀아야 해요.", "ex_en": "You have to play carefully so that it is not dangerous."}]}', updated_at = now() where article_id = 'mnd969wre1l9' and md5(grammar) = '59b11db80662258e0c1731eb106d9ce9';
update public.article_cache set grammar = '{"patterns": [{"name": "N이/가 되다", "level": "Beginner", "exp": "''To become N'': the noun takes 이/가 and is followed by 되다. 인기 검색어가 되었어요 = ''became a popular search term''.", "ex_ko": "미국에서 ''타이거스 개막일''이 인기 검색어가 되었어요.", "ex_en": "In the US, ''Tigers Opening Day'' became a popular search term."}, {"name": "~다는 뜻이에요 (means that~)", "level": "Beginner", "exp": "Expresses the meaning or implication of something mentioned before", "ex_ko": "새 시즌에 대한 기대가 크다는 뜻이에요.", "ex_en": "It means that expectations for the new season are high."}]}', updated_at = now() where article_id = 'mniwy2paxs7b' and md5(grammar) = '62f066f1d9897b397ef497e16efb933c';
update public.article_cache set grammar = '{"patterns": [{"name": "Ability expression -을 수 있어요", "level": "Beginner", "exp": "Used to express the ability or possibility to do something.", "ex_ko": "휘찬은 이제 다시 음악 활동을 할 수 있어요.", "ex_en": "Hwichan can now resume music activities again."}]}', updated_at = now() where article_id = 'mniwz14v91tz' and md5(grammar) = '2827be40f32e14a0fdbb92d1529159f9';
update public.article_cache set grammar = '{"patterns": [{"name": "~았/었어요", "level": "Beginner", "exp": "Past tense ending used to describe completed actions or states in casual polite speech", "ex_ko": "서울이 아시아에서 가장 좋은 여행 도시로 선택되었어요.", "ex_en": "Seoul was selected as the best travel city in Asia."}, {"name": "~때문에", "level": "Beginner", "exp": "Means ''because of'' or ''due to'' and indicates the reason or cause for something", "ex_ko": "이런 경험들 때문에 서울이 1위가 되었어요.", "ex_en": "Because of these experiences, Seoul became number one."}, {"name": "-(으)ㄹ 것 같다", "level": "Beginner", "exp": "Expresses a guess about the future: ''it seems (it) will ...''. 되다 → 될 것 같아요.", "ex_ko": "이번 발표는 서울의 매력을 세계에 알리는 좋은 기회가 될 것 같아요.", "ex_en": "This announcement seems likely to be a good chance to show Seoul''s charm to the world."}]}', updated_at = now() where article_id = 'mniwzw39eqt0' and md5(grammar) = 'b8d1cb09d57e73516fd664a4ca475c3d';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄴ/는다고 발표하다", "level": "Beginner", "exp": "Reports an announcement (indirect speech): statement + -ㄴ/는다고 + 발표하다. 떠나다 → 떠난다고 발표했어요 ''announced that he is leaving''.", "ex_ko": "마크가 팀을 떠난다고 발표했어요.", "ex_en": "Mark announced that he is leaving the team."}, {"name": "-는 + noun (describing a noun)", "level": "Beginner", "exp": "Turns a verb into a describing phrase before a noun. 응원하다 → 응원하는 메시지 ''a message cheering (him) on''.", "ex_ko": "NCT 멤버들이 마크를 응원하는 메시지를 남겼어요.", "ex_en": "NCT members left messages cheering Mark on."}, {"name": "-(으)ㄹ 것 같다", "level": "Beginner", "exp": "Expresses a guess about the future: ''it seems (he) will ...''. 보여주다 → 보여줄 것 같아요.", "ex_ko": "마크도 새로운 길에서 좋은 모습을 보여줄 것 같아요.", "ex_en": "It seems Mark will do well on his new path too."}]}', updated_at = now() where article_id = 'mnix0t6vpbh1' and md5(grammar) = 'bfc3306f1ba79fd1c93a73d367a80bd6';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Beginner", "exp": "Describes an action or situation in progress: ''be -ing''. 즐기다 → 즐기고 있어요 ''are enjoying''.", "ex_ko": "인도 사람들이 새로운 여행을 즐기고 있어요.", "ex_en": "Indian people are enjoying a new kind of travel."}, {"name": "~ㄹ 수 있어요 (Can/Able to)", "level": "Beginner", "exp": "Indicates the ability or possibility to do something.", "ex_ko": "그 나라의 음식과 문화를 쉽게 알 수 있어요.", "ex_en": "You can easily learn about that country''s food and culture."}, {"name": "-기 때문이다", "level": "Beginner", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. 알 수 있다 → 알 수 있기 때문이에요.", "ex_ko": "그 나라의 음식과 문화를 쉽게 알 수 있기 때문이에요.", "ex_en": "It''s because you can easily learn about that country''s food and culture."}]}', updated_at = now() where article_id = 'mnix1966bwrb' and md5(grammar) = '6656642c2945c0b35c8cb52a4350caa1';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Beginner", "exp": "Describes something that is happening now or keeps happening: ''be -ing''. 1위를 하다 → 1위를 하고 있어요 ''is ranking first''.", "ex_ko": "BTS가 부른 ''아리랑''이 호주 ARIA 차트에서 계속 1위를 하고 있어요.", "ex_en": "BTS''s ''Arirang'' keeps ranking first on Australia''s ARIA chart."}, {"name": "-아/어서 (reason)", "level": "Beginner", "exp": "Links a cause to its result: ''because ..., so ...''. 만들다 → 만들어서 ''because (they) made''.", "ex_ko": "BTS가 현대적으로 새롭게 만들어서 전 세계 사람들이 좋아하고 있어요.", "ex_en": "Because BTS remade it in a modern way, people around the world love it."}, {"name": "-(으)ㄹ 것 같다", "level": "Beginner", "exp": "Expresses a guess about the future: ''it seems (it) will ...''. 높아지다 → 높아질 것 같아요.", "ex_ko": "K-pop의 인기가 더욱 높아질 것 같아요.", "ex_en": "It seems that K-pop will become even more popular."}]}', updated_at = now() where article_id = 'mnix1pa5xd6s' and md5(grammar) = '60a1ac5b6cfc67f899c111ae77e6285c';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어서", "level": "Beginner", "exp": "Indicates reason or cause. ''-아서'' is used after vowels ㅏ,ㅗ and ''-어서'' after other vowels", "ex_ko": "물가가 많이 올라서 사람들이 힘들어해요.", "ex_en": "Because prices rose a lot, people are struggling."}, {"name": "-고 있어요", "level": "Beginner", "exp": "Progressive aspect showing an ongoing or continuous action in the present", "ex_ko": "인터넷에서 이 지도가 빠르게 퍼지고 있어요.", "ex_en": "This map is spreading rapidly on the internet."}, {"name": "-고 (and then)", "level": "Beginner", "exp": "Links two actions in order: ''do A and then B''. 보다 → 보고 찾아가요 ''look at (it) and then go find''.", "ex_ko": "많은 사람들이 이 지도를 보고 싼 음식점을 찾아가요.", "ex_en": "Many people look at this map and then go to find cheap restaurants."}]}', updated_at = now() where article_id = 'mnlx40ti37zv' and md5(grammar) = 'e7729bf499ea23199a412226812471a7';
update public.article_cache set grammar = '{"patterns": [{"name": "~고 있어요", "level": "Beginner", "exp": "Indicates an ongoing or continuous action in the present tense.", "ex_ko": "한국의 벚꽃나무 사진이 외국 사람들에게 인기를 얻고 있어요.", "ex_en": "Korean cherry blossom tree photos are gaining popularity among foreign people."}]}', updated_at = now() where article_id = 'mnlx4frvytvj' and md5(grammar) = 'c06dcdaa89e5d1b61fd0546434146f0f';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄴ + noun (past modifier)", "level": "Beginner", "exp": "Describes a noun with a completed action. 사용하다 → 사용한 카메라 ''the camera (he) used''.", "ex_ko": "그가 사용한 카메라는 펜탁스 ME 슈퍼예요.", "ex_en": "The camera he used is a Pentax ME Super."}, {"name": "~기 때문이다", "level": "Intermediate", "exp": "A causal pattern meaning ''because'' or ''due to the fact that'', used to explain reasons.", "ex_ko": "K-pop과 한국 문화에 관심이 많기 때문입니다.", "ex_en": "It is because they have a lot of interest in K-pop and Korean culture."}]}', updated_at = now() where article_id = 'mnlx4uk1m23v' and md5(grammar) = '496405e757adb65249231a8ad9c66f4d';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면 안 되다", "level": "Beginner", "exp": "Says something is not allowed or should not be done: ''must not''. 먹다 → 먹으면 안 되는 이유 ''the reason you must not eat''.", "ex_ko": "도서관에서 음식을 먹으면 안 되는 이유", "ex_en": "The reason you should not eat food in the library"}, {"name": "-(으)면", "level": "Beginner", "exp": "Connecting ending meaning ''if'' or ''when''. 먹다 → 먹으면 ''if you eat''.", "ex_ko": "음식을 먹으면 냄새가 나요", "ex_en": "If you eat food, it leaves a smell."}, {"name": "-(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses possibility or ability: ''can, could''. 더러워지다 → 더러워질 수 있어요 ''can get dirty''.", "ex_ko": "책이 더러워질 수 있어요", "ex_en": "Books can get dirty."}]}', updated_at = now() where article_id = 'mnlx5aoxtzll' and md5(grammar) = '3ac5463ccbb2d6fb582efb4495e4014c';
update public.article_cache set grammar = '{"patterns": [{"name": "-어서/-아서", "level": "Intermediate", "exp": "Connective ending that expresses reason, cause, or sequence of actions", "ex_ko": "K-pop을 좋아해서 한국에 관심을 갖게 됐어요.", "ex_en": "Because he likes K-pop, he became interested in Korea."}, {"name": "-고 싶다", "level": "Beginner", "exp": "Expresses a desire or wish to do something", "ex_ko": "다음에는 서울도 가보고 싶다고 했어요.", "ex_en": "He said he wants to visit Seoul next time."}]}', updated_at = now() where article_id = 'mnlx5rq9xcwt' and md5(grammar) = 'f9fad169a82833a357ecb7fc29195f8e';
update public.article_cache set grammar = '{"patterns": [{"name": "~다고 했어요 (reported speech)", "level": "Starter", "exp": "Used to report what someone said or claimed in the past.", "ex_ko": "사촌 언니가 급한 일이 있다고 했어요.", "ex_en": "Her cousin said she had an urgent matter."}, {"name": "~(으)면 안 돼요 (prohibition/should not)", "level": "Starter", "exp": "Used to express that something should not be done or is not allowed.", "ex_ko": "가족끼리도 거짓말하면 안 돼요.", "ex_en": "Family members should not lie to each other."}]}', updated_at = now() where article_id = 'mnobw7yw5gk4' and md5(grammar) = 'fe74bb2cdfe96391700c1689c01f7a1b';
update public.article_cache set grammar = '{"patterns": [{"name": "-기 때문이다", "level": "Starter", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. 했다 → 했기 때문이에요.", "ex_ko": "남자친구가 무서운 말을 했기 때문이에요.", "ex_en": "It''s because the boyfriend said something scary."}, {"name": "~어야 할지 (Whether one should/need to)", "level": "Intermediate", "exp": "Expresses uncertainty about what one should do in a situation.", "ex_ko": "남자친구와 헤어져야 할지 고민하고 있어요.", "ex_en": "She is worrying about whether she should break up with her boyfriend."}]}', updated_at = now() where article_id = 'mnobx71kzdrd' and md5(grammar) = 'c095ca9ac3a9b9c0e5b9414dc38ab531';
update public.article_cache set grammar = '{"patterns": [{"name": "-다가", "level": "Starter", "exp": "Shows that something else happened in the middle of an action: ''while doing ..., (suddenly)''. 보다 → 보다가.", "ex_ko": "면접을 보다가 정체가 드러났어요.", "ex_en": "His identity was revealed in the middle of a job interview."}, {"name": "N(이)라는 것", "level": "Starter", "exp": "''The fact that it is N'': N(이)라는 것을 알다 ''find out that it is N''. 해커라는 것을 알게 됐어요 = ''came to know that (he) was a hacker''.", "ex_ko": "북한에서 온 해커라는 것을 알게 됐어요.", "ex_en": "They found out that he was a hacker from North Korea."}]}', updated_at = now() where article_id = 'mnobxme6ahqe' and md5(grammar) = '51c086e1d99135c2185487ad177e0f3b';
update public.article_cache set grammar = '{"patterns": [{"name": "-다는 것 (the fact that)", "level": "Intermediate", "exp": "Turns a whole statement into a noun: ''the fact that ...''. 거짓말을 했다 → 거짓말을 했다는 것을 알았어요 ''found out that (she) had lied''.", "ex_ko": "나중에 여성은 사촌이 거짓말을 했다는 것을 알았어요.", "ex_en": "Later, the woman found out that her cousin had lied."}]}', updated_at = now() where article_id = 'mnobzzvruuu5' and md5(grammar) = 'c78f22a4ac0268ca72c7e6e9a17b1cfa';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면 어떨까요?", "level": "Beginner", "exp": "''What if ...?, how about ...?'': imagines or suggests a situation. 생기다 → 생기면 어떨까요?", "ex_ko": "이런 똑똑한 화장실이 한국에도 생기면 어떨까요?", "ex_en": "What if smart bathrooms like this appeared in Korea too?"}, {"name": "~지 않아도 돼요", "level": "Beginner", "exp": "Expression meaning ''don''t have to'' or ''no need to'' indicating something is not necessary", "ex_ko": "이제 문을 두드리지 않아도 돼요.", "ex_en": "Now you don''t have to knock on the door."}]}', updated_at = now() where article_id = 'mnoc0h7d8kkw' and md5(grammar) = 'e3cf89466bff6fed193579dc312a18c1';
update public.article_cache set grammar = '{"patterns": [{"name": "~게 되었습니다 (came to/became)", "level": "Beginner", "exp": "Expresses a change of state or situation that occurred naturally or unexpectedly", "ex_ko": "그녀는 지금까지의 연인 관계를 다시 생각해보게 되었습니다.", "ex_en": "She came to reconsider their relationship so far."}, {"name": "-(으)ㄹ 수도 있다", "level": "Beginner", "exp": "Says something might possibly happen: ''could, might''. 도 makes it softer than -(으)ㄹ 수 있다: 만들다 → 만들 수도 있다.", "ex_ko": "진실이 관계를 어렵게 만들 수도 있다고 합니다.", "ex_en": "They say the truth can sometimes make a relationship difficult."}]}', updated_at = now() where article_id = 'mnoc0tn8uk0o' and md5(grammar) = 'e4186bc59a87b2b4dd3b75f4e29a8185';
update public.article_cache set grammar = '{"patterns": [{"name": "-았/었어요", "level": "Beginner", "exp": "Past tense ending used to describe completed actions or states in casual polite speech", "ex_ko": "1981년에 영화가 큰 상을 받았어요.", "ex_en": "In 1981, the movie received a big award."}, {"name": "-기 때문이다", "level": "Beginner", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. 만들었다 → 만들었기 때문이에요.", "ex_ko": "늑대인간으로 변하는 모습을 정말 잘 만들었기 때문이에요.", "ex_en": "It''s because they made the transformation into a werewolf really well."}, {"name": "-도", "level": "Beginner", "exp": "Particle meaning ''also'' or ''even''; adds emphasis or shows inclusion", "ex_ko": "메이크업 부분에서도 최고 상을 받았어요.", "ex_en": "It also received the top award in the makeup category."}]}', updated_at = now() where article_id = 'mnp8ef0q0vp5' and md5(grammar) = '1b63c5e7118be47c89584df67cccf90e';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Intermediate", "exp": "Shows two actions happening at the same time: ''while''. 받다 → 받으면서 ''while receiving''.", "ex_ko": "이 식물들은 햇빛을 받<strong>으면서</strong> 광합성(photosynthesis)을 해요.", "ex_en": "These plants carry out photosynthesis while taking in sunlight."}, {"name": "보기에도 + adjective", "level": "Intermediate", "exp": "보기에 means ''to look at, in appearance''; 도 adds ''also''. 보기에도 아름다워요 = ''is also beautiful to look at''.", "ex_ko": "물속에서는 이 산소가 작은 거품 형태로 나타나 <strong>보기에도 아름다워요</strong>.", "ex_en": "In the water, this oxygen appears as small bubbles, which are also beautiful to look at."}, {"name": "-(으)ㄹ 수 있다", "level": "Intermediate", "exp": "Expresses possibility or ability: ''can''. Here it ends with the friendly -답니다 (''you know''): 관찰하다 → 관찰할 수 있답니다.", "ex_ko": "특히 여름철 햇빛이 강할 때 더 많은 산소 거품을 관찰<strong>할 수 있답니다</strong>.", "ex_en": "Especially in summer, when the sunlight is strong, you can see even more oxygen bubbles."}, {"name": "-는 역할도 하다", "level": "Intermediate", "exp": "''Also play the role of ...'': adds another function. 만들다 → 깨끗하게 만드는 역할도 해요 ''also help make (the water) clean''.", "ex_ko": "또한 물을 깨끗하게 만드는 <strong>역할도 해요</strong>.", "ex_en": "They also help make the water clean."}]}', updated_at = now() where article_id = 'mnwpe54dtll9' and md5(grammar) = '3be03005c53b129d4919b0a87c54ded7';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어지다 (become)", "level": "Beginner", "exp": "Shows a change of state: ''become ...''. 유명하다 → 유명해지다 ''become famous''; past: 유명해졌어요.", "ex_ko": "미국에서 원숭이 한 마리가 인터넷에서 유명해졌어요.", "ex_en": "A monkey in America became famous on the internet."}, {"name": "~(으)ㄹ 때도 (even when, also when)", "level": "Beginner", "exp": "Used to indicate that an action or state occurs in multiple situations or at multiple times.", "ex_ko": "먹을 때도, 잠을 잘 때도 인형을 안고 있어요.", "ex_en": "The monkey holds the doll even when eating and even when sleeping."}, {"name": "-아/어서 (reason)", "level": "Beginner", "exp": "Connects a reason to its result: ''because ..., so ...''. 귀엽다 → 귀여워서 ''because (it) is cute''.", "ex_ko": "이 모습이 너무 귀여워서 많은 사람들이 좋아해요.", "ex_en": "Because it looks so cute, many people love it."}]}', updated_at = now() where article_id = 'mo1fwwdoul77' and md5(grammar) = 'ae20ed721023f9bac60dcb55a2b03c9f';
update public.article_cache set grammar = '{"patterns": [{"name": "-았어요 / -었어요", "level": "Beginner", "exp": "Past tense ending used to describe completed actions or states in polite/casual speech", "ex_ko": "천문학자들이 블랙홀에서 나오는 제트의 힘과 속도를 처음 측정했어요.", "ex_en": "Astronomers measured the power and speed of jets from black holes for the first time."}, {"name": "-는 + noun (describing a noun)", "level": "Beginner", "exp": "Describes a noun with an action: 나오다 → 나오는 물질 ''material that comes out''.", "ex_ko": "블랙홀 제트는 블랙홀 주변에서 나오는 매우 빠른 물질의 흐름이에요.", "ex_en": "A black hole jet is a stream of very fast material coming out from around a black hole."}, {"name": "-고 있다", "level": "Beginner", "exp": "Describes an ongoing action: ''be -ing''. Here it ends with the friendly -답니다: 발전시키다 → 발전시키고 있답니다.", "ex_ko": "우리나라도 우주과학 기술을 계속 발전시키고 있답니다.", "ex_en": "Korea, too, keeps developing its space science technology."}]}', updated_at = now() where article_id = 'mo1fxedxwqhn' and md5(grammar) = '0f4537ffb5267a4534e50a15f5358088';
update public.article_cache set grammar = '{"patterns": [{"name": "N이에요/예요", "level": "Beginner", "exp": "Polite ''to be'' ending after a noun: 이에요 after a consonant, 예요 after a vowel. 모양이에요 = ''is the shape (of)''.", "ex_ko": "닭고기가 미국 지도 모양이<strong>에요</strong>.", "ex_en": "The chicken is shaped like a map of the US."}, {"name": "~았/었어요 (Past Tense Ending)", "level": "Beginner", "exp": "This ending describes completed actions or events in the past. It also conjugates based on the final vowel of the verb stem.", "ex_ko": "한 사람이 닭고기를 요리<strong>했어요</strong>.", "ex_en": "A person cooked the chicken."}, {"name": "~와/과 똑같이 (Same as / Identical to)", "level": "Beginner", "exp": "This pattern means ''the same as'' or ''identical to.'' It is used to compare two things that look or function the same way.", "ex_ko": "닭고기 껍질이 미국 지도<strong>와 똑같이</strong> 생겼어요.", "ex_en": "The chicken skin looked identical to the US map."}, {"name": "-(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses possibility or ability: ''can''. 닮다 → 닮을 수 있어요 ''can resemble''.", "ex_ko": "음식이 다른 모양<strong>을 닮을 수 있어요</strong>.", "ex_en": "Food can resemble other shapes."}]}', updated_at = now() where article_id = 'mo4a4rxe3lbc' and md5(grammar) = '2e647b9777a614fcc74ca7adf5f1fdbc';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Intermediate", "exp": "Describes something happening now or continuing: ''be -ing''. 주목받다 → 주목받고 있어요 ''is getting attention''.", "ex_ko": "미용업계에서 ''그레이 블렌딩''이 주목받고 있어요.", "ex_en": "''Gray blending'' is getting attention in the beauty industry."}, {"name": "-지 않는 + noun", "level": "Beginner", "exp": "A negative verb describing a noun: -지 않다 → -지 않는 + noun, ''a ... that does not ...''. 가리지 않는 방법 = ''a method that does not hide''.", "ex_ko": "흰머리를 완전히 염색으로 가리지 않는 방법이에요.", "ex_en": "It is a method that does not completely cover gray hair with dye."}, {"name": "-(으)면서", "level": "Intermediate", "exp": "''As'': shows one change going along with another. 나이가 들다 → 나이가 들면서 ''as (people) get older''.", "ex_ko": "나이가 들면서 생기는 흰머리를 부정적으로 보지 않아요.", "ex_en": "They do not see the gray hair that comes with age as something negative."}]}', updated_at = now() where article_id = 'mo4a5topvurc' and md5(grammar) = '8e7f5a59f9ee468596479cf97b7159fc';
update public.article_cache set grammar = '{"patterns": [{"name": "-에 대한", "level": "Intermediate", "exp": "Means ''about'' or ''regarding''; indicates the topic or object of discussion", "ex_ko": "''인터폴(Interpol)''에 대한 검색량이 크게 늘어났습니다.", "ex_en": "Search volume regarding ''Interpol'' has greatly increased."}, {"name": "-(으)ㄹ 때", "level": "Intermediate", "exp": "Means ''when, at the time of (doing)''. 추적하다 → 추적할 때 ''when tracking''.", "ex_ko": "범죄자를 추적할 때 협력하는 국제기구예요.", "ex_en": "It is an international organization that cooperates when tracking criminals."}, {"name": "-을 것으로 추정되다", "level": "Intermediate", "exp": "Means ''is presumed to'' or ''is estimated to''; expresses conjecture or assumption", "ex_ko": "최근 국제적인 사건이나 영화와 관련이 있을 것으로 추정돼요.", "ex_en": "It is presumed to be related to recent international incidents or movies."}]}', updated_at = now() where article_id = 'mo5c8crvyftq' and md5(grammar) = 'c5cc15fc3b70b242f277c178d0fbd113';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어요", "level": "Beginner", "exp": "Present tense polite ending used to state facts or describe current situations", "ex_ko": "BTS의 멤버 뷔가 미국 유명 잡지에 나와요", "ex_en": "BTS member V appears in a famous American magazine"}, {"name": "-(으)ㄴ + noun (adjective modifier)", "level": "Beginner", "exp": "Turns an adjective into a describing word before a noun. 멋지다 → 멋진 사진 ''cool photos''.", "ex_ko": "잡지 안에는 뷔의 멋진 사진들도 많이 있어요", "ex_en": "There are also many great photos of V in the magazine."}, {"name": "-고 있어요", "level": "Beginner", "exp": "Describes an action or feeling that is going on now: ''be -ing''. 기뻐하다 → 기뻐하고 있어요.", "ex_ko": "팬들은 매우 기뻐하고 있어요", "ex_en": "The fans are very happy."}]}', updated_at = now() where article_id = 'mo5s7gxf93rq' and md5(grammar) = '5b40ec34eabf682a12bb7db27df17a7e';
update public.article_cache set grammar = '{"patterns": [{"name": "-았/었어요 (past polite)", "level": "Starter", "exp": "Polite past-tense ending for something that already happened. 나오다 → 나왔어요 ''came out''.", "ex_ko": "새로운 연습용 마네킹 머리가 나왔어요.", "ex_en": "A new practice mannequin head has come out."}, {"name": "N + 이에요/예요", "level": "Starter", "exp": "Copula to identify or describe nouns in present tense polite form", "ex_ko": "이름은 다이앤 에스테틱 마네킹이에요.", "ex_en": "The name is Diane Aesthetic Mannequin."}, {"name": "V + 을/ㄹ 때", "level": "Starter", "exp": "Temporal expression meaning ''when'' or ''while doing something''", "ex_ko": "마사지나 화장을 배울 때 써요.", "ex_en": "We use it when learning massage or makeup."}]}', updated_at = now() where article_id = 'mo5s7xz0pn61' and md5(grammar) = '5b0f28ce99751e384799d4868a112b02';
update public.article_cache set grammar = '{"patterns": [{"name": "V-ㄴ/은 N (Past Participle Modifier)", "level": "Intermediate", "exp": "Used to modify a noun with a past participle form, indicating a completed action", "ex_ko": "교과서에 나온 시계 방향 설명", "ex_en": "The explanation of clockwise direction that appeared in the textbook"}, {"name": "-기 때문이다", "level": "Intermediate", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. Attach -기 to a verb: 나와 있었다 → 나와 있었기 때문입니다.", "ex_ko": "시계 방향에 대한 설명이 나와 있었기 때문입니다", "ex_en": "It is because there was an explanation of the clockwise direction."}, {"name": "V-으면서 (While/As)", "level": "Intermediate", "exp": "Indicates two actions occurring simultaneously or one action leading to another", "ex_ko": "아날로그 시계를 보는 경우가 줄어들면서 이런 설명이 필요해진 것", "ex_en": "As the cases of looking at analog clocks decreased, such explanations became necessary"}]}', updated_at = now() where article_id = 'mo5s8fzu38je' and md5(grammar) = 'fe83dfc79cfb5edafe29e1a2b1c22350';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Intermediate", "exp": "''As'': shows one change going along with another. 나이가 들다 → 나이가 들면서 ''as one gets older''.", "ex_ko": "나이가 들면서 속눈썹이 얇아진다", "ex_en": "As one ages, eyelashes become thinner."}, {"name": "-(으)ㄹ수록", "level": "Advanced", "exp": "''The more ..., the more ...'': one thing increases as another does. 들다 → 나이가 들수록 ''the older one gets''.", "ex_ko": "나이가 들수록 피부가 민감해진다", "ex_en": "The older one gets, the more sensitive the skin becomes."}, {"name": "-는 것이 장점이다", "level": "Advanced", "exp": "Names an advantage: ''the good thing is that ...''. 유지되다 → 유지되는 것이 장점이다.", "ex_ko": "번짐 없이 유지되는 것이 장점이다", "ex_en": "Its advantage is that it stays on without smudging."}]}', updated_at = now() where article_id = 'mo5s9nb3b9b0' and md5(grammar) = '95feb6fc87009d9a0679a11e8d4c6548';
update public.article_cache set grammar = '{"patterns": [{"name": "-기로 하다", "level": "Starter", "exp": "Expresses a decision: ''decide to''. 쓰다 → 쓰기로 했어요 ''decided to use''.", "ex_ko": "마이크로소프트 프로그램을 덜 쓰기로 했어요.", "ex_en": "They decided to use Microsoft programs less."}, {"name": "N이에요/예요", "level": "Starter", "exp": "Polite ''to be'' ending after a noun: 이에요 after a consonant, 예요 after a vowel. 회사예요 = ''is a company''.", "ex_ko": "마이크로소프트는 미국 회사예요.", "ex_en": "Microsoft is an American company."}, {"name": "-(으)려고 하다", "level": "Starter", "exp": "Expresses an intention or plan: ''intend to, plan to''. 쓰다 → 쓰려고 해요.", "ex_ko": "그래서 다른 프로그램도 쓰려고 해요.", "ex_en": "So they plan to use other programs too."}]}', updated_at = now() where article_id = 'mo5sa7hlo7ta' and md5(grammar) = '775d969646150c9dc1eaa2afe2191d6b';
update public.article_cache set grammar = '{"patterns": [{"name": "V + -(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses possibility or ability; ''can/could/be able to''", "ex_ko": "8700만 명의 생명을 구할 수 있었다", "ex_en": "Could have saved the lives of 87 million people"}, {"name": "-았/었으면 좋았을 것이다", "level": "Beginner", "exp": "Expresses regret about the past: ''it would have been better if ...''. 쓰다 → 썼으면 더 좋았을 것이다.", "ex_ko": "의료나 식량 지원에 썼으면 더 좋았을 것이다", "ex_en": "It would have been better if it had been spent on medical care or food aid."}, {"name": "N + 보다 + V", "level": "Beginner", "exp": "Comparison particle; ''more than/rather than''", "ex_ko": "전쟁보다 평화에 더 많은 관심을 가져야 한다", "ex_en": "Should pay more attention to peace rather than war"}]}', updated_at = now() where article_id = 'mo7toohv93g0' and md5(grammar) = 'cd25004bdca9f36e4df64adaad0e3f8c';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어지다 (become)", "level": "Starter", "exp": "Shows a change of state: 많다 → 많아지다 ''become many, increase''; past: 많아졌어요.", "ex_ko": "요즘 인공지능을 좋아하지 않는 사람들이 많아졌어요.", "ex_en": "These days, more and more people dislike artificial intelligence."}, {"name": "-ㄹ 수 있어요", "level": "Starter", "exp": "Expression meaning ''can/is able to'' indicating possibility or capability", "ex_ko": "AI가 사람의 일자리를 빼앗을 수 있어요.", "ex_en": "AI can take away people''s jobs."}, {"name": "-아/어서예요 (giving a reason)", "level": "Beginner", "exp": "Gives the reason for something just mentioned: ''it''s because ...''. 있다 → 있어서예요.", "ex_ko": "사람의 일자리를 빼앗을 수 있어서예요.", "ex_en": "It''s because it can take away people''s jobs."}]}', updated_at = now() where article_id = 'mo7tpkb6fqr5' and md5(grammar) = 'd0e5698f6b0d7b50e6e23885c7067bab';
update public.article_cache set grammar = '{"patterns": [{"name": "-면서", "level": "Intermediate", "exp": "Used to express two actions happening simultaneously or in parallel", "ex_ko": "피부를 매끄럽게 만들어 주면서 동시에 강력한 자외선 차단 효과를 제공해요.", "ex_en": "While making skin smooth, it provides strong UV blocking effects at the same time."}, {"name": "N일수록", "level": "Intermediate", "exp": "''The more (something is) N, the more ...''. 이다 → 일수록: 나이가 든 피부일수록 ''the older the skin''.", "ex_ko": "나이가 든 피부일수록 선크림 사용이 중요하다고 말합니다.", "ex_en": "Experts say that the older the skin, the more important it is to use sunscreen."}, {"name": "-ㄹ 수 있어요", "level": "Intermediate", "exp": "Used to express possibility or ability to do something", "ex_ko": "매일 꾸준히 사용하면 주름과 나이 반점을 예방할 수 있어요.", "ex_en": "If you use it consistently every day, you can prevent wrinkles and age spots."}]}', updated_at = now() where article_id = 'mo7tq3w71sjz' and md5(grammar) = '53f08ade164f22935edba71907a6dad8';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 (and)", "level": "Beginner", "exp": "Joins two descriptions or actions: ''and''. 빠르다 → 빠르고 안정적이에요 ''fast and stable''.", "ex_ko": "속도가 매우 빠르고 안정적이에요.", "ex_en": "The speed is very fast and stable."}, {"name": "-았/었어요 (past polite)", "level": "Beginner", "exp": "Polite past-tense ending for something that already happened. 선정하다 → 선정했어요 ''selected''.", "ex_ko": "미국의 기술 전문 회사 CNET에서 2026년 최고의 광섬유 인터넷 회사들을 선정했어요.", "ex_en": "The US tech company CNET picked the best fiber internet companies of 2026."}, {"name": "-고 있어요 (Present progressive)", "level": "Beginner", "exp": "Indicates an ongoing action or current state", "ex_ko": "많은 사람들이 광섬유 인터넷을 선택하고 있어요.", "ex_en": "Many people are choosing fiber internet."}]}', updated_at = now() where article_id = 'mo7tqmqeimvc' and md5(grammar) = '7814a2741e8dadd217832e3a417a536d';
update public.article_cache set grammar = '{"patterns": [{"name": "N이에요/예요", "level": "Beginner", "exp": "Polite ''to be'' ending after a noun: 이에요 after a consonant, 예요 after a vowel. 앤트로픽이에요 = ''is Anthropic''.", "ex_ko": "미국에 있는 회사 이름은 앤트로픽이<strong>에요</strong>.", "ex_en": "The name of the company in America is Anthropic."}, {"name": "-겠다고 하다", "level": "Beginner", "exp": "Reports someone''s promise or plan: -겠다 (''will'') + -고 하다 (''said''). 쓰다 → 쓰겠다고 했어요 ''said (they) would use''.", "ex_ko": "아마존의 컴퓨터를 많이 쓰<strong>겠다고 했어요</strong>.", "ex_en": "(They) said they would use a lot of Amazon''s computers."}, {"name": "N(이)나 되다", "level": "Beginner", "exp": "Stresses that an amount is surprisingly large: ''as much as N''. 5조원이나 돼요 = ''is as much as 5 trillion won''.", "ex_ko": "그 돈은 5조원<strong>이나</strong> 돼요.", "ex_en": "That money is as much as 5 trillion won."}, {"name": "-게 되다", "level": "Intermediate", "exp": "Shows a situation that came about: ''come to, end up''. 일하다 → 일하게 됐어요 ''came to work (together)''.", "ex_ko": "두 회사가 함께 일하<strong>게 됐어요</strong>.", "ex_en": "The two companies ended up working together."}]}', updated_at = now() where article_id = 'mo7trf618ddd' and md5(grammar) = '5e346efd40df4de9524985d4a17aaeb9';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)로 화제가 되다", "level": "Beginner", "exp": "to become a topic of discussion; to be talked about for (a reason)", "ex_ko": "그녀는 아름다운 헤어스타일로 화제가 되고 있어요.", "ex_en": "She is becoming a topic of discussion for her beautiful hairstyle."}, {"name": "-아/어 보이다", "level": "Beginner", "exp": "''Look ..., seem ...'' based on appearance. 있다 → 있어 보여요; 아름답다 → 아름다워 보여요.", "ex_ko": "이 헤어스타일은 매우 세련되고 품격이 있어 보여요.", "ex_en": "This hairstyle looks very refined and classy."}, {"name": "N처럼 (like N)", "level": "Beginner", "exp": "Compares to something: ''like N''. 하이엑처럼 멋지게 = ''stylishly, like Hayek''.", "ex_ko": "하이엑처럼 멋지게 연출하면 더욱 아름다워 보여요.", "ex_en": "If you style it stylishly like Hayek, it looks even more beautiful."}]}', updated_at = now() where article_id = 'mo7trzb2paz6' and md5(grammar) = '39e3c58f30c719f7839b4b98c72323d1';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Intermediate", "exp": "Describes something happening now or continuing: ''be -ing''. 보이다 → 보이고 있어요 ''is showing''.", "ex_ko": "화산이 활발한 활동을 보이고 있어요.", "ex_en": "The volcano is very active."}, {"name": "-기도 하다", "level": "Intermediate", "exp": "Means ''also'' or ''at the same time''; indicates multiple aspects or properties", "ex_ko": "많은 관광객들이 찾는 명소이기도 합니다.", "ex_en": "It is also a tourist destination that many visitors seek."}, {"name": "-지만", "level": "Intermediate", "exp": "Indicates contrast between two clauses; means ''but'' or ''although''", "ex_ko": "화산 활동은 위험하지만 동시에 아름다운 자연 현상이기도 해요.", "ex_en": "Volcanic activity is dangerous, but at the same time it is also a beautiful natural phenomenon."}]}', updated_at = now() where article_id = 'mo7tskmym5aw' and md5(grammar) = 'f720447c3a85583e0491f07d7c879e37';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어요 (present tense declarative)", "level": "Starter", "exp": "Expresses present tense facts or states in polite, conversational Korean", "ex_ko": "세상에는 재미있는 숫자 법칙이 있어요.", "ex_en": "There are interesting number laws in the world."}, {"name": "-는 것 (thing that ...)", "level": "Starter", "exp": "Turns a verb phrase into a noun: ''thing(s) that ...''. 시작하다 → 시작하는 것 ''things that start''.", "ex_ko": "1로 시작하는 것이 많아요.", "ex_en": "Many things start with 1."}, {"name": "-ㄹ 때 (when/at the time of)", "level": "Starter", "exp": "Indicates a time or situation when something happens", "ex_ko": "가짜 숫자를 찾을 때 도움이 돼요.", "ex_en": "It helps when finding fake numbers."}]}', updated_at = now() where article_id = 'mo7tte2sq1zd' and md5(grammar) = 'c95e7bd00047462807368c21c482499b';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어요 (Present tense declarative)", "level": "Beginner", "exp": "Used to make present tense statements in polite/informal speech", "ex_ko": "뉴욕타임스에서 매일 퍼즐 게임을 내요.", "ex_en": "The New York Times releases puzzle games every day."}, {"name": "-는 + noun (describing a noun)", "level": "Beginner", "exp": "Describes a noun with an action: 찾다 → 답을 찾는 사람들 ''people who look up the answers''.", "ex_ko": "어려워서 답을 찾는 사람들이 많아요.", "ex_en": "It is hard, so many people look up the answers."}, {"name": "-아/어서 (sequence)", "level": "Beginner", "exp": "Links two steps where the first sets up the second: ''do A and then B''. 묶다 → 묶어서 ''group (them) and then''.", "ex_ko": "16개의 단어를 4개씩 묶어서 같은 그룹을 찾는 게임이에요.", "ex_en": "It''s a game where you group 16 words into sets of 4 and find the matching groups."}]}', updated_at = now() where article_id = 'mo7ttwrqj9k3' and md5(grammar) = '9b2e149d8d3f819a000d89190b49f9ce';
update public.article_cache set grammar = '{"patterns": [{"name": "~예요/이에요 (Present tense copula)", "level": "Beginner", "exp": "Used to describe or identify someone/something in present tense. ~예요 is used after vowels, ~이에요 after consonants.", "ex_ko": "제이 성씨는 미국에 사는 아버지예요.", "ex_en": "Mr. Jay Sung is a father living in America."}, {"name": "-기 위해(서)", "level": "Beginner", "exp": "Expresses purpose: ''in order to''. Attach -기 위해 to the verb stem: 찾다 → 찾기 위해 ''in order to find''.", "ex_ko": "제이 성씨는 아들을 찾기 위해 노력하고 있어요.", "ex_en": "Jay Sung is working hard to find his son."}, {"name": "~기를 원하다 (Desire/wish expression)", "level": "Beginner", "exp": "Expresses wanting or wishing for something. ~기를 원하다 means ''to want/wish for [verb action]''.", "ex_ko": "그는 이 문제를 많은 사람들이 기억하기를 원한다고 말했어요.", "ex_en": "He said he wants many people to remember this problem."}]}', updated_at = now() where article_id = 'mo7tuj107typ' and md5(grammar) = '68061c7528669b85aff6e52e31dbf5ac';
update public.article_cache set grammar = '{"patterns": [{"name": "~기 때문에", "level": "Starter", "exp": "because; due to the fact that", "ex_ko": "한국의 장관이 핵 시설에 대해 말했기 때문에", "ex_en": "Because a Korean minister spoke about nuclear facilities"}, {"name": "-고 있었어요 (was -ing)", "level": "Starter", "exp": "Past progressive: an action that was going on in the past. 나누다 → 나누고 있었어요 ''was sharing''.", "ex_ko": "미국은 한국과 여러 정보를 함께 나누고 있었어요", "ex_en": "The US was sharing various information with Korea."}, {"name": "~ㄹ 거예요 (future tense)", "level": "Starter", "exp": "will; going to (future intention or prediction)", "ex_ko": "두 나라는 계속 친구로 지낼 거예요", "ex_en": "The two countries will continue to be friends"}]}', updated_at = now() where article_id = 'mo99691skc2e' and md5(grammar) = '9cea8ea08cea8796f4ffbc309934f5d9';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 것이라고 전망하다", "level": "Intermediate", "exp": "Reports a forecast: -(으)ㄹ 것이다 (''will'') + -라고 + 전망하다 (''predict''). 끌다 → 끌 것이라고 전망했어요.", "ex_ko": "자연스러운 메이크업이 앞으로도 계속 인기를 끌 것이라고 전망했어요.", "ex_en": "(Beauty experts) predicted that natural makeup will stay popular."}]}', updated_at = now() where article_id = 'mo996sf5xrh5' and md5(grammar) = 'ca9796871d3772ef1bdbed9e5c097454';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses ability or possibility: ''can''. 사다 → 살 수 있어요 ''can buy''.", "ex_ko": "스페이스X는 커서 회사를 살 수 있어요.", "ex_en": "SpaceX can buy the company Cursor."}, {"name": "-는 + noun (describing a noun)", "level": "Beginner", "exp": "Describes a noun with an action: 만들다 → 만드는 회사 ''a company that makes''.", "ex_ko": "커서는 컴퓨터 프로그램을 만드는 회사예요.", "ex_en": "Cursor is a company that makes computer programs."}, {"name": "-아/어서 (by doing)", "level": "Beginner", "exp": "Shows the means used for the next action: ''by (using) ...''. 사용하다 → 사용해서 ''by using''.", "ex_ko": "인공지능 기술을 사용해서 프로그래머들을 도와주는 도구를 만들어요.", "ex_en": "They use AI technology to make tools that help programmers."}]}', updated_at = now() where article_id = 'mo997g4atuzs' and md5(grammar) = 'c2df4b501ff405ea64a529cafaa1250d';
update public.article_cache set grammar = '{"patterns": [{"name": "-기로 하다", "level": "Starter", "exp": "Expresses a decision or agreement to do something: ''decide to''. 주다 → 주기로 했어요 ''decided to give''.", "ex_ko": "미국이 한국에게 북한 정보를 덜 주기로 했어요.", "ex_en": "The US decided to give Korea less information about North Korea."}, {"name": "-다고 말했어요", "level": "Starter", "exp": "reports what someone said; indirect speech", "ex_ko": "IAEA가 북한을 걱정한다고 말했어요.", "ex_en": "The IAEA said that it worries about North Korea."}, {"name": "N 만에", "level": "Starter", "exp": "''After (a period of) N'': stresses how soon something happened. 6일 만에 = ''just six days later''.", "ex_ko": "그 후 6일 만에 이런 일이 일어났어요.", "ex_en": "Just six days after that, this happened."}]}', updated_at = now() where article_id = 'mo9urgjr4msf' and md5(grammar) = '5c030d1bac310555a78a4092e91dd002';
update public.article_cache set grammar = '{"patterns": [{"name": "N이/가 아니라고 (reported denial)", "level": "intermediate", "exp": "Reports a denial: N이/가 아니다 ''is not N'' + -라고 + 밝히다 ''state''. 사실이 아니라고 밝혔습니다 = ''stated that it is not true''.", "ex_ko": "관련 보도가 사실이 아니라고 밝혔습니다", "ex_en": "(The company) stated that the related reports are not true."}, {"name": "V + -고 있어요", "level": "intermediate", "exp": "Present progressive tense indicating an ongoing action or current state", "ex_ko": "백현은 아이돌 그룹 엑소의 멤버로 활동하고 있어요", "ex_en": "Baek Hyun is currently active as a member of the idol group EXO"}]}', updated_at = now() where article_id = 'mo9us3ji6smb' and md5(grammar) = 'c79406cca31905ea28f81d1d87bc8545';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있어요 (present progressive)", "level": "Beginner", "exp": "Indicates an action that is currently in progress or a state that is continuing", "ex_ko": "새로운 브랜드들이 인기를 얻고 있어요.", "ex_en": "New brands are gaining popularity."}, {"name": "-아/어지다 (became)", "level": "Beginner", "exp": "Shows a change of state: ''become ...''. 유명하다 → 유명해지다; past: 유명해졌어요 ''became famous''.", "ex_ko": "두 브랜드가 특히 유명해졌어요.", "ex_en": "Two brands have become especially famous."}, {"name": "-(으)ㄹ 것으로 보이다", "level": "Beginner", "exp": "Makes a prediction based on signs: ''look likely to ...''. 성장하다 → 성장할 것으로 보여요.", "ex_ko": "이런 브랜드들이 앞으로 더 성장할 것으로 보여요.", "ex_en": "These brands look likely to grow even more in the future."}]}', updated_at = now() where article_id = 'mo9usvhww7m7' and md5(grammar) = '67ccbfbc46bcdc6db44bd07ad38d3df7';
update public.article_cache set grammar = '{"patterns": [{"name": "~다고 해요 (Reported Speech/Hearsay)", "level": "Beginner", "exp": "Used to report what someone said or what is being said, indicating information from an external source.", "ex_ko": "F1 레이싱 선수도 관련되어 있다고 해요.", "ex_en": "They say that an F1 racing driver is also involved."}, {"name": "~고 있어요 (Progressive Action)", "level": "Beginner", "exp": "Used to express an ongoing or continuous action in the present.", "ex_ko": "경찰은 이런 불법 업소들을 계속 수사하고 있어요.", "ex_en": "The police are continuously investigating these illegal businesses."}]}', updated_at = now() where article_id = 'mo9uypj8l0uf' and md5(grammar) = 'ff653c44a2d9716f5e68a8e00b00e576';
update public.article_cache set grammar = '{"patterns": [{"name": "V-ㄹ 수 없다 / 수 없도록", "level": "Intermediate", "exp": "Used to express inability or impossibility; literally ''cannot do'' or ''made unable to do''", "ex_ko": "현재 17세 이하 청소년들이 평생 담배를 살 수 없도록 하는 내용입니다.", "ex_en": "The content makes it so that youth currently 17 years old and under cannot buy cigarettes for their entire lives."}, {"name": "N인 + noun", "level": "Intermediate", "exp": "Uses a noun to describe another noun: 이다 → 인. 지금 15세인 사람 = ''a person who is 15 now''.", "ex_ko": "지금 15세인 사람은 30세가 되어도 담배를 살 수 없게 돼요.", "ex_en": "A person who is 15 now will not be able to buy cigarettes even at age 30."}, {"name": "V-(으)ㄹ 것으로 예상되다", "level": "Intermediate", "exp": "Used to express expectation or prediction about future events or outcomes", "ex_ko": "이런 해외 사례가 한국의 금연 정책에도 영향을 줄 수 있을 것으로 예상돼요.", "ex_en": "It is expected that such overseas cases could also influence Korea''s anti-smoking policies."}]}', updated_at = now() where article_id = 'moa03be973tk' and md5(grammar) = 'ccbf43b35f7121757770fdcddf5c0c10';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄴ 결과", "level": "Intermediate", "exp": "''As a result of doing ...'': 조사하다 → 조사한 결과 ''as a result of investigating''.", "ex_ko": "경찰이 용의자를 조사한 결과, 놀라운 사실이 밝혀졌어요.", "ex_en": "When the police investigated the suspect, a surprising fact came to light."}, {"name": "-는 + noun (describing a noun)", "level": "Intermediate", "exp": "Describes a noun with an action: 총을 쏘다 → 총을 쏘는 사건 ''an incident in which (someone) shoots''.", "ex_ko": "한 남성이 관광객들을 향해 총을 쏘는 사건이 발생했습니다.", "ex_en": "An incident occurred in which a man shot at tourists."}]}', updated_at = now() where article_id = 'moa041sf8nz6' and md5(grammar) = 'fd8a47a5b4141e22c4a60eea845f43ae';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어서 (reason)", "level": "Beginner", "exp": "Connects a reason to its result: ''because ..., so ...''. 아프다 → 아파서 ''because (it) is sick''.", "ex_ko": "강아지는 몸이 아파서 잘 움직이지 못해요.", "ex_en": "Because the dog is sick, it cannot move well."}, {"name": "하지만 (but)", "level": "Beginner", "exp": "Starts a sentence that contrasts with the previous one: ''but, however''.", "ex_ko": "강아지는 몸이 아파서 잘 움직이지 못해요. 하지만 주인이 집에 오면 기뻐해요.", "ex_en": "The dog is sick and cannot move well. But when its owner comes home, it is happy."}, {"name": "명사 + 이/가 되다 (become)", "level": "Beginner", "exp": "Indicates that something becomes or transforms into a certain state or role.", "ex_ko": "강아지나 고양이는 가족의 일부가 되어요.", "ex_en": "Dogs and cats become a part of the family."}]}', updated_at = now() where article_id = 'moa4mp15nfbr' and md5(grammar) = 'f0f3404ea1ca69a54ea9034dbcab3cfc';
update public.article_cache set grammar = '{"patterns": [{"name": "-다가", "level": "Beginner", "exp": "Shows that one action or state was interrupted by another: ''was ... and then (suddenly)''. 있다 → 있다가.", "ex_ko": "악어는 물 위에 있다가 갑자기 모습을 감췄어요.", "ex_en": "The crocodile was on the surface of the water, then suddenly vanished from sight."}, {"name": "-았/었던 것처럼 (as if)", "level": "Beginner", "exp": "''As if ...'': compares to an imagined situation. 없었다 → 없었던 것처럼 ''as if it had never been there''.", "ex_ko": "처음부터 그곳에 없었던 것처럼 완전히 사라졌어요.", "ex_en": "It disappeared completely, as if it had never been there in the first place."}]}', updated_at = now() where article_id = 'moa4n9y5hv1r' and md5(grammar) = '3ad7d4b695607c0814312090c0f734d4';
update public.article_cache set grammar = '{"patterns": [{"name": "-는데 (background)", "level": "Intermediate", "exp": "Sets up the background for what happens next: ''was ... when''. 일하고 있었다 → 일하고 있었는데.", "ex_ko": "문지기는 평소와 다름없이 일하고 있었는데", "ex_en": "The doorman was working as usual when ..."}, {"name": "~ㄹ 수 있다 (을 수 있다)", "level": "Intermediate", "exp": "Expresses possibility or ability to do something.", "ex_ko": "여성의 목숨을 구할 수 있었습니다", "ex_en": "He was able to save the woman''s life"}, {"name": "~다고 말하다 (다고 말하다)", "level": "Intermediate", "exp": "Used to report what someone said or expressed as speech.", "ex_ko": "전문가들은 이런 상황에서 주변 사람들의 역할이 매우 중요하다고 말해요", "ex_en": "Experts say that the role of people around is very important in such situations"}]}', updated_at = now() where article_id = 'moa5jqojn9jx' and md5(grammar) = '5723606ea01c4dee47a8e58242afaa2c';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Intermediate", "exp": "''As'': shows one change going along with another. 나이가 들다 → 나이가 들면서 ''as (it) gets older''.", "ex_ko": "나이가 들면서 활동량이 줄어들어요.", "ex_en": "As the dog gets older, it becomes less active."}, {"name": "-는 순간", "level": "Intermediate", "exp": "''The moment ...'': the next thing happens right then. 보다 → 보는 순간 ''the moment (it) sees''.", "ex_ko": "주인을 보는 순간 꼬리를 흔들며 신나하는 모습을 보여줍니다.", "ex_en": "The moment it sees its owner, it wags its tail and gets excited."}]}', updated_at = now() where article_id = 'moa5kev6xj1p' and md5(grammar) = 'ce9bd7edfcc95e6c9a72fdd4dd334344';
update public.article_cache set grammar = '{"patterns": [{"name": "-았/었던 것처럼 (as if)", "level": "Intermediate", "exp": "''As if ...'': compares to an imagined situation. 없었다 → 없었던 것처럼 ''as if it had never been there''.", "ex_ko": "마치 처음부터 없었던 것처럼 보였거든요.", "ex_en": "It looked as if it had never been there in the first place."}, {"name": "-기는 쉽지 않다", "level": "Intermediate", "exp": "Says something is hard to do: ''it is not easy to ...''. 보다 → 보기는 쉽지 않아요.", "ex_ko": "이렇게 완벽하게 숨는 모습을 직접 보기는 쉽지 않아요.", "ex_en": "It is not easy to see it hide this perfectly with your own eyes."}, {"name": "-거나", "level": "Beginner", "exp": "Lists alternatives between actions: ''or''. 피하다 → 피하거나 ''avoid ... or''.", "ex_ko": "악어가 천적을 피하거나 사냥을 위해 이런 행동을 한다고 설명해요.", "ex_en": "(Experts) explain that crocodiles do this to avoid predators or to hunt."}]}', updated_at = now() where article_id = 'moa5l1dwqx4r' and md5(grammar) = '34b2dc3397ac63acc29b02cb0624e372';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어서 (cause/sequence)", "level": "Intermediate", "exp": "Links an action to its result: ''and so''. 움직이다 → 움직여서 ''(it) moves, and so''.", "ex_ko": "잘린 꼬리는 몇 분간 계속 움직여서 포식자의 시선을 끌어요.", "ex_en": "The cut-off tail keeps moving for a few minutes, drawing the predator''s attention."}, {"name": "N(이)라고 불리다", "level": "Intermediate", "exp": "''Be called N''. ''자절''이라고 불립니다 = ''is called autotomy''.", "ex_ko": "도마뱀의 꼬리 자르기는 ''자절(自切)''이라고 불립니다.", "ex_en": "A lizard cutting off its tail is called ''autotomy''."}, {"name": "-자 (as soon as)", "level": "Intermediate", "exp": "''As soon as, when'': the second action follows right after the first. 받다 → 공격을 받자 ''as soon as it was attacked''.", "ex_ko": "한 도마뱀이 고양이의 공격을 받자 꼬리를 자르고 도망쳤습니다.", "ex_en": "As soon as a lizard was attacked by a cat, it cut off its tail and ran away."}]}', updated_at = now() where article_id = 'moajy1yr7opu' and md5(grammar) = '1febc2f4509bfddf7a1eebf249fc3ed5';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Intermediate", "exp": "Shows two actions done at the same time: ''while''. 일하다 → 일하면서 ''while working''.", "ex_ko": "청소부로 일하면서 공부해서 의대생이 된", "ex_en": "became a medical student by studying while working as a cleaner"}, {"name": "-는 데 성공하다", "level": "Intermediate", "exp": "''Succeed in doing ...'': 입학하다 → 입학하는 데 성공했습니다 ''succeeded in getting into''.", "ex_ko": "의대에 입학하는 데 성공했습니다", "ex_en": "(He) succeeded in getting into medical school."}]}', updated_at = now() where article_id = 'moajynpvwjp3' and md5(grammar) = 'a89538ce8a30fad71a351803aba69892';
update public.article_cache set grammar = '{"patterns": [{"name": "N와/과 함께", "level": "Intermediate", "exp": "''Together with N'': 학생과 함께 = ''together with the student''. 와 follows a vowel, 과 a consonant.", "ex_ko": "시각 장애인 학생과 함께 모든 수업에 참석한 안내견", "ex_en": "a guide dog that attended every class together with a visually impaired student"}, {"name": "-(으)ㄹ 때까지", "level": "Intermediate", "exp": "''Until ...'': something continues up to that point. 졸업하다 → 졸업할 때까지 ''until (the owner) graduated''.", "ex_ko": "주인이 졸업할 때까지 한 번도 빠지지 않고 참석했습니다.", "ex_en": "It attended without missing a single day until its owner graduated."}, {"name": "-다며 (saying that)", "level": "Intermediate", "exp": "Short for -다고 하며: quotes what someone says while they do the next action. ''...공부했다''며 수여했어요 = ''awarded ..., saying (it) studied ...''.", "ex_ko": "대학교 측은 ''이 개도 학생만큼 열심히 공부했다''며 특별 졸업장을 수여했어요.", "ex_en": "Saying ''this dog studied as hard as the student,'' the university awarded it a special diploma."}]}', updated_at = now() where article_id = 'moajzaek4vfz' and md5(grammar) = '80fd88ae539f008c2d2028adaa6d0aaf';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄴ/는답니다", "level": "Intermediate", "exp": "A friendly ending that passes on information, like ''you know''. 보여주다 → 보여준답니다.", "ex_ko": "하지만 실제로는 다른 모습을 보여준답니다.", "ex_en": "But in reality, they show a different side."}, {"name": "동사 + -기도 해요", "level": "Intermediate", "exp": "This pattern indicates that an action sometimes occurs or that something also happens among other things.", "ex_ko": "거북이들은 영역을 지키기 위해 싸우기도 해요.", "ex_en": "Turtles sometimes fight to protect their territory."}, {"name": "-(으)ㄹ 때", "level": "Intermediate", "exp": "Means ''when, at the time of (doing)''. 경쟁하다 → 경쟁할 때 ''when competing''.", "ex_ko": "특히 먹이를 놓고 경쟁할 때 더 활발해져요.", "ex_en": "They become more active especially when competing for food."}]}', updated_at = now() where article_id = 'moajzw3h0h6k' and md5(grammar) = '9d6b6e408ba49302a950ec83b5bd57bc';
update public.article_cache set grammar = '{"patterns": [{"name": "-지 않고(도)", "level": "Beginner", "exp": "''Without doing ...'': 타다 → 타지 않고도 ''even without (people) on board''.", "ex_ko": "사람이 타지 않고도 데이터를 모을 수 있어요.", "ex_en": "It can collect data even without people on board."}, {"name": "N(으)로 (by means of)", "level": "Beginner", "exp": "Marks the means or tool: ''by, with''. 바람과 태양의 힘으로 = ''with the power of wind and sun''.", "ex_ko": "이 배는 바람과 태양의 힘으로 움직여요.", "ex_en": "This boat runs on wind and solar power."}, {"name": "~는 데 도움이 돼요 (helps with/is helpful for)", "level": "Beginner", "exp": "Indicates that something is useful or helpful for a particular purpose or situation.", "ex_ko": "이 기술은 바다 환경을 보호하는 데 도움이 돼요.", "ex_en": "This technology helps protect the ocean environment."}]}', updated_at = now() where article_id = 'moamhg2arz55' and md5(grammar) = '85babe5c66e8909e00695662c3fe2d74';
update public.article_cache set grammar = '{"patterns": [{"name": "N(으)로 만들어지다", "level": "Beginner", "exp": "''Be made of N'': (으)로 marks the material and 만들어지다 is the passive of 만들다. 나무로 만들어졌어요 = ''was made of wood''.", "ex_ko": "이 사원은 모두 나무로 만들어졌어요.", "ex_en": "This temple was made entirely of wood."}]}', updated_at = now() where article_id = 'moami07bdua4' and md5(grammar) = 'e704b7a4023536e45cd8caa0b2adef9d';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 수 있다", "level": "Beginner", "exp": "Expresses ability or possibility: ''can''. 받다 → 받을 수 있어요 ''can receive''.", "ex_ko": "쉼터에서는 잠자리와 식사를 제공해요. 또한 상담과 취업 도움도 받을 수 있어요.", "ex_en": "The shelters provide a place to sleep and meals. You can also get counseling and help finding a job."}, {"name": "-고 있다", "level": "Beginner", "exp": "Describes an ongoing action: ''be -ing''. 운영하다 → 운영하고 있어요 ''is running''.", "ex_ko": "서울시는 노숙자들을 위해 여러 쉼터를 운영하고 있어요.", "ex_en": "Seoul City is running several shelters for homeless people."}, {"name": "-아/어 있다 (resulting state)", "level": "Beginner", "exp": "Describes a state that remains after an action is done. 정돈되다 → 정돈되어 있어요 ''is (kept) tidy''.", "ex_ko": "쉼터 내부는 깨끗하고 정돈되어 있어요.", "ex_en": "Inside, the shelter is clean and tidy."}]}', updated_at = now() where article_id = 'moao9hr9j40u' and md5(grammar) = '0b794e44b02c6b37e97d62aa788d3e7c';
update public.article_cache set grammar = '{"patterns": [{"name": "-고 있다", "level": "Intermediate", "exp": "Describes something happening now or continuing: ''be -ing''. 화제가 되다 → 화제가 되고 있어요 ''is becoming a hot topic''.", "ex_ko": "한 마리 쥐가 보여준 놀라운 용기가 화제가 되고 있어요.", "ex_en": "The amazing courage shown by a mouse is becoming a hot topic."}, {"name": "-았/었을 것이다", "level": "Intermediate", "exp": "Makes a guess about the past: ''probably did ...''. 하다 → 했을 것이라고 말해요 ''say (it) probably tried''.", "ex_ko": "전문가들은 쥐가 먹이를 찾거나 영역을 지키려 했을 것이라고 말해요.", "ex_en": "Experts say the mouse probably tried to find food or protect its territory."}, {"name": "-(으)ㄴ + noun (past modifier)", "level": "Intermediate", "exp": "Describes a noun with a completed action: 보여주다 → 보여준 용기 ''the courage (it) showed''.", "ex_ko": "한 마리 쥐가 보여준 놀라운 용기가 화제가 되고 있어요.", "ex_en": "The amazing courage shown by a mouse is becoming a hot topic."}]}', updated_at = now() where article_id = 'moatdtv9ut24' and md5(grammar) = '334003b375a2e926cb2edac479102766';
update public.article_cache set grammar = '{"patterns": [{"name": "동사/형용사 + -고 (and, while)", "level": "Intermediate", "exp": "Connects two actions or states, indicating sequential or simultaneous actions", "ex_ko": "꼬리를 버리고 도망쳤어요", "ex_en": "discarded its tail and fled"}, {"name": "동사 + -아/어도 (even if, even though)", "level": "Intermediate", "exp": "Expresses a contrast or concession despite an action or condition occurring", "ex_ko": "꼬리가 떨어져도 계속 움직여서", "ex_en": "Even though the tail falls off, it continues to move"}]}', updated_at = now() where article_id = 'moateigoskwq' and md5(grammar) = '48aba646a04e01eeabadd72c649dd0b9';
update public.article_cache set grammar = '{"patterns": [{"name": "-는 모습", "level": "Intermediate", "exp": "''The sight of (someone) doing ...'', common in news about viral videos. 인쇄하다 → 인쇄하는 모습.", "ex_ko": "오래된 프린터를 사용해서 종이에 ''생일 축하합니다''라는 글자를 인쇄하는 모습이 온라인에서 큰 관심을 받고 있어요.", "ex_en": "The sight of a man printing ''Happy Birthday'' on paper with an old printer is getting a lot of attention online."}, {"name": "-게 되다", "level": "Intermediate", "exp": "Shows a change that comes about through circumstances: ''come to ...''. 깨닫다 → 깨닫게 되다 ''come to realize''.", "ex_ko": "디지털 시대에도 손으로 직접 만드는 것의 소중함을 다시 깨닫게 되는 사례라고 말했습니다.", "ex_en": "(Experts) said it is a case that makes people realize again, even in the digital age, how precious handmade things are."}]}', updated_at = now() where article_id = 'mob0bcnv87ms' and md5(grammar) = '82b8eb33417c1d2b03c31b98b88516ff';
update public.article_cache set grammar = '{"patterns": [{"name": "V-기 위해(서)", "level": "Intermediate", "exp": "Expresses purpose or intention: ''in order to'' or ''for the purpose of''", "ex_ko": "과학자들은 우주의 크기를 측정하기 위해 많은 연구를 하고 있어요.", "ex_en": "Scientists are conducting a lot of research in order to measure the size of the universe."}, {"name": "A/V-(으)ㄹ 정도", "level": "Intermediate", "exp": "Indicates degree or extent: ''to such a degree that'' or ''enough to''", "ex_ko": "빛의 속도로도 몇 년이 걸릴 정도예요.", "ex_en": "It takes several years even at the speed of light."}, {"name": "-고 있다", "level": "Intermediate", "exp": "Describes something that is continuing now: ''be -ing''. Here it ends with the friendly -답니다: 커지다 → 커지고 있답니다.", "ex_ko": "우주는 지금도 계속 커지고 있답니다.", "ex_en": "The universe is still getting bigger, even now."}]}', updated_at = now() where article_id = 'mob0bzqrsnvj' and md5(grammar) = 'fdce7f30ecd436a49f3818e9c7e07cae';
update public.article_cache set grammar = '{"patterns": [{"name": "~(으)ㄹ 수 있다", "level": "Intermediate", "exp": "Expression meaning ''can/be able to'' or ''it is possible to'' do something", "ex_ko": "외부 충격에 잘 견딜 수 있습니다.", "ex_en": "It can withstand external impact well."}, {"name": "~다고 말했어요/발표했습니다", "level": "Intermediate", "exp": "Indirect speech pattern used to report what someone said or announced", "ex_ko": "더 가볍고 강한 재료를 만들 수 있다고 말했어요.", "ex_en": "They said that lighter and stronger materials can be made."}]}', updated_at = now() where article_id = 'mob5ba3hcuu2' and md5(grammar) = '088768054b58751ee6ae8c1e440ba258';
update public.article_cache set grammar = '{"patterns": [{"name": "-다가", "level": "Intermediate", "exp": "Shows that something happened in the middle of an action: ''while doing ...''. 먹다 → 먹다가 ''while eating''.", "ex_ko": "한 외국인이 브로콜리를 먹다가 특별한 경험을 했어요.", "ex_en": "A foreigner had an unusual experience while eating broccoli."}, {"name": "-기 쉽다", "level": "Intermediate", "exp": "Says something is easy to do or likely to happen: ''easy to ...''. 숨다 → 숨기 쉬운 채소 ''a vegetable that bugs can easily hide in''.", "ex_ko": "브로콜리는 꽃 모양이 복잡해서 벌레가 숨기 쉬운 채소예요.", "ex_en": "Broccoli has a complex flower shape, so it is a vegetable where bugs can easily hide."}]}', updated_at = now() where article_id = 'mocf2fscygph' and md5(grammar) = '2415a3781f2c5ea70c5d514dfe44f361';
update public.article_cache set grammar = '{"patterns": [{"name": "N이/가 되다", "level": "Intermediate", "exp": "''To become N'': the noun takes 이/가 and is followed by 되다. 플랫폼이 되었습니다 = ''has become a platform''.", "ex_ko": "유튜브는 이제 전 세계에서 가장 큰 동영상 플랫폼이 되었습니다.", "ex_en": "YouTube has now become the largest video platform in the world."}, {"name": "-되다 (passive)", "level": "Intermediate", "exp": "Many 하다 verbs become passive by swapping 하다 for 되다: 업로드하다 ''upload'' → 업로드되다 ''be uploaded''.", "ex_ko": "이 영상은 2005년 4월 23일에 처음 업로드되었어요.", "ex_en": "This video was first uploaded on April 23, 2005."}, {"name": "~을/를 통해 (Through/Via)", "level": "Intermediate", "exp": "Indicates the means or method through which an action is performed", "ex_ko": "한국에서도 많은 사람들이 유튜브를 통해 콘텐츠를 만들고 시청하고 있어요.", "ex_en": "Many people in Korea are also creating and watching content through YouTube."}]}', updated_at = now() where article_id = 'mocf3156w1ma' and md5(grammar) = 'dcc0839b52f0d28b66a4ce17693e7a45';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄹ 것으로 추정되다", "level": "Intermediate", "exp": "A formal way to give a likely explanation or estimate: ''it is presumed that ...''. 때문이다 → 때문일 것으로 추정돼요.", "ex_ko": "이런 현상이 나타나는 이유는 바다나 강의 환경 변화 때문일 것으로 추정돼요.", "ex_en": "This is presumed to be because of environmental changes in the sea or rivers."}, {"name": "-다고 해요 (hearsay)", "level": "Intermediate", "exp": "Passes on information heard from someone else: ''they say ...''. 보였다 → 보였다고 해요.", "ex_ko": "또한 평소보다 12km 더 멀리 이동하는 모습도 보였다고 해요.", "ex_en": "They were also reportedly seen traveling 12 km farther than usual."}]}', updated_at = now() where article_id = 'mocf3l034hvc' and md5(grammar) = '7251bcde5e5433585f69fc08f68689c2';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어서 (sequence)", "level": "Intermediate", "exp": "Links two actions where the first leads into the second: 올라타다 → 올라타서 ''climbed on and then''.", "ex_ko": "작은 게 한 마리가 해파리 위에 올라타서 함께 헤엄치고 있었습니다.", "ex_en": "A small crab climbed on top of a jellyfish and was swimming along with it."}, {"name": "-는 모습 (the sight/appearance of)", "level": "Intermediate", "exp": "Describes the appearance or scene of an action or state being observed", "ex_ko": "게가 해파리를 교통수단처럼 이용하는 모습이었거든요.", "ex_en": "It was the sight of a crab using a jellyfish like a means of transportation."}, {"name": "-다고 (하)다 (it is said that/according to)", "level": "Intermediate", "exp": "Reports what someone said or explains information indirectly", "ex_ko": "전문가들은 이런 현상이 자연에서 가끔 일어난다고 설명했어요.", "ex_en": "Experts explained that this phenomenon happens occasionally in nature."}]}', updated_at = now() where article_id = 'mocf47gjyanq' and md5(grammar) = '6b770c4686e55fa3ac6cc7a427545da2';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)ㄴ 것이다 (explaining)", "level": "Intermediate", "exp": "Explains or sums up what happened: ''what (they) did was ...''. 설치하다 → 설치한 것입니다.", "ex_ko": "실물 크기의 가짜 경찰관 모형을 도로변에 설치한 것입니다.", "ex_en": "What they did was set up life-size fake police officer figures by the road."}, {"name": "~게 만들다", "level": "Intermediate", "exp": "This pattern means ''to make someone/something do something'' or ''to cause a state/action to happen.''", "ex_ko": "운전자들이 경찰관인 줄 알고 속도를 줄이게 만드는 것이 목적입니다.", "ex_en": "The purpose is to make drivers think they are police officers and reduce their speed."}, {"name": "~다고 설명/언급하다", "level": "Intermediate", "exp": "This pattern is used in indirect speech to report what someone said or explained.", "ex_ko": "베트남 당국은 이 방법이 교통사고 예방에 효과적이라고 설명했어요.", "ex_en": "Vietnamese authorities explained that this method is effective in preventing traffic accidents."}]}', updated_at = now() where article_id = 'mocf4sd3gjts' and md5(grammar) = '859818533df10bbeaedb3c997f5cafa1';
update public.article_cache set grammar = '{"patterns": [{"name": "N을/를 위한 + noun", "level": "Beginner", "exp": "''For N'' before a noun. 외국인 학생만을 위한 학과 = ''a department just for foreign students''.", "ex_ko": "외국인 학생만을 위한 새로운 학과 만들어요", "ex_en": "(The university) is creating a new department just for foreign students."}, {"name": "N만 (only)", "level": "Beginner", "exp": "Means ''only, just'' and limits something to that noun. 외국인 학생들만 = ''only foreign students''.", "ex_ko": "이 학과는 외국인 학생들만 들어갈 수 있어요", "ex_en": "Only foreign students can enter this department."}, {"name": "-(으)ㄹ 수 있게 돕다", "level": "Beginner", "exp": "''Help (someone) be able to ...'': 공부하다 → 공부할 수 있게 도와줄 거예요.", "ex_ko": "외국인 학생들이 더 쉽게 공부할 수 있게 도와줄 거예요", "ex_en": "It will help foreign students study more easily."}]}', updated_at = now() where article_id = 'mocffx6amokx' and md5(grammar) = '80c66347c6ae5cf2eafb0f5fabf4fbb6';
update public.article_cache set grammar = '{"patterns": [{"name": "~았/었어요", "level": "Beginner", "exp": "Past tense ending used to describe completed actions or states in casual polite speech.", "ex_ko": "서울에 있는 아트선재센터에서 특별한 전시회가 열렸어요.", "ex_en": "A special exhibition was held at Art Sonje Center in Seoul."}, {"name": "-(으)ㄹ 것 같다", "level": "Beginner", "exp": "Expresses a guess about the future: ''it seems (it) will ...''. 되다 → 될 것 같아요.", "ex_ko": "다양한 문화를 이해하는 기회가 될 것 같아요.", "ex_en": "It seems like it will be a chance to understand different cultures."}, {"name": "~라서", "level": "Beginner", "exp": "Conjunction meaning ''because'' or ''so'' used to show cause and effect relationship.", "ex_ko": "미술관에서 공식적으로 여는 전시회라서 더 의미가 있어요.", "ex_en": "Because it is an official exhibition held by an art museum, it has more meaning."}]}', updated_at = now() where article_id = 'mocfghybmkp8' and md5(grammar) = 'b2d3ec3615abf31f7f4e9f8205860bed';
update public.article_cache set grammar = '{"patterns": [{"name": "~은/는 + 명사 + 이에요", "level": "Beginner", "exp": "This pattern is used to define or identify what something is, equivalent to ''is'' in English.", "ex_ko": "맥심은 한국에서 가장 유명한 인스턴트 커피예요.", "ex_en": "Maxim is the most famous instant coffee in Korea."}, {"name": "-(으)ㄴ + noun (past modifier)", "level": "Beginner", "exp": "Describes a noun with a completed action: 만들다 → 만든 분 ''the person who made (it)''.", "ex_ko": "우리가 매일 마시는 맥심 인스턴트 커피를 만든 분이 세상을 떠났어요.", "ex_en": "The man who created Maxim instant coffee, which we drink every day, has passed away."}, {"name": "N만 -(으)면 (if you just)", "level": "Beginner", "exp": "''If you just ...'': 만 ''only'' + -(으)면 ''if''. 뜨거운 물만 부으면 = ''if you just pour in hot water''.", "ex_ko": "뜨거운 물만 부으면 바로 마실 수 있는 커피예요.", "ex_en": "It''s coffee you can drink right away if you just pour in hot water."}]}', updated_at = now() where article_id = 'mocfiigj3zhm' and md5(grammar) = 'b3c604ac1a04c0ca787e163edeb1b5a8';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Beginner", "exp": "''As'': shows one change going along with another. 유명해지다 → 유명해지면서 ''as (the news) became famous''.", "ex_ko": "늑대 탈출 소식이 유명해지면서 재미있는 일들이 생겼어요.", "ex_en": "As the news of the wolf''s escape spread, some funny things happened."}, {"name": "N도 (even, also)", "level": "Beginner", "exp": "Adds something extra or surprising: ''even, also''. 암호화폐도 만들어졌어요 = ''even a cryptocurrency was made''.", "ex_ko": "이 늑대 이름으로 암호화폐도 만들어졌어요.", "ex_en": "Even a cryptocurrency was created using this wolf''s name."}, {"name": "-았/었어요 (past polite)", "level": "Starter", "exp": "Polite past-tense ending for something that already happened. 탈출하다 → 탈출했어요 ''escaped''.", "ex_ko": "한국의 한 동물원에서 늑대 한 마리가 탈출했어요.", "ex_en": "A wolf escaped from a zoo in Korea."}]}', updated_at = now() where article_id = 'mocfj67yth63' and md5(grammar) = '05bb19a87f8a4de7ac8801cd55931f93';
update public.article_cache set grammar = '{"patterns": [{"name": "-는 것 (nominalizing)", "level": "Intermediate", "exp": "Turns a verb phrase into a noun: ''doing ...''. 쓰고 다니다 → 쓰고 다니는 것 ''going around wearing''.", "ex_ko": "바로 죽은 연어를 머리에 쓰고 다니는 것이었습니다.", "ex_en": "It was this: going around wearing a dead salmon on their heads."}, {"name": "~다고 해요 (reported speech/indirect quotation)", "level": "Intermediate", "exp": "Expresses what someone said or what is said/reported, often used for hearsay or information from others.", "ex_ko": "최근 태평양 북동부 지역의 범고래들이 다시 이 ''연어 모자'' 유행을 따라 하고 있다고 해요.", "ex_en": "It is said that recently orcas in the northeastern Pacific region are again following this ''salmon hat'' trend."}]}', updated_at = now() where article_id = 'moeg3ybr2r2b' and md5(grammar) = '097250d08c6b275d6996d08b89bea8bf';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)려고 하다", "level": "Intermediate", "exp": "Shows an intention or attempt: ''try to, intend to''. 먹다 → 먹으려고 했습니다 ''tried to eat''.", "ex_ko": "이 벌레는 미생물을 먹은 후 다른 벌레<strong>까지 먹으려고 했습니다</strong>.", "ex_en": "After eating microorganisms, this worm even tried to eat other worms."}, {"name": "N 때문이다", "level": "Intermediate", "exp": "Gives the cause after a noun: ''it is because of N''. 구조 때문이에요 = ''it is because of (its) structure''.", "ex_ko": "이런 일이 일어난 이유는 플라나리아의 특별한 구조 <strong>때문이에요</strong>.", "ex_en": "The reason this happens is the planarian''s special structure."}, {"name": "-는 것과 다르다", "level": "Intermediate", "exp": "''Unlike ..., different from ...'': compares with what is usual. 있다 → 있는 것과 달라요.", "ex_ko": "많은 동물들이 입과 항문이 따로 있는 <strong>것과 달라요</strong>.", "ex_en": "This is different from many animals, which have a separate mouth and anus."}, {"name": "-아/어야 하다", "level": "Intermediate", "exp": "Expresses necessity: ''must, have to''. 해결하다 → 해결해야 합니다.", "ex_ko": "플라나리아는 하나의 구멍으로 모든 것을 <strong>해결해야 합니다</strong>.", "ex_en": "The planarian has to do everything through a single opening."}]}', updated_at = now() where article_id = 'moeg4nn7youv' and md5(grammar) = '55aa6ef244267f25ec854545c2ba75b3';
update public.article_cache set grammar = '{"patterns": [{"name": "N마다 (every N)", "level": "Intermediate", "exp": "''Every N'': 여름마다 = ''every summer''. It is often used with 매: 매년 여름마다.", "ex_ko": "인도의 극심한 더위는 매년 여름마다 큰 사회 문제가 되고 있습니다.", "ex_en": "India''s extreme heat becomes a major social problem every summer."}, {"name": "-(으)ㄹ 정도이다", "level": "Intermediate", "exp": "''To the point that ...'': shows how extreme something is. 위험하다 → 위험할 정도입니다.", "ex_ko": "특히 야외에서 일하는 사람들에게는 생명이 위험할 정도입니다.", "ex_en": "Especially for people who work outdoors, it is so hot that it can be life-threatening."}, {"name": "-(으)ㄹ 것이라고 경고하다", "level": "Intermediate", "exp": "Reports a warning about the future: -(으)ㄹ 것이다 (''will'') + -라고 + 경고하다 (''warn''). 나타나다 → 나타날 것이라고.", "ex_ko": "전문가들은 지구 온난화로 인해 이런 극한 기온이 더 자주 나타날 것이라고 경고하고 있어요.", "ex_en": "Experts warn that extreme temperatures like this will occur more often because of global warming."}]}', updated_at = now() where article_id = 'moelbahy6kc1' and md5(grammar) = '2ec7e38b9c3136434350e4e23249b528';
update public.article_cache set grammar = '{"patterns": [{"name": "-는 모습", "level": "Intermediate", "exp": "''The sight of (something) doing ...''. 조립하다 → 조립하는 모습 ''the sight of (it) assembling''.", "ex_ko": "로봇 팔이 정확하고 빠르게 움직이며 작은 부품들을 조립하는 모습이 인상적입니다.", "ex_en": "The sight of the robot arm moving precisely and quickly to assemble small parts is impressive."}, {"name": "-는 과정을 담다", "level": "Intermediate", "exp": "''Capture the process of ...'', used for what a video or photo shows. 조립하다 → 조립하는 과정을 담았어요.", "ex_ko": "이 영상은 로봇이 회로기판을 조립하는 과정을 담았어요.", "ex_en": "This video captured the process of a robot assembling circuit boards."}, {"name": "-(으)며", "level": "Intermediate", "exp": "Written form of ''and, while'': links two actions done together. 움직이다 → 움직이며.", "ex_ko": "로봇 팔이 정확하고 빠르게 움직이며 작은 부품들을 조립하는 모습이 인상적입니다.", "ex_en": "The robot arm moves precisely and quickly as it assembles small parts, which is impressive."}]}', updated_at = now() where article_id = 'moelbxqrojeg' and md5(grammar) = '28a3ee8050aceb55eaa310c906153aa8';
update public.article_cache set grammar = '{"patterns": [{"name": "V-아/어야 한다", "level": "Intermediate", "exp": "Expression indicating necessity or obligation; means ''must do'' or ''have to do''", "ex_ko": "약초를 끓이지 말고 차갑게 우려내야 한다는 사실을 발견했습니다.", "ex_en": "She discovered the fact that medicinal herbs must be steeped cold rather than boiled."}]}', updated_at = now() where article_id = 'moelcki5bw68' and md5(grammar) = '003f5982e3024411b3bb66245de71716';
update public.article_cache set grammar = '{"patterns": [{"name": "-다고 보도하다 (reported news)", "level": "Intermediate", "exp": "Reports what the media said: statement + -다고 + 보도하다 (''report''). 보냈다 → 보냈다고 보도했어요.", "ex_ko": "메타의 최고경영자(CEO) 마크 저커버그가 회사 직원들에게 충격적인 메시지를 보냈다고 외신이 보도했어요.", "ex_en": "Foreign media reported that Meta CEO Mark Zuckerberg sent a shocking message to the company''s employees."}, {"name": "-(으)ㄹ지", "level": "Intermediate", "exp": "''Whether ...'': raises an open question. 있다 → 있을지 주목되다 ''attention is on whether (it) is''.", "ex_ko": "이번 메시지가 회사의 새로운 방향과 관련이 있을지 주목되고 있습니다.", "ex_en": "Attention is on whether this message is related to the company''s new direction."}, {"name": "N일 수 있다", "level": "Intermediate", "exp": "''Could be N'': 이다 → 일 수 있다. 신호일 수 있다 = ''could be a sign''.", "ex_ko": "IT 업계에서는 이런 경영진의 메시지가 회사 정책 변화의 신호일 수 있다고 분석해요.", "ex_en": "The IT industry thinks such a message from management could be a sign of a change in company policy."}]}', updated_at = now() where article_id = 'moeld7tmi3c2' and md5(grammar) = '861304a283794233a5c6e45a3f6da147';
update public.article_cache set grammar = '{"patterns": [{"name": "N에도 불구하고", "level": "Intermediate", "exp": "''Despite N, in spite of N''. 나이에도 불구하고 = ''despite her age''.", "ex_ko": "나이에도 불구하고 놀라운 성과를 보여줘요.", "ex_en": "Despite her age, she shows amazing results."}, {"name": "-다는 것을 보여주다", "level": "Intermediate", "exp": "''Show that ...'': turns a statement into a noun with -다는 것. 불과하다 → 불과하다는 것을 보여줘요.", "ex_ko": "이것은 나이는 숫자에 불과하다는 것을 보여줘요.", "ex_en": "This shows that age is just a number."}, {"name": "-는 계기가 되다", "level": "Intermediate", "exp": "''Become a turning point for ...'', something that triggers a change. 바꾸다 → 바꾸는 계기가 되다.", "ex_ko": "이 사례는 인식을 바꾸는 계기가 되고 있어요.", "ex_en": "This case is becoming a turning point in changing people''s views."}]}', updated_at = now() where article_id = 'moeldtx43cuf' and md5(grammar) = 'ac9b705094db0b4db89038a4e2a651ff';
update public.article_cache set grammar = '{"patterns": [{"name": "-다는 것을 보여줍니다", "level": "Intermediate", "exp": "Used to indicate that something shows or demonstrates a particular meaning or conclusion", "ex_ko": "이는 폭격을 막기 위해 매우 튼튼하게 지었다는 것을 보여줍니다", "ex_en": "This shows that it was built very strongly to prevent bombing"}, {"name": "-았/었을 것으로 추정되다", "level": "Intermediate", "exp": "A formal way to give an estimate about the past: ''it is presumed that ... (happened)''. 세워지다 → 세워졌을 것으로 추정됩니다.", "ex_ko": "이 비밀 본부에서 많은 끔찍한 계획들이 세워졌을 것으로 추정됩니다", "ex_en": "It is presumed that many terrible plans were made at this secret headquarters."}]}', updated_at = now() where article_id = 'mof6dxiyhknc' and md5(grammar) = '6ffc97d8ca7704446e3f5d92cad097a1';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어 있던 + noun", "level": "Intermediate", "exp": "Describes a noun with a state that lasted in the past: 얼다 → 얼어 있다 ''be frozen'' → 얼어 있던 상태 ''the frozen state (it) had been in''.", "ex_ko": "얼어있던 상태였습니다", "ex_en": "It had been in a frozen state."}, {"name": "-을 뿐만 아니라 (not only... but also)", "level": "Intermediate", "exp": "A conjunction expressing ''not only... but also'', used to add additional information or consequences", "ex_ko": "벌레는 다시 살아났을 뿐만 아니라 번식도 했습니다", "ex_en": "The worm not only came back to life but also reproduced"}, {"name": "-는 데 도움이 되다", "level": "Intermediate", "exp": "''Help in doing ...'': 데 here means ''in (doing)''. 이해하다 → 이해하는 데 도움이 됩니다.", "ex_ko": "고대 생물의 생존 능력을 이해하는 데 도움이 됩니다", "ex_en": "It helps us understand how ancient organisms were able to survive."}]}', updated_at = now() where article_id = 'mof6eofsser5' and md5(grammar) = '2d93647fee61793437473c69969bf055';
update public.article_cache set grammar = '{"patterns": [{"name": "-는 이유는", "level": "Intermediate", "exp": "''The reason (that) ... is ...'': 들어가다 → 들어가는 이유는 ''the reason (they) go in''.", "ex_ko": "벌들이 이렇게 쉽게 상자로 들어가는 이유는 간단해요.", "ex_en": "The reason bees go into the box so easily is simple."}, {"name": "-(으)ㄹ 수 없다", "level": "Intermediate", "exp": "Expresses inability or impossibility to do something", "ex_ko": "여왕벌이 없으면 벌 집단은 생존할 수 없어요.", "ex_en": "Without a queen bee, a bee colony cannot survive."}, {"name": "-으려고 하다", "level": "Intermediate", "exp": "Indicates an intention or effort to do something", "ex_ko": "일벌들은 항상 여왕벌 주변에 모여 있으려고 합니다.", "ex_en": "Worker bees always try to gather around the queen bee."}]}', updated_at = now() where article_id = 'mof6fcvthkb0' and md5(grammar) = '2f39d69249b49785053bff02ed7a4631';
update public.article_cache set grammar = '{"patterns": [{"name": "N과/와 다른 + noun", "level": "Beginner", "exp": "''(Something) different from N'': 다르다 → 다른 before a noun. 일반적인 구름과는 다른 형태 = ''a shape different from ordinary clouds''.", "ex_ko": "이 구름은 일반적인 구름과는 다른 독특한 형태를 보였습니다.", "ex_en": "This cloud had a unique shape, different from ordinary clouds."}, {"name": "V-어야 하다", "level": "Intermediate", "exp": "Necessity or requirement, indicates what must be done or what must happen", "ex_ko": "기온과 습도, 바람의 방향이 모두 맞아떨어져야 합니다.", "ex_en": "Temperature, humidity, and wind direction must all align perfectly."}]}', updated_at = now() where article_id = 'mof6g31zi250' and md5(grammar) = 'ea84bac493926e7fc91dc34d6274c7fe';
update public.article_cache set grammar = '{"patterns": [{"name": "-게 하다", "level": "Intermediate", "exp": "''Make (something) ...'': causes a result. 가능하다 → 가능하게 했습니다 ''made (it) possible''.", "ex_ko": "정상 출산을 가능하게 했습니다.", "ex_en": "(It) made a normal birth possible."}, {"name": "-(으)ㄹ 수 있었어요", "level": "Intermediate", "exp": "Past tense form expressing that something was possible or able to happen", "ex_ko": "산모는 자연분만을 할 수 있었어요.", "ex_en": "The pregnant woman was able to have natural childbirth."}, {"name": "-은/는 것은 아니다", "level": "Intermediate", "exp": "Negates or qualifies a statement, meaning ''it is not the case that'' or ''not necessarily''", "ex_ko": "모든 경우에 성공하는 것은 아니에요.", "ex_en": "It is not the case that it succeeds in all cases."}]}', updated_at = now() where article_id = 'mof6grzq6oc1' and md5(grammar) = '44e75fa070ad37009456a88e45eaf5e9';
update public.article_cache set grammar = '{"patterns": [{"name": "-기(가) 쉽다", "level": "Beginner", "exp": "Says an action is easy to do: ''easy to ...''. 쌓다 → 쌓기가 쉬워요 ''easy to stack''.", "ex_ko": "네모나서 쌓기가 쉬워요.", "ex_en": "It is square, so it is easy to stack."}, {"name": "N 때문에", "level": "Beginner", "exp": "''Because of N'': put 때문에 directly after a noun. 특별한 모양 때문에 = ''because of its special shape''.", "ex_ko": "특별한 모양 때문에 인기가 많아요.", "ex_en": "It is popular because of its special shape."}, {"name": "-기도 하다", "level": "Beginner", "exp": "Adds another fact: ''also, sometimes''. 팔다 → 팔기도 해요 ''(they) also sell (it)''.", "ex_ko": "백화점이나 과일가게에서 팔기도 해요.", "ex_en": "It is also sold at department stores or fruit shops."}]}', updated_at = now() where article_id = 'mof6hf7adm4y' and md5(grammar) = 'c9bdb8b24394db27605caabcbdaa483d';
update public.article_cache set grammar = '{"patterns": [{"name": "-아/어지다 (passive)", "level": "Beginner", "exp": "Makes a verb passive: 만들다 ''make'' → 만들어지다 ''be made''; 만들어진 것 = ''a thing that was made''.", "ex_ko": "이 온수기는 지금부터 약 2천 년 전에 만들어진 것이에요.", "ex_en": "This water heater was made about 2,000 years ago."}, {"name": "-다는 것을 알 수 있다", "level": "Beginner", "exp": "Draws a conclusion: ''we can tell that ...''. 사용했다 → 사용했다는 것을 알 수 있어요.", "ex_ko": "로마 시대 사람들도 우리처럼 따뜻한 물을 사용했다는 것을 알 수 있어요.", "ex_en": "We can tell that people in Roman times also used warm water, just like us."}, {"name": "-거든요", "level": "Beginner", "exp": "A sentence ending that gives the reason or background for what was just said: ''you see, because''. 남아 있다 → 남아 있거든요.", "ex_ko": "물을 데우는 관과 연결 부품들이 모두 완전한 상태로 남아 있거든요.", "ex_en": "That''s because the pipes that heat the water and the connecting parts are all still intact."}]}', updated_at = now() where article_id = 'mof6i16d2jid' and md5(grammar) = '2762011068aa864bc47c968e38ab1c38';
update public.article_cache set grammar = '{"patterns": [{"name": "-ㄴ/는다는 사실", "level": "Intermediate", "exp": "''The fact that ...'': turns a statement into a noun. 지키다 → 지킨다는 사실을 알고 있나요? ''Do you know (the fact) that ... keep ...?''", "ex_ko": "숲에서 나무들이 서로의 공간을 지킨다는 사실을 알고 있나요?", "ex_en": "Did you know that trees in a forest respect each other''s space?"}, {"name": "-기 위해서", "level": "Intermediate", "exp": "Expresses purpose: ''in order to''. 받다 → 받기 위해서예요 ''it''s in order to receive''.", "ex_ko": "나무들이 햇빛을 더 많이 받기 위해서예요.", "ex_en": "It''s so that the trees can get more sunlight."}, {"name": "-는 것처럼 보이다", "level": "Intermediate", "exp": "''Look as if ...'': describes how something appears. 배려하다 → 배려하는 것처럼 보입니다.", "ex_ko": "마치 사람들이 서로를 배려하는 것처럼 보입니다.", "ex_en": "It looks just as if people were being considerate of each other."}]}', updated_at = now() where article_id = 'mof6iqm2v1ga' and md5(grammar) = '0ed96e912106fb03696b8039c1dcb7db';
update public.article_cache set grammar = '{"patterns": [{"name": "~라고 불렸는데 (Past passive + ~라고)", "level": "Intermediate", "exp": "Used to indicate what something was called or named in the past", "ex_ko": "이 배는 ''뷔스텐쉬프(Wustenschiff)''라고 불렸는데, 독일어로 ''사막의 배''라는 뜻이에요.", "ex_en": "This ship was called ''Wustenschiff,'' which means ''desert ship'' in German."}, {"name": "-(으)ㄹ 만큼", "level": "Intermediate", "exp": "''Enough to ..., to the extent that ...''. 태울 수 있다 → 태울 수 있을 만큼 컸습니다 ''was big enough to carry''.", "ex_ko": "승객 300명을 태울 수 있을 만큼 컸습니다.", "ex_en": "It was big enough to carry 300 passengers."}, {"name": "~지는 않았지만 (Past negative + contrast)", "level": "Intermediate", "exp": "Used to express a negative action in the past while introducing a contrasting idea", "ex_ko": "이 계획은 실제로 만들어지지는 않았지만, 사막을 건너는 새로운 교통수단을 생각해낸 흥미로운 아이디어였어요.", "ex_en": "Although this plan was never actually built, it was an interesting idea that conceived a new transportation method across the desert."}]}', updated_at = now() where article_id = 'mof6k0s7baf2' and md5(grammar) = 'f1fc782856898e584351335721836959';
update public.article_cache set grammar = '{"patterns": [{"name": "-을/를 두고", "level": "Intermediate", "exp": "This pattern means ''over/regarding something'' or ''concerning something''. It indicates the subject of conflict or discussion.", "ex_ko": "영국과 아르헨티나가 영유권을 두고 갈등을 벌이는", "ex_en": "Britain and Argentina are in conflict over territorial rights"}, {"name": "-을/를 기회로 보다", "level": "Intermediate", "exp": "This pattern means ''to see/view something as an opportunity''. It expresses how someone perceives a situation.", "ex_ko": "아르헨티나는 이를 기회로 보고 있는 것 같습니다", "ex_en": "Argentina seems to be viewing this as an opportunity"}]}', updated_at = now() where article_id = 'mof9vz1w668g' and md5(grammar) = '019114b3b9825a35fa93bcbde300230f';
update public.article_cache set grammar = '{"patterns": [{"name": "Past tense with -았어요/었어요", "level": "Beginner", "exp": "Used to describe completed actions or past events in casual polite speech", "ex_ko": "보츠와나에서 중요한 변화가 있었어요.", "ex_en": "There was an important change in Botswana."}, {"name": "N 때문에", "level": "Beginner", "exp": "''Because of N'': put 때문에 directly after a noun. 이 법 때문에 = ''because of this law''.", "ex_ko": "많은 사람들이 이 법 때문에 차별을 받았어요.", "ex_en": "Many people faced discrimination because of this law."}, {"name": "Prospective with -ㄹ 것 같아요", "level": "Beginner", "exp": "Used to express a guess or prediction about the future", "ex_ko": "보츠와나의 결정이 다른 나라들에게도 영향을 줄 것 같아요.", "ex_en": "Botswana''s decision seems likely to influence other countries too."}]}', updated_at = now() where article_id = 'mof9wunkuv3r' and md5(grammar) = '7d60687b493f9c320a8d52ec58cbc86e';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Intermediate", "exp": "''As'': shows one development going along with another. 장기화되다 → 장기화되면서 ''as (it) drags on''.", "ex_ko": "러시아의 우크라이나 침공이 장기화되면서 서방 국가들에 대한 위협이 커지고 있어요", "ex_en": "As Russia''s invasion of Ukraine drags on, the threat to Western countries is growing."}, {"name": "-아/어 (short for -아/어서)", "level": "Beginner", "exp": "In writing, -아/어서 ''because'' is often shortened to -아/어: 접하고 있어 = ''because (it) borders''.", "ex_ko": "폴란드는 우크라이나와 국경을 접하고 있어 안보 위협을 직접적으로 느끼고 있습니다", "ex_en": "Because Poland borders Ukraine, it feels the security threat directly."}]}', updated_at = now() where article_id = 'mof9xpiphztk' and md5(grammar) = '4500b93aae16987b870b05f263fce15e';
update public.article_cache set grammar = '{"patterns": [{"name": "-다는 사실이 드러나다", "level": "Advanced", "exp": "Reports that a hidden fact has come out: ''it has been revealed that ...''. 심각했다 → 심각했다는 사실이 드러났어요.", "ex_ko": "이란이 미군 기지에 가한 피해가 공개된 것보다 훨씬 심각했다는 사실이 드러났어요.", "ex_en": "It has been revealed that the damage Iran caused to the US military base was far more serious than what was made public."}, {"name": "-(으)ㄹ 가능성을 제기하다", "level": "Advanced", "exp": "''Raise the possibility that ...'': 광범위했다 → 광범위했을 가능성 ''the possibility that (it) was widespread''.", "ex_ko": "군사 전문가들은 실제 손상이 더 광범위했을 가능성을 제기하고 있습니다.", "ex_en": "Military experts are raising the possibility that the actual damage was more widespread."}, {"name": "-(으)면서", "level": "Advanced", "exp": "''As'': shows one development going along with another, often as its cause. 지속되다 → 지속되면서 ''as (it) continues''.", "ex_ko": "미국과 이란 간의 갈등이 지속되면서 국제 사회의 우려가 커지고 있습니다.", "ex_en": "As the conflict between the United States and Iran continues, international concern is growing."}]}', updated_at = now() where article_id = 'mof9ynldhr54' and md5(grammar) = '04bd0184fac5a18ba780c83de04f00ec';
update public.article_cache set grammar = '{"patterns": [{"name": "V + -고 있다", "level": "Beginner", "exp": "Expresses an ongoing or continuous action in the present", "ex_ko": "미국에서 사형 집행이 늘어나고 있어요.", "ex_en": "Capital punishment executions are increasing in the United States."}, {"name": "N(이)라고 말하다", "level": "Beginner", "exp": "Reports what someone said when the statement ends in a noun: 것이다 → 것이라고 말했어요 ''said that it is ...''.", "ex_ko": "교황은 사형제도가 잘못된 것이라고 말했어요.", "ex_en": "The Pope said that the death penalty is wrong."}, {"name": "-지만", "level": "Beginner", "exp": "Connects two contrasting clauses: ''but, although''. 있다 → 있지만.", "ex_ko": "한국도 사형제도가 있지만 실제로는 집행하지 않고 있어요.", "ex_en": "Korea also has the death penalty, but it does not actually carry out executions."}]}', updated_at = now() where article_id = 'mof9zmwhsyl5' and md5(grammar) = '4e76deedbdf491c1c0463959ddd1107d';
update public.article_cache set grammar = '{"patterns": [{"name": "~인 척하며", "level": "Intermediate", "exp": "pretending to be; acting as if one is. Combines ~인 척 (pretending to be) with ~며 (while doing)", "ex_ko": "그는 ''위험한 정신병자''인 척하며 정신병원에 들어갔습니다.", "ex_en": "He entered the mental hospital while pretending to be a ''dangerous mentally ill person.''"}, {"name": "-(으)ㄴ 것이었다", "level": "Intermediate", "exp": "Names what something was by turning a whole clause into a noun: ''it was that ...''. 바뀌다 → 바뀐 것이었어요 ''was that (the law) changed''.", "ex_ko": "더 중요한 것은 법이 바뀐 것이었어요.", "ex_en": "What was more important was that the law changed."}, {"name": "~고 싶었어요", "level": "Beginner", "exp": "wanted to; past tense of ~고 싶다 expressing a desire or wish that existed in the past", "ex_ko": "체임버스는 이런 문제를 직접 확인하고 싶었어요.", "ex_en": "Chambers wanted to directly confirm these problems."}]}', updated_at = now() where article_id = 'mofavbgj2kuk' and md5(grammar) = '3a172af233c709a4749fa5429f3d591f';
update public.article_cache set grammar = '{"patterns": [{"name": "V + 을/ㄹ 수 있게 만들다", "level": "Advanced", "exp": "To make something in a way that allows a certain action to be possible; to design/construct something to enable a specific capability", "ex_ko": "3대의 대형 폭격기를 접을 수 있게 만들어서 탑재할 수 있었습니다.", "ex_en": "It was made in a way that allowed three large bombers to be folded and loaded."}, {"name": "-(으)면서", "level": "Intermediate", "exp": "''As, with'': shows one event happening along with another, often as its cause. 항복하다 → 항복하면서 ''as (Japan) surrendered''.", "ex_ko": "잠수함이 완성된 직후 일본이 항복하면서 모든 공격 계획이 중단되었습니다.", "ex_en": "Right after the submarine was finished, Japan surrendered, and all attack plans were called off."}, {"name": "N을/를 이용해(서)", "level": "Intermediate", "exp": "''Using N, by means of N''. 이 잠수함을 이용해 = ''using this submarine''.", "ex_ko": "일본은 이 특수 잠수함을 이용해 미국 샌프란시스코를 공격할 계획을 세웠어요.", "ex_en": "Japan made a plan to attack San Francisco using this special submarine."}]}', updated_at = now() where article_id = 'mofaw5kqi8d4' and md5(grammar) = '46821887a191fe2a0c20b67acdc90422';
update public.article_cache set grammar = '{"patterns": [{"name": "V-고 있어요", "level": "Intermediate", "exp": "Indicates an ongoing action or current state in the present tense with a polite tone.", "ex_ko": "일본 후쿠시마 제1원자력발전소가 관광지로 변화하고 있어요.", "ex_en": "The Fukushima Daiichi Nuclear Power Plant is changing into a tourist destination."}, {"name": "N을/를 통해", "level": "Intermediate", "exp": "''Through N, by way of N'': marks the means. 재해 관광을 통해 = ''through disaster tourism''.", "ex_ko": "재해 관광을 통해 교육 효과를 높이려고 해요.", "ex_en": "They are trying to boost the educational effect through disaster tourism."}, {"name": "V-으면서", "level": "Intermediate", "exp": "Expresses two actions happening simultaneously or at the same time.", "ex_ko": "관광객들이 직접 현장을 보면서 원자력 에너지 정책을 이해할 수 있어요.", "ex_en": "Tourists can understand nuclear energy policy while directly seeing the site."}]}', updated_at = now() where article_id = 'mofaxqlzns4g' and md5(grammar) = '688ffefab34fe008a401abdf5ffdf552';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)며", "level": "Intermediate", "exp": "Written form of ''and, while'': links two actions or facts. 기록하다 → 기록하며 ''set (a record) and''.", "ex_ko": "역대 최고치를 기록하며 전 세계적인 한국어 학습 <strong>열풍을 실감케 했다</strong>", "ex_en": "set an all-time high, showing just how strong the global Korean-learning boom is"}, {"name": "-게 하다 (written -케 하다)", "level": "Intermediate", "exp": "Causative ''make (someone) ...'': 실감하다 + -게 하다 → 실감하게 하다, shortened in writing to 실감케 하다 ''made (people) really feel''.", "ex_ko": "전 세계적인 한국어 학습 열풍을 <strong>실감케 했다</strong>", "ex_en": "made (people) really feel the global boom in Korean learning"}]}', updated_at = now() where article_id = 's10' and md5(grammar) = '507a562ef2b76a1255c9b00d513d4e35';
update public.article_cache set grammar = '{"patterns": [{"name": "V-면서", "level": "Intermediate", "exp": "Connects two actions happening simultaneously or in sequence; ''while doing'' or ''as''", "ex_ko": "삼성전자가 차세대 AI 반도체 양산에 돌입하면서 엔비디아와 대규모 공급 계약을 체결했다.", "ex_en": "As Samsung Electronics entered mass production of next-generation AI semiconductors, it concluded a large-scale supply contract with NVIDIA."}]}', updated_at = now() where article_id = 's11' and md5(grammar) = 'c1959ed928d39a9af1e44fd9d9b1e0ea';
update public.article_cache set grammar = '{"patterns": [{"name": "-(으)면서", "level": "Intermediate", "exp": "Connective ending indicating two actions occurring simultaneously or one action triggering another", "ex_ko": "새로운 국제 기후 협약이 서명되면서 한국은 탄소중립 목표 시점을 2045년으로 앞당겼다.", "ex_en": "As the new international climate agreement was signed, Korea brought forward its carbon neutrality target to 2045."}]}', updated_at = now() where article_id = 's14' and md5(grammar) = '6982fdb4a7e8c26abe6cf10f30f98fe0';
update public.article_cache set grammar = '{"patterns": [{"name": "명사 + 이/가 (Subject Particle)", "level": "Beginner", "exp": "This particle marks the subject of a sentence. It shows what or who is doing the action.", "ex_ko": "BTS 월드투어 서울 공연 티켓<strong>이</strong> 판매 시작 수분 만에 전석 매진되면서", "ex_en": "BTS world tour Seoul concert tickets sold out within minutes of sales starting"}, {"name": "-(으)면서", "level": "Beginner", "exp": "''As'': shows one event happening along with another, often as its cause. 매진되다 → 매진되면서 ''as (the tickets) sold out''.", "ex_ko": "전석 매진되<strong>면서</strong> 소속사가 추가 공연 개최를 검토하고 있다.", "ex_en": "As every seat sold out, the agency is considering holding more concerts."}, {"name": "명사 + 을/를 (Object Particle)", "level": "Beginner", "exp": "This particle marks the direct object of a verb, showing what or who receives the action.", "ex_ko": "소속사가 추가 공연 개최<strong>를</strong> 검토하고 있다.", "ex_en": "The agency is reviewing the holding of additional performances"}, {"name": "동사 + 고 있다 (Progressive/Continuous Action)", "level": "Beginner", "exp": "This shows an action that is currently in progress or an ongoing state. It means ''is doing'' or ''is in the process of''.", "ex_ko": "소속사가 추가 공연 개최를 검토하<strong>고 있다</strong>.", "ex_en": "The agency is (currently) reviewing additional performances"}]}', updated_at = now() where article_id = 's8' and md5(grammar) = '3bb4057f65ac1880b8c3dbf09bdf7ff9';
